/* 平成21年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h21.committeeSessions.push(...[{"id":"h21-20090312-3","meetingId":"h21-c-budget","date":"2009年3月12日","dateIso":"2009-03-12","committee":"予算特別委員会","time":"午前１０時０２分～午後６時２４分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を174件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"原委員","kind":"質問・要望","question":"今日も暑く委員長がお思いになるぐらいの緊張した質疑をさせていただきたいと思います。プレス発表資料の３７ページの八潮プロジェクト、この辺から伺っていきたいと思います。２３１ページです。特別養護老人ホーム等の「等」、それから、八潮南中学校、ずっと来まして、ホーム等、あと、高齢者住宅等、それから施設管理費等、この辺の「等」についてのご説明を、簡単で結構ですから、いただきたい。","respondent":"冨岡高齢福祉課長、日下部企画財政課長","answer":"２３１ページの表記の「等」の関係です。都市計画の見直しですが、これにつきましては、一応今、予定どおり手続きを進めているという状況です。","voiceIndex":4,"id":"exchange-001"},{"speaker":"原委員","kind":"質問","question":"非常によくわかりました。それで、ここのプロジェクトに関しまして、まずお聞きしたいのは、建築関係、これは改修ということなんですけれども、年数が経っているからということなんでしょうけれども、国、都の割合が６０％と４０％になっておりますけれども、これ、もし新築をしていたらばというようなお考えというのが出たか、出なかったか。","respondent":"日下部企画財政課長","answer":"八潮南中学校跡、八潮南小学校もそうですが、実は、まだ築２５年ということで、手入れも結構しっかりしてきておりますので、できるだけ既存のものを大切に使っていこうということで、これは改修によりまして、活用を図っていくという、これが基本的な考え方です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"原委員","kind":"質問","question":"これはもう１点、答えとしては、新築で計算されたかどうかという点だけ、ご答弁がなかったので、お願いします。","respondent":"宍戸施設担当課長","answer":"新築で行った場合は、約２倍ぐらいの経費がかかるのではないかと試算しております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"原委員","kind":"質問","question":"今、２倍というお話だったんですけれども、これは多分、建築物ですのでかなり大幅な差が出ると思うんですけれども、２倍というのは高いほうで見積もったのかなということですので、考えていた質問から、次、先にいきます。出てくる公の施設についてご説明をいただけますでしょうか。この内容をもう少し説明をしますと、プレスに発表している公の施設という意味です。","respondent":"日下部企画財政課長","answer":"公の施設ということでありますけれども、私ども、幅広く使っておりますが、基本的には区民サービスとして提供する、公共目的の施設ということで位置づけをしています。","voiceIndex":11,"id":"exchange-004"},{"speaker":"原委員","kind":"質問","question":"何か法的な関係の規制とか、そういった面がありますでしょうか。わかればで結構です。わからなければ、次を進めていきます。","respondent":"日下部企画財政課長","answer":"公の施設につきましては、たしか地方自治法第２４４条、この辺を中心にしまして、必要な規定がなされている。これに基づきまして、区としても公の施設の整備運営等を図っているというものです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"原委員","kind":"質問・要望","question":"ご丁寧にありがとうあります。ですから、逆に言えば、パーセンテージが、もし、これが新築だった場合にはどうなるのかなというお伺いをさせていただきたかったんですね。６０％対４０％ではなくなるのかどうか。もしくは、その都度、協議なのか。その辺、もしおわかりでしたら、お願いしたいんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"},{"speaker":"原委員","kind":"質問・要望","question":"何でそういったことをいろいろと申し上げてきたかといいますと、施設の関係でありますけれども、ここは大事なポイントかと思うんですが、確認をさせていただきたいということで、１ベッド当たり多分２００万円ぐらいのお金がおりてくるかと思うんですね。これは当然区がつくっていくわけですから、区のほうに来るのか。は今回の場合は、指定管理者制度というのをとっているので、実際には運営側なのかどうか。","respondent":"冨岡高齢福祉課長","answer":"都の補助金は１億５,０００万円ぐらいです。それは区のほうに入ってまいります。","voiceIndex":17,"id":"exchange-007"},{"speaker":"原委員","kind":"確認","question":"区のほうということで、安心しました。というのは、要は、基本的に、さっき言った新築をするよりも、年数も経ってないからということなんですけれども、私、現地を確認したら、大分クラックも入っているんですね。それで、当然に建替えよりも改修工事のほうがよりよかったと、効率的であるというようなところまで判断をしてほしかったということで、以上、お願いで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-008"},{"speaker":"山路委員","kind":"質問","question":"もう１点は、２３７ページ、病児保育についてお伺いをいたします。病児保育につきましては、品川・大井地区のお母さん方に強い希望を与えるものだと、その努力に対して非常に私も高く評価しているわけですが、この病児保育の２カ所で、本年度、ケアといいますか、サポートといいますか、そういう内容についてどういう展開をされていくか、お伺いいたします。","respondent":"冨岡高齢福祉課長、小林保育課長","answer":"この部分につきましては、今、原小学校跡に建てましたケアホーム、これにつきましても、高齢者向け優良賃貸住宅制度を活用した制度でございまして、今回、予定をしております大井林町跡につきましては、ケアホームというよりは。ご質問のございましたケアという点では、１つは、各施設が有機的に連携して対応していくという点でのケア、あるいは、保育園、看護師もおりますので、そういった育児。","voiceIndex":21,"id":"exchange-009"},{"speaker":"山路委員","kind":"質問・要望","question":"ここで、全国初と言われている、昨年、都の第１回定例会で、我が党が要望いたしましたが、昨年から補助制度になりました訪問看護ステーション、これが非常に全国的にこれから注目をされていくのではないかと、一体化の中にできるということで、この医療と介護について、どのような展開を考えていらっしゃるのか、お伺いいたします。","respondent":"冨岡高齢福祉課長","answer":"これから用地を取得する段階ですので、今後、詳細につきましては、基本計画、基本設計という順番で進めてまいるところですが、現在、プレスの発表に出させていただきましたように、訪問看護ステーション等につきましても、これは一応現在の段階では考えているということで。","voiceIndex":24,"id":"exchange-010"},{"speaker":"山路委員","kind":"質問","question":"病児保育ですが、いざというときにお母さんたちの強い味方になりますので、今後ともどうぞよろしくお願い申し上げます。それとも大きく変わっていくのか。この辺についてお伺いいたします。","respondent":"冨岡高齢福祉課長","answer":"高齢者向けの優良賃貸住宅の制度ですので、６０歳以上の方で、当然品川区民ということは前提にしています。","voiceIndex":26,"id":"exchange-011"},{"speaker":"山路委員","kind":"質問・要望","question":"居宅介護、訪問看護ステーション、これが非常に安心に、安全に、品川に住み続けたいという夢がかなってくるのかなという希望があると思うんですね。でも、多くの方を考えた場合に、もっと安く、高齢者専用賃貸住宅というのが新たに今、話題になりつつありますが、この辺のところまで将来考えられていらっしゃるかどうか、もう一度お知らせをいただきたいと思います。","respondent":"冨岡高齢福祉課長","answer":"高齢者の住まいのあり方については、今後引き続きさまざまなあり方を検討させていただきたいと考えております。","voiceIndex":28,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"新規事業ですけれども、まず、公設公営で考えているのか、運営について伺いたいのと、あと、利用料についてでありますが、同じ高優賃の制度を使った原小学校跡と同じく、家賃分と介護保険上の自己負担分とその他諸経費、基本サービス、共益費、この３要素で構成する、そういう考えなのか、ご説明ください。","respondent":"冨岡高齢福祉課長","answer":"この施設ですけれども、用地の取得から始めまして、公設を考えておりますが、運営につきましては、今後検討を進めてまいりたいと考えています。","voiceIndex":31,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"違いがあればご説明いただきたい。高齢者住宅の整備について、東京新聞に載って、これを見た７４歳の高齢者から、「これは一体幾らなのか。２０万円も３０万円もするようじゃ、私たちは入れない。利用料設定についての考え方、幾らぐらいの設定を想定しているのか、教えていただきたい。同じく品川区の助成による独自家賃の軽減制度を設ける考えなのか、あわせてご説明いただけますか。","respondent":"冨岡高齢福祉課長","answer":"高優賃制度ですので、助成金につきましては、大いに活用できるものは活用してまいりたいと考えています。それから、ほかの部分、今後どうするかということは、軽減の部分ですけれども、これは今後の検討の課題であるです。","voiceIndex":33,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"利用料、使用料、幾らぐらいの設定なのかということなのでご説明いただきたい。これが区民の率直な実態だと思うんですね。自治体が所得の少ない区民を排除するような、こういう利用料設定はやめるべきだと思うんですけれども、そのお考えを教えていただきたい。ぜひ原小学校跡と同じく、軽減制度をお考えいただきたいと思うんですけれども、いかがでしょうか。","respondent":"冨岡高齢福祉課長","answer":"それにあわせて、利用料につきましても、そういうさまざまな条件の中から、いろいろな角度から総合的に判断して、最終的に決めていくべきだと思いますので、どの程度ということは今の段階ではお答えできません。","voiceIndex":35,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"利用料については、総合的に検討したいということですけれども、その総合的とはどういう要素なのか、ご説明いただきたい。今一つこのコンセプトがよくわからない。だれを対象としているのかわからない。総合的の要素をご説明いただけますか。","respondent":"冨岡高齢福祉課長","answer":"利用料の設定ですけれども、これにつきましては、例えば所在地の近傍の家賃よりは高くしてはいけないとかというような部分、それから、どういうサービスを提供していくのかという部分、それから、現在利用されている施設がどのような形態で利用料をいただいているのかという部分。","voiceIndex":37,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"高齢者の厳しい生活実態、そこをしっかり利用料の中でも見ていくべきだと思うんですね。そこがよくわからないので、ご説明いただきたい。先ほども伺いましたけれども、自治体が所得の少ない区民を使用料で排除する。こういう考えを持ち込むべきではないと思うんですけれども、そこについてもはっきりご答弁いただきたいと思います。私はぜひ軽減制度を考えるべきだと思いますけれども、いかがでしょうか。","respondent":"木下福祉高齢事業部長","answer":"具体的に家賃をどうするかという部分については、今後建設コストも含めまして、またどういうような運営をしていくかということも含めまして、検討する中で、その辺は詰めていきたいということでありますので、原小学校跡と比較しながらの論議というのは。","voiceIndex":39,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"結局はご説明を伺っても、区民の厳しい実態を全く見ようとしない、その姿勢だと思います。相次ぐ増税負担増、この厳しい生活状況、高齢者のぎりぎりな生活状況をしっかりつかんでいただいて、利用料を定めていただきたいと思います。重ねて軽減制度をよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-018"},{"speaker":"稲川委員","kind":"質問","question":"私はソフトな質問をします。２１３ページの高齢者生きがい対策事業の中にあります高齢者の趣味・健康づくり事業についてお伺いいたします。この中に４項目ございまして、高齢者作品展、ゲートボール大会、シルバーダンスパーティー、いきいきカラオケ広場等ありますが、今後、健康、趣味の観点で考えて、これはまた増えていくのか、どうなのか。","respondent":"永尾高齢事業課長","answer":"今後の趣味・健康づくり事業についてですが、現在、作品展、ダンス、ゲートボール、カラオケともに好評で、それぞれ参加された方からは、もっと充実してほしいというようなアンケート等はいただいておりますので、ただ。","voiceIndex":43,"id":"exchange-019"},{"speaker":"稲川委員","kind":"質問・要望","question":"ぜひ充実をさせてください。そして、開催場所なんですが、４件あるんですが、これは簡単にお答えいただきたいんですが、どういった場所で開催をしているのか。高齢者作品展だけが９８万円ということで、１００万円近い予算なんですが、会場費になっているのかどうなのか、その辺、教えてください。","respondent":"永尾高齢事業課長","answer":"年に１回ということです。ダンスパーティーにつきましては、きゅりあんのイベントホールで開催しております。こちらも年に１回、秋に開催ということです。ゲートボールにつきましては、西大井広場公園で行っております。カラオケにつきましては、店舗との契約になっております。","voiceIndex":45,"id":"exchange-020"},{"speaker":"稲川委員","kind":"質問","question":"審査員の費用だけでこれだけ額がいってしまうというのは、なかなかちょっと考えづらい部分で、むしろカラオケ店と契約したほうがお金がかかるのではないかなと、そういう思いがあるんですが、それはいいといたしまして、この中のゲートボール大会についてお伺いいたします。","respondent":"永尾高齢事業課長","answer":"区内のクラブ数は、申しわけありません、把握してないんですけれども、ゲートボール大会の参加のチームは２４チームになっております。","voiceIndex":49,"id":"exchange-021"},{"speaker":"稲川委員","kind":"質問","question":"例えばゲートボールというのは、ほかのものに比べて持ち物が結構多くて、自転車で来られている方も多いと思うんですが、よく遠いから行かないという、大会とかに行くとそういう方もいらっしゃるんですが、西大井広場公園でやるだけというよりは、西大井広場公園は何面もとれる広い公園ですが、例えば北品川のほうとか、荏原のほうとかでもやるべきだと。","respondent":"永尾高齢事業課長","answer":"ゲートボールにつきましては、音の問題もかなりございまして、近隣の方が、あのカーンという音がうるさいとか、そういうこともありますので、その辺のことも考慮しながら場所を考えているところです。","voiceIndex":51,"id":"exchange-022"},{"speaker":"稲川委員","kind":"質問・要望","question":"大会となると、しかも、生きがいの中での健康づくりと、区が主催をしているのであれば、ゲートボールをやられている方がみんな参加できる。生きがいという観点から考えたときに、大会などに子どもたち、中学生なのか、小学生なのかは別にしても、一緒になって参加することも高齢者にとって最大の生きがいではないかなと私は考えているんですが、いかがお考えですか。","respondent":"永尾高齢事業課長","answer":"現在、グラウンドゴルフ等でお年寄りとも一緒にやるような事業もやっておりまして、例えば輪投げなんかもやっているというような状況ですので、こちらのゲートボールについても、どういうふうにやったらいいかということは、考えていきたいと思います。","voiceIndex":53,"id":"exchange-023"},{"speaker":"山内委員","kind":"質問","question":"私のほうから、２３７ページ、児童措置費の児童手当の支給、それから、２１１ページの社会福祉費の訪問介護員雇用・訪問介護員２級資格取得助成、それから、２１５ページの高齢福祉費の家具転倒防止対策助成についてお伺いいたします。教えてください。","respondent":"諸岡児童課長","answer":"所得によりまして、これは非常に細かく１０円刻みで規定されておりまして、一番少ない方が９,８５０円、また、所得によって、もちろん出ない方もいますけれども、支給される方で一番少ない方が９,８５０円、こういうような制度です。","voiceIndex":56,"id":"exchange-024"},{"speaker":"山内委員","kind":"質問","question":"今の児童扶養手当の一部支給のところで、これは母子家庭のみで、所得制限があるというか、所得が多い人は一部支給、そういう考え方でいいんですか。","respondent":"諸岡児童課長","answer":"規定の所得を超えますと、児童扶養手当は出ません。所得ごとに階層がありまして、これは非常に細かく、１０円刻みです、一番所得の少ない方等につきましては、満額の月額４万１,７２０円、こういう金額で現在実施しております。","voiceIndex":58,"id":"exchange-025"},{"speaker":"山内委員","kind":"質問","question":"税金を納めなければならないといった中で、ちょっと困ってしまったというアンケートがあったんですけれども、例えば支給されるときに、通知の書面か、何かそういうのでもいいんですけれども、これは課税対象ですよということがわかっていれば、それなりの気持ちにも余裕というか、あるのかなと思うんですけれども、いきなり来られちゃうと。","respondent":"諸岡児童課長","answer":"これは私ども、品川税務署等を通しまして、協議依頼をして、国の法に基づく児童手当と同じ目的で子育て世代の経済的支援のために支給しているので、相談させていただけないかということで、協議依頼を申し上げたんですが、税務署のほうとしては。","voiceIndex":60,"id":"exchange-026"},{"speaker":"山内委員","kind":"質問・要望","question":"わかりました。では、続きまして、２１１ページの訪問介護員雇用と２級資格の取得の助成について伺いますけれども、本会議でも質問はさせていただいたんですけれども、これは非常にすばらしい、画期的な施策だと私も思っております。そんな中で、事業所がたくさんありますけれども、例えば平成２０年度内に事業所で申し込みをされた、区内の事業所と区外の事業所の内訳は何かありますか。","respondent":"冨岡高齢福祉課長","answer":"事業所については、対象を区内としておりますので、基本的に区内です。","voiceIndex":62,"id":"exchange-027"},{"speaker":"山内委員","kind":"質問","question":"外国人介護士の質問を本会議でさせていただいたんですけれども、答弁の中で、将来的には事業所のニーズがあれば、受け入れを推進していくというようなご答弁をいただいたと思うんですけれども、今、品川区には品川介護福祉専門学校が中小企業センターの中にありますけれども、そこに、例えば定住者の外国人の方が将来的に介護の仕事をしたいということで。","respondent":"冨岡高齢福祉課長","answer":"入学については制限を設けていないと思いますけれども、実際、区内等で働いていただく場合には、まだ環境が整っていないということで、実際問題として、就職につながってこないということがあれば。","voiceIndex":64,"id":"exchange-028"},{"speaker":"山内委員","kind":"意見","question":"そういう人たちの門戸を開かないというか、それはちょっといかがなものなのかなと思うんですけれども、そういう人が出てきたときは、速やかに入学してもらって、勉強をしてもらうということも、今後を見据えますと、非常にいいことなのかなと思うんですけれども、どうなんでしょう。","respondent":"冨岡高齢福祉課長","answer":"まして介護ですので、身体介護あるいは生活の援助ということは、非常に微妙な、なかなか生活上のニュアンスがとらえられるかどうかということもありまして、そういうのも含めて、介護福祉士ですので、まず、かなり条件を整えるのが難しい状況があるかなと理解しています。","voiceIndex":66,"id":"exchange-029"},{"speaker":"山内委員","kind":"質問・要望","question":"私は別に品川介護福祉専門学校で語学を学べと言っているわけではないので、例えば日本人の方が英語を学んで、それで向こうで医学の勉強をするという方だってたくさんいらっしゃるわけですし、そういう逆の入口というものもちゃんと柔軟にしておくことが一つ必要なのかなと思いますので、それは今後の要望というか、今後を見据えていきたいと考えています。","respondent":"冨岡高齢福祉課長","answer":"再チャレンジ応援講座という部分ですけれども、これにつきましては、現在、ヘルパーとか、そういう資格がおありになる方で、今、お勤めになってない方、この方たちに品川介護福祉専門学校で一定期間、講習会等を開きまして、もう一度研修等で。","voiceIndex":68,"id":"exchange-030"},{"speaker":"山内委員","kind":"質問","question":"つまり、何かの原因で休職されている方がまた仕事をしたいといったときに、そういう意味での講座ということでよろしいんですよね、わかりました。最後に、家具転倒防止対策助成、これは３００万円ついておりますけれども、地震があったときに一番の死亡率の原因というのは圧死なわけですよね。この助成の仕方と、今どのようなタイプのものを用意されているのか。それだけを教えてください。","respondent":"永尾高齢事業課長","answer":"上限２万円までの部分について、９割助成をするというような制度です。なお、非課税の方については、全額、区が助成することとなっております。それから、器具についてですが、取り付けの家主のほうの承諾が得られれば、金具等を取り付けますけれども、それがなければ……。","voiceIndex":70,"id":"exchange-031"},{"speaker":"浅野委員","kind":"質問","question":"私のほうからは、２３３ページ、ひとり親家庭支援事業、国民健康保険事業会計の４３４ページの特定健康診査等事業費、後期高齢者医療特別会計のほうで４８６ページ、保健事業費、健康診査費についてお伺いします。","respondent":"諸岡児童課長","answer":"パソコン教室事業につきましては、これまで品川区の独自のひとり親家庭支援事業ということで、母子寡婦福祉連合会のほうに委託して事業を実施しておりました。","voiceIndex":73,"id":"exchange-032"},{"speaker":"浅野委員","kind":"確認","question":"パソコンの教室ですけれども、具体的に何を勉強するのかということと、これは母子家庭、父子家庭、両方の対象になっているかと思うんですけれども、その参加者数と、あと、自立支援助成、こちらのほうはいろいろな訓練とか、あると思いますけれども、そちらのほうの人数の内訳、それぞれ、平成１９年度からの助成件数と助成額などについてお伺いできればと思います。","respondent":"諸岡児童課長","answer":"パソコン教室事業、これの内容ですけれども、これは母子寡婦福祉連合会のほうに委託いたしまして、託児つきで実施をしているものがあります。今年度は、初級講座ということで、ワード、エクセル、それぞれの講座を２０人の定員に分けて、年２コース実施をしたものです。","voiceIndex":75,"id":"exchange-033"},{"speaker":"浅野委員","kind":"意見","question":"母子自立支援助成ですけれども、実際にその成果として、就労につながったかどうかということについても、ひとつお願いします。","respondent":"諸岡児童課長","answer":"プログラムの中では４０人ほどプログラムを申し込まれていますけれども、そういった方もこのプログラムに含めて、自立支援員がアドバイスを行いながら、きめ細かく対応していただいて、就労に結びつけているという状況です。","voiceIndex":77,"id":"exchange-034"},{"speaker":"浅野委員","kind":"質問","question":"先ほども質問にありました件ですけれども、児童扶養手当の一部削減、こちらのほうですけれども、昨年の予算特別委員会でも、会派としても質問させていただいたんですけれども、働いている方、また就労していなくても、休職している方などが、一部支給停止適用の除外の対象ということだったと思うんですけれども、この制度が昨年の２月８日以降に急遽スタートしたと聞いているんですけれども。","respondent":"諸岡児童課長","answer":"現在、私どもとしても、さまざまに個別に対応を図りながら、状況確認をしておりますけれども、連絡がとれなかったりというようなことで、２分の１の削減になった方が全体で８０人ぐらいの人数です。","voiceIndex":79,"id":"exchange-035"},{"speaker":"浅野委員","kind":"質問","question":"せっかく就労につながったけれども、条件が合わずに、例えば保育園に預けられないということになったら、これは困るなと思ったんですけれども、この連携についてお伺いします。","respondent":"諸岡児童課長","answer":"就労に向けて求職活動を行っている方、この方々の中にはほとんど保育園にお子さんを預けて就労活動を行っている方、多い状況があります。その中で特別な事情等があれば、私どもを通して保育課との連携を図りながら、対応をしている状況です。","voiceIndex":81,"id":"exchange-036"},{"speaker":"浅野委員","kind":"質問・要望","question":"今お話しいただきましたけれども、実際に求職している方でも、保育園に入ってない状況もありますので、ぜひともこの点については考慮いただきたいなと思います。児童を対象としている福祉ですので、親はだれであれ、女性でもばりばり働いている方も当然いらっしゃいますし、男性でもなかなか仕事のほうが厳しいという方もおられますので、この点についてお伺いします。","respondent":"諸岡児童課長","answer":"父子家庭の支援についてです。父子家庭で一番切実なのは、家事がなかなかできないというお話をよく聞きます。","voiceIndex":83,"id":"exchange-037"},{"speaker":"浅野委員","kind":"質問","question":"平成２１年度の特定健診の受診率の目標と、この受診率が、将来的には平成２４年度の国の参酌標準ですけれども、達しなかった場合の国保への影響があるかと思いますけれども、これについて、平成２１年度の受診率目標、どのぐらいに設定されるのか、お伺いします。","respondent":"本城国保年金課長","answer":"初めに特定保健指導の現在の状況ですが、現在の実施状況といたしまして、対象となった方の２６.３％に当たる方に実際に保健指導を行っているところです。","voiceIndex":85,"id":"exchange-038"},{"speaker":"浅野委員","kind":"質問・要望","question":"最後、今度は要望だけにしておきます。平成２１年度、たしか質問の回答、前にあったと思いますけれども、年度当初に対象者全員に特定健診の案内を発送するというお話をいただいていたかと思うんですけれども、実際に特定保健指導も早期から開始する。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-039"},{"speaker":"渡部委員","kind":"質問","question":"すごいですね。そのほか、いろいろバンドですとか、ダンスですとかを指導される方が中高生向けにはいたり、いろんな方がいると思うんですが、実際児童センターの事業費が１５％も落ちてきている理由と、この指導員謝礼等というところが大きく落ち込みがあると思うんですが、この辺、指導員とは何なのかとか、等というのが何なのかというところを教えてください。","respondent":"諸岡児童課長","answer":"その事業の総額、これが減少している理由ですが、同じ２４３ページの下から５行目をご覧いただきたいと思うんですが、保育園との連携事業の中で、この中でも、児童センター事業ということで、２,２００万円ほど計上しています。","voiceIndex":89,"id":"exchange-040"},{"speaker":"渡部委員","kind":"質問","question":"この部分、わかりました。今、平成２０年度で派遣の方を午前中の分、打ち切りということなんですが、ということは、その前のページを見ますと、職員８５名というのは、これは前回とも変わってないと思うんですけれども、いる人間で残業等で頑張っていこうという話なんでしょうか。","respondent":"諸岡児童課長","answer":"こういう方々が増えてきてまいりまして、児童センターにおきましても、今回の予算にも計上しておりますように、子育て支援スタッフ育成講座というような講座を用意いたしまして、この中で地域の方々の力を児童センターの運営にお借りしようです。","voiceIndex":91,"id":"exchange-041"},{"speaker":"渡部委員","kind":"質問","question":"子どもたちもまた、いわゆる学校じゃない、親じゃない部分での自立というんですかね、好きなことが児童館に行けばできるんだということで、児童館で相当活躍している。時間がなくなっちゃいましたが、１件だけ、今後、ティーンズプラザをこれから増やしていこうとか、日曜あいているところで、中高生が来れるようなのを増やそうとかというお考えがあるかどうかだけひとつ最後にお聞かせください。","respondent":"諸岡児童課長","answer":"平成２１年度にも１館、またティーンズプラザ、工事をしておりまして、合計９館ということで、今後も児童センターの施設を活用して、青少年事業を一層充実させていただいて、また地域の方のご協力もいただきながら、実施してまいりたいと考えております。","voiceIndex":93,"id":"exchange-042"},{"speaker":"菊地委員","kind":"質問","question":"私のほうは、後期高齢者医療特別会計のところでお聞きしたいと思います。この制度、始まって１年近くたちますけれども、保険料の滞納者数をまずお知らせを願いたいと思います。その辺で考えると、資格証の発行もあり得るということなのかどうか。その辺をお聞かせを願いたいと思います。","respondent":"永尾高齢事業課長","answer":"資格証の件ですが、国のほうでも資格証は機械的に出すのではなくて、丁寧な相談をした上で出しなさいということの通知が来ておりまして、それを受けて、広域連合のほうでもどういう基準にするかというのは、厚生労働省の案を見ながら、今、検討していますので、現在。","voiceIndex":96,"id":"exchange-043"},{"speaker":"菊地委員","kind":"質問","question":"収納率９５.３２％。実際に滞納者数というのはどれぐらいになるのかをお聞きしたので、そこをお知らせ願いたいなと思います。","respondent":"永尾高齢事業課長","answer":"現在は、法律上はこういう規定になっておりますが、先ほど申し上げましたように、今年度につきましては、初年度ということで、いろいろ周知ができていない部分もありますので、このとおりに法律どおりやるのではなくて。","voiceIndex":98,"id":"exchange-044"},{"speaker":"菊地委員","kind":"質問・要望","question":"ただ、今のお話ですと、法律上はこうなっていますよということですから、実質的に今後の経過の中では、保険証の取り上げという事態も生まれてくるというふうになります。そうすると、半分以下ですよね。この半分以下の状態というのをこのまま、一度通知をしているんでしょうけれども、この半分以下という実態をどういうふうに改善をしていくつもりなのか、そこをお聞かせください。","respondent":"永尾高齢事業課長","answer":"全員に送付しております関係で、お年寄りの方、かなり、こちらのほうにお問い合わせをいただいておりますので、この説明を聞いた上で、出さないという方も中にはいらっしゃるのではないかと考えています。","voiceIndex":103,"id":"exchange-045"},{"speaker":"菊地委員","kind":"質問・要望","question":"こう言って昨年１月に厚生労働省の課長補佐が地方で講演していますけれども、先ほどの話ですけれども、保険証を取り上げるというのは人の道に反する問題だと思いますから、そこはきっちりやっていただきたいのと、この制度そのものを中途半端に見直しするんじゃなくて、中止を求めるということをやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-046"},{"speaker":"渡辺委員","kind":"質問","question":"私は５３９ページ、サービス向上委員会費、２２１ページ、障害者リラクゼーション事業、２１３ページ、高齢者生きがい対策事業費、２３５ページ、次世代育成支援対策費、４点で伺いたいと思います。最初にサービス向上委員会費で伺いたいと思います。品川区のサービス向上委員会の点が１つと、もう一つ、予算書でもありましたが、東京都の福祉サービス第三者評価という表現がありました。","respondent":"冨岡高齢福祉課長","answer":"それから一方、東京都のほうのサービスの第三者評価ですけれども、これは、平成１５年に事業者のサービスの質の向上に向けた取り組みの支援ということで始められた第三者機関による評価でございまして、具体的には事業者が都の認証の評価機関と契約を締結していただいて。","voiceIndex":108,"id":"exchange-047"},{"speaker":"渡辺委員","kind":"質問","question":"資料等を見た感覚と、背景はわからなかったので、背景は今のご答弁でわかってきました。それを次のサービスに生かすという姿勢が感じ取れた、個人的な感想があります。その点を伺いたいのと、分析等調査では、独自にされているのか、委託等もあるとは思いますが、この辺、２点伺いたいと思います。","respondent":"冨岡高齢福祉課長","answer":"苦情の部分ですけれども、毎回のサービス向上委員会におきまして、前回からの後のさまざまな区内の在宅サービスなり施設サービスにおける苦情の状況、それから、対応の状況、区としてどのように対応していくか、そういう形で報告いたしまして。","voiceIndex":110,"id":"exchange-048"},{"speaker":"渡辺委員","kind":"質問","question":"私の聞き方も悪かったんですが、何を言わんとしているかというと、評価という何か目安がないと、一般利用者の方等は、どうしても判断基準が持てない部分があると思いましたので、特に品川区の制度の場合は、年４回という、頻度も結構されていますし、膨大な資料がとてもインパクトという点も含めてわかりやすさもあったものですから、今後発展されたらいいなという思いで伺いました。","respondent":"高橋障害者福祉課長","answer":"私どもでは、五感に働きかけるということで、空間設定をしたり、機器を導入したりして、リラックス効果、また適正な刺激を受けて、より快適性が継続できるということで、今回、検討プロジェクトをしながら、モデル事業を実施し、検証して。","voiceIndex":112,"id":"exchange-049"},{"speaker":"渡辺委員","kind":"質問","question":"そういう今のご説明から聞きますと、ねらいというのが、朝のご説明も、試行という点を触れられていましたが、今、経緯の中でも、部署内の方の前向きな意欲、そういった経緯も期待しますし、多分今の話にありました共助の考え、そして、自分としての感覚でいえば、福祉だけではなくて、こういった都市部における各施策への効果、こんなこともねらいにあるのかなと思ったので、その点、伺いたいと思います。","respondent":"高橋障害者福祉課長","answer":"都市部のねらいですが、私どもの施設におけるところでの設定、もしくは区内にいろいろな施設、例えば水族館みたいなものがありますので、そこを活用したりというところで、そういうような区内の施設を活用しながらということも考えられますので。","voiceIndex":114,"id":"exchange-050"},{"speaker":"渡辺委員","kind":"質問","question":"次世代育成支援事業の点で伺いたいと思います。今年度のプレス発表を見ますと、この中の１つの項目、大学出張セミナー、ルック品川とあります。予算上は講義資料などで３０万円となっています。普通の一般的な講演というと、呼ばれていくのかなという思いがありました。そして、品川区が得る効果、あるいはねらいはどのようなところにあるのか、伺えればと思います。","respondent":"諸岡児童課長","answer":"特に間もなく社会人となる大学生の皆様を対象として、就労と子育ての両立支援とか、あるいは、品川区の充実した子育て支援策をお伝えすることによって、子育て制度等についても理解を深めてもらうということで、区内の大学、現在。","voiceIndex":116,"id":"exchange-051"},{"speaker":"石田（慎）委員","kind":"質問","question":"私は、２０７ページ、ホームレス対策事業について、２３５ページ、今も質問にありました次世代育成支援対策費について、それと２３７ページの一時保育に関連して質問します。それと次世代育成支援対策費なのですが、先ほども質問がありましたので、重ならないようにはしたいと思うんですが、ＰＲの経費が計上されているんですが、このＰＲというのは、どのような形で進められていくのでしょうか。","respondent":"志村生活福祉課長、福島長期計画担当課長、阿部経理課長","answer":"こうした施設の取り組みを平成１２年から行っておりますので、こうした減少につながっていると考えております。次世代のどの辺の世代を考えているかですが、こちら、子どもがもちろんメインですが、子どもを取り巻く、育てる家庭ですとか、あるいは。それをレイアウト変更に伴いまして、７階に移動するものでございまして、職員の休憩時間の利用。","voiceIndex":119,"id":"exchange-052"},{"speaker":"石田（慎）委員","kind":"提案","question":"次世代育成支援のほうはわかりました。１点だけ、これは要望なのですが、ホームページということで立ち上げていただいて大変活発的なご意見が交わされているということなんですが、青年層は、今パソコンより携帯電話のほうが圧倒的にインターネットに接続するのが高いので、そういった点もぜひ考慮していただきたいと思います。ご見解をお聞かせください。","respondent":"志村生活福祉課長、福島長期計画担当課長、阿部経理課長","answer":"私から、ビッグイシューという雑誌の件ですけれども、雑誌の存在は承知していますけれども、具体的な連携等はございません。ホームページで、実は今も携帯のホームページも運用してございまして、来年度はさらに充実して行っていく予定です。常時の一時保育ですけれども、この和室に関しましては、例えばいろんな区の主催で行事をする場合に。","voiceIndex":123,"id":"exchange-053"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"最後に、ホームレス対策は常用雇用を目指すということですが、例えば施設になかなか行きたくないというような方もいらっしゃると思いますので、そういった方々に、こういったのもあるよというような告知などをもしできたらと思うので、ご検討していただきたいと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-054"},{"speaker":"安藤委員","kind":"質問","question":"ただいまホームレス支援対策ということで、品川区のホームレスの人数が３５人で、毎月訪問調査しているというお話がありましたけれども、今、３月末までに４０万人の方が正規労働者が職を失うというような試算が出ております中で、今後もっと危機的な状況になるんじゃないかということと、あと、調査の中でネットカフェの中の状況は調査してないと思うんですけれども、これは実際に調査しないと。","respondent":"志村生活福祉課長","answer":"ですので、その方からのご相談ということで、お受けする中でこうした対応を図るべきだろうと考えています。","voiceIndex":129,"id":"exchange-055"},{"speaker":"安藤委員","kind":"質問・要望","question":"２００８年度の生活保護手帳の中の実施要領ですけれども、保護手帳の中に、きちんと要保護者の発見、把握をしなさいという条項がありまして、要保護者を発見し、適切な保護を実施するため、生活困窮者に関する情報が保護の実施機関の窓口につながるよう、住民に対する生活保護制度の周知に努めることを求めているわけですね。あわせてお伺いしたいと思います。","respondent":"志村生活福祉課長","answer":"それとご本人の意思です。これを確認しながら、いわゆるキャッチボールをしながら進めていくのが福祉の原点だと感じております。ですので、生の声をお聞きした上で対応を図るべきだろうと思ってあります。","voiceIndex":131,"id":"exchange-056"},{"speaker":"西本委員","kind":"質問","question":"私から３点ほど。２１１ページのこうほうえん、２３５ページの認証保育所利用助成、２４３ページの保育園との連携事業についてお聞きします。しかも、国会議員の方もいらっしゃっていたんですが、こうほうえんの地元の議員の方なんでしょうか、来ておられた。そこら辺は選定の中に入っていなかったのかどうかということをまずお聞きしたいと考えています。拡大の方向は考えてないのかどうかを聞きます。","respondent":"冨岡高齢福祉課長、小林保育課長","answer":"こうほうえんがこの場所の公募のプロポーザルで選ばれました経緯につきましては、これは、ああいう施設が全国的に類を見ない施設であり、実際の問題として、さまざまな場所で実施をして、例えばケアホームの部分ですとか。児童センターのうち、一部、乳幼児に特化した性格を持たせて、キッズ館ということで、現在、来年度、２館を含めて４館に増やして対応していますが、児童課とは、ある意味で、対象とする層に対して役割分担をし、そして。","voiceIndex":134,"id":"exchange-057"},{"speaker":"西本委員","kind":"質問・要望","question":"別に宣伝されても構いません。ですから、親からの立場からいうと、認証保育所も今、目いっぱいなんです。しかしながら、働く上では、認証保育所がいっぱいで入れないわけですから、どうしても無認可に行かせざるを得ないというところがあるわけで、そういう了見からすると、助成金はあってしかるべきではないかなと私は思いますので、そのお考えを最後お聞きします。２つだけお願いします。","respondent":"冨岡高齢福祉課長、小林保育課長","answer":"地域のことをよく知るべきだという話については、お話をしてまいります。それから、今後のサービスについては、引き続き頑張るように伝えてまいります。ただ、ご指摘のとおり、そうはいっても、入れない部分がある。これにつきましては、いろいろな制度を総合的に活用して、そういう状況が発生しないように引き続き努力してまいりたいと考えております。","voiceIndex":137,"id":"exchange-058"},{"speaker":"山元委員","kind":"質問・要望","question":"私のほうからは、２０７ページの成年後見制度利用支援事業、それに関連しまして、次の２０９ページの社会福祉協議会助成金、そして最後は、２４３ページの児童センター事業についてお伺いします。しかし、改めてここでもう一度、成年後見制度というのはどういうことなのかということを教えていただきたいと思います。","respondent":"冨岡高齢福祉課長","answer":"認知症高齢者の方、あるいは知的障害者の方など、ご自分で十分な判断をすることができない方が財産の取引とか契約等々で一方的に不利な契約を結ばないよう、法律面で支援するとともに、適切な福祉サービスにつなげるなど、生活面での援助ということで。","voiceIndex":141,"id":"exchange-059"},{"speaker":"山元委員","kind":"質問・要望","question":"この制度が施行されて約８年経ちまして、約１５万人の方が利用していると伺っております。実際品川区におきまして、こちらにも高齢者と障害者に分けてありますけれども、今までの品川区における利用者の人数を教えていただきたいと思います。","respondent":"冨岡高齢福祉課長","answer":"法定後見が始まりましたのは平成１４年からですが、合計で、今、後見を受けております、受任と申しますが、これは９１件です。なお、そのうち、平成２０年度につきましては、２５件という数字です。","voiceIndex":143,"id":"exchange-060"},{"speaker":"山元委員","kind":"質問","question":"今、平成２０年度は２５件とおっしゃいましたけれども、この内訳といいますか、ご相談というか、利用なさった方は高齢者の方がほとんどなんでしょうか。","respondent":"高橋障害者福祉課長","answer":"障害者の方で、今まで１５件の方が申し立てて、社会福祉協議会が具体的な後見人になっている方は９人おります。そのほかの方につきましては、地方の施設に入所しているため地方の方に後見にせざるを得ない方については、そちらをご紹介して、行っているものです。","voiceIndex":145,"id":"exchange-061"},{"speaker":"山元委員","kind":"質問","question":"私のところにもご相談がありまして、こういう制度があるんだというお話をいたします。周知といいますか、具体的に今までこういう制度があるということをお知らせなさっていたかと思いますが、今までどのような周知をされていたのか、教えていただけますでしょうか。","respondent":"冨岡高齢福祉課長","answer":"これはさまざまなパンフレット類でまずお知らせをするということと、それから、当然ホームページにも載せまして、あるいは社会福祉協議会、私ども、区のそれぞれの広報紙、あるいはさまざまな機関紙等でご案内しています。","voiceIndex":147,"id":"exchange-062"},{"speaker":"山元委員","kind":"質問・要望","question":"そのまま引き続きまして、２０９ページのほうに移らせていただきたいと思います。社会福祉協議会の助成金の中に、成年後見センターというふうにあるんですが、実際、成年後見センターで行われている仕事といいますか、どういうことをなさっているのか、中身を教えていただけますでしょうか。","respondent":"冨岡高齢福祉課長","answer":"それからあと、先ほど申し上げました広報とか普及体制ということで、区民の皆様に対する説明会、あるいは関係機関に対して周知を図っていくというようなことが主な業務です。","voiceIndex":149,"id":"exchange-063"},{"speaker":"山元委員","kind":"提案","question":"今回、プレス発表資料の中に、協働事業提案制度、平成２１年度に実施する事業ということで、区民の提案事業の中に成年後見制度、ＮＰＯの市民後見人の会という団体から成年後見制度普及ビデオ上映、または市民後見人の養成講座事業というのが記載されているんですけれども、実際、市民後見人養成講座というんですか、活動というのは、どのような活動をするのでしょうか。教えていただけますでしょうか。","respondent":"久保田行財政改革担当課長","answer":"協働事業提案制度ですので、私からお答えします。","voiceIndex":151,"id":"exchange-064"},{"speaker":"山元委員","kind":"質問","question":"しかし、今のお話によりますと、講習を受けることによって、そういう資格といいますか、なれるということなんでしょうか。そこでちょっと心配なのは、そういう方がなっても大丈夫と言うと変ですけれども、ある意味、財産とかをその方に任せるわけですので、その辺はどうなのか、教えていただけますでしょうか。","respondent":"久保田行財政改革担当課長","answer":"社会福祉協議会の成年後見センターのほうでバックアップをしていくとお伺いしておりますので、大丈夫だと伺っております。","voiceIndex":153,"id":"exchange-065"},{"speaker":"山元委員","kind":"質問","question":"大丈夫というお話でしたが、実際こういう方、区民後見人はいらっしゃるんでしょうか。","respondent":"冨岡高齢福祉課長","answer":"実際３人ぐらいおいでになるですが、先ほどの補足になりますけれども、これは社会福祉協議会のほうで後見監督のほうをするですので、そういう形で支援もし、また、東京都の後見人のための講座も受けた方たちですので、安心だと考えております。","voiceIndex":155,"id":"exchange-066"},{"speaker":"山元委員","kind":"意見","question":"今、３人とおっしゃいましたが、将来的に３人ではもちろんやっていけないと思いますが、区としてはある程度の人数の目標を掲げていらっしゃるんじゃないかなと思いますが、大体どのぐらいの人数を養成していこうと思っていらっしゃいますか。","respondent":"冨岡高齢福祉課長","answer":"市民後見人の会の方たちは、自主的に積極的にやっていただいている部分があります。それはあくまでも私ども社会福祉協議会の成年後見センターを通じて後見人活動をしているというのがメインでございまして、計画的に何人にするとかという形で考えてございません。","voiceIndex":157,"id":"exchange-067"},{"speaker":"山元委員","kind":"質問","question":"時間がなくなってしまったので、それに関連する、この中のさわやかサービスのことでお伺いいたします。そしてまた、利用料金というんですか、と同時に、協力会員に対しての報酬はどのぐらいなのか教えていただけますか。","respondent":"冨岡高齢福祉課長","answer":"さわやかサービスの関連のご質問です。ご案内のとおり、協力会員と利用会員がおりまして、平成１９年度の実績で恐縮ですが、利用会員が４６７人、協力会員が４０７人です。協力会員に対しましては、１時間７００円の協力費をお支払いしています。","voiceIndex":159,"id":"exchange-068"},{"speaker":"山元委員","kind":"質問","question":"これはボランティアということなので、７００円というのは安いんじゃないかなと私としては思うんですが、これは当初から７００円ということなんでしょうか。","respondent":"冨岡高齢福祉課長","answer":"これは平成４年に立ち上げをしたということで、当初から７００円ということで、会員制であるということ、ボランティアということで、７００円に設定をしています。","voiceIndex":161,"id":"exchange-069"},{"speaker":"山元委員","kind":"質問","question":"その中でもう一つ、ちょっと気になっているのが、ボランティアセンターというところなんですが、ボランティアセンターというのは、区からお仕事をいただいて、ボランティアとして行って、商品券、もしくは寄付をする、と見たんですけれども、実際これは６０歳以上の方、男性、女性関係なく、ボランティアに参加するということなんでしょうか。","respondent":"冨岡高齢福祉課長","answer":"あるいは寄付をしていただくという形で進めているものでございまして、おおむね６０歳以上です。","voiceIndex":163,"id":"exchange-070"},{"speaker":"山元委員","kind":"質問","question":"今、そういう意味ではボランティア精神の方が多くいらっしゃると思うんですけれども、実際、やってくださっている人数というのは、１年間で何人ぐらいボランティア、お仕事をしていただいているんですか。","respondent":"冨岡高齢福祉課長","answer":"今の地域貢献ポイント事業につきましては、今年から始まりました事業ですが、登録者数が１月の段階で６１２名という形になっております。","voiceIndex":165,"id":"exchange-071"},{"speaker":"山元委員","kind":"質問・要望","question":"時間がなくなってしまいましたので、ともかく区民成年後見に対しても、ぜひ問題の起こらないようお力添えしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":167,"id":"exchange-072"},{"speaker":"本多委員","kind":"質問・要望","question":"２４３ページで何点か質問します。それ以外の部分で、指導員について教えていただきたいのと、同じページで、すくすく赤ちゃん訪問事業で、助産師、保健師、児童センター職員の連携がどのような状況になっているのか教えていただきたいのと、同じく２４３ページの助産師によるベビーマッサージ等事業ということで、これまでの取り組みと平成２１年度の取り組みについて教えてください。","respondent":"諸岡児童課長","answer":"平成１９年までは、それぞれの各館の中で、５館ないし６館ということで取り組んでおりましたが、平成２０年度からは、１３地域それぞれの館、１３館でベビーマッサージ等の講座を年間３回ということで拡大して実施させていただきました。","voiceIndex":169,"id":"exchange-073"},{"speaker":"本多委員","kind":"質問・要望","question":"そういうさまざまな事業に携わった方で、親御さんが子育てのポイントですとか、子育ての不安ですとか、そういったものが解消できたりして、非常に的確なアドバイスを受けたり、そういった成果がどのように上がっているのか。成果は当然上がっていると思っているんですけれども、その辺、具体的にどのように成果が上がっていると見ているのかを教えていただきたいと思います。","respondent":"諸岡児童課長","answer":"助産師の皆さんからさまざまなご協力をいただきまして、事業を実施しております。平成２０年度でも、それぞれの回数ごと、２５組から３０組ぐらいの多くのお母さん、それから赤ちゃんが参加されて、実施しています。大変好評です。","voiceIndex":171,"id":"exchange-074"},{"speaker":"本多委員","kind":"質問","question":"福祉人材確保という言葉が最近よく使われておりますけれども、福祉人材確保というと、介護関連の高齢者関連というのがすごく、そういう感が強いんですけれども、それはそれでもちろん大切なことですし、介護従事者の環境、介護報酬等も含めて、当然環境整備というのは大切なんですけれども、そういう大事な部分、同じように、乳幼児関連でも、そういった環境整備というものが、人材確保等。","respondent":"諸岡児童課長","answer":"児童センターの運営等にさまざまな方がご協力をいただいているところですけれども、来年度に向けても、事業の中で、子育て支援のサポーターをしていただく、スタッフの養成の講座というようなものを児童センターのほうで開催いたしまして、その中で、地域の方々を含めて。","voiceIndex":173,"id":"exchange-075"},{"speaker":"本多委員","kind":"質問・要望","question":"ぜひよろしく進めていただきたいと思います。同じ２４３ページの中にもありますけれども、赤ちゃん・ふらっと事業ということで、授乳などの環境整備がされてきているという、朝の説明でもありました。そういう環境が順次整っているんだなと思うんですけれども、大体これで品川区内全域に環境が整ったというふうに見るのか。その辺について教えていただきたいと思います。","respondent":"諸岡児童課長","answer":"今後引き続き、この設備等の充実、またそういったＰＲについては図っていきたいと考えているところです。","voiceIndex":175,"id":"exchange-076"},{"speaker":"本多委員","kind":"質問・要望","question":"民生費の今日の款別の中での施設、児童センターに限らず、いろんなもろもろの施設で、そういったポスターを貼るだけでも効果が上がるんじゃないかなと思うんですが、保健所にはあした衛生費で聞こうかと思いますけれども、きょうは民生費の管内での施設で、そういう対応はいかがでしょうかということを教えていただきたいと思います。","respondent":"諸岡児童課長","answer":"ご指摘のポスターの掲示等につきましては、そういった意味も含めて、私どもといたしましても、積極的に対応させていただきたいと思っているところです。","voiceIndex":177,"id":"exchange-077"},{"speaker":"井上委員","kind":"質問","question":"民生委員経費ですけれども、民生委員は市区町村の推薦を受けて、厚生労働大臣が委嘱するということで、民生委員法の第２６条には都道府県が費用を負担すると明記されているんですが、それだと区は支払義務はないと思うんですけれども、予算特別委員会の資料によると、都の支出と一般財源からも支出をされているんですが、この理由はどういったものなのでしょうか。","respondent":"冨岡高齢福祉課長","answer":"この中身につきましては、負担割合ということでやっているわけです。この内容ですけれども、民生委員の会長協議会等の内容につきまして、負担割合で実施しています。","voiceIndex":180,"id":"exchange-078"},{"speaker":"井上委員","kind":"質問","question":"都道府県が負担すると書かれているのに、どうして自治体で負担しなければいけないのかということをお聞きしているので、その点についての説明だけで結構です。","respondent":"冨岡高齢福祉課長","answer":"この部分につきましては、社会福祉施設の視察等の研修事業につきまして、区から支出をしています。","voiceIndex":182,"id":"exchange-079"},{"speaker":"井上委員","kind":"質問","question":"研修とか、いろいろな部分については都道府県というふうに民生委員法に書いてあるので、この部分については、また別途伺いたいと思いますが、本当は企画財政課のほうに伺えればと思いましたので、何かあればお願いします。","respondent":"日下部企画財政課長","answer":"ただ、地方にも一部そういう意味では利害関係が出てまいりますので、一部については地方が負担するというような、おおむねそういうような仕組みになっておりまして、ですから、その辺につきましては、一種の割り勘的に負担をし合う。","voiceIndex":184,"id":"exchange-080"},{"speaker":"井上委員","kind":"質問","question":"それからもう一つは、民生委員の活動に対する報酬が適切かどうかという視点で伺うんですが、報酬あるいは費用弁償という形なのかと思いますが、先ほど生活保護のほうからも民生委員の役割としてちょっとお話がありましたが、実際に幾つの事業を民生委員に品川区としてお願いしていて、その活動に対してどれだけの報酬が支払われているのかということをお伺いいたします。","respondent":"冨岡高齢福祉課長","answer":"これにつきましては、考え方といたしまして、ボランティア活動費として交通費等実費を支給するというところになっておりますので、その趣旨に従いまして、支出をしています。活動状況ですけれども、３０個ぐらいの業務を活動していただいております。","voiceIndex":186,"id":"exchange-081"},{"speaker":"井上委員","kind":"質問","question":"今、お話しいただいたように、民生委員に対して３０ぐらいの量ということで、以前にも伺ったときに、区境の民生委員、大田区と品川区というような区境があるんですが、そういったところでは、民生委員同士のお話で、品川区にはいろいろな活動の依頼が多いんだということで、随分と困っている声も聞きました。その見解だけ先にお願いします。","respondent":"冨岡高齢福祉課長","answer":"そういう部分もありますし、民生委員でなければならない、ある程度プライバシーにかかわるような仕事といったものはあるということをよく踏まえながら、お願いできる部分はお願いしたいと思っておるところです。","voiceIndex":190,"id":"exchange-082"},{"speaker":"井上委員","kind":"質問・要望","question":"次が、知的障害者の単身生活サポート事業や精神障害者の地域生活サポート事業なんですが、昨年新規で始まって、地域生活を支援するということが確実に広がればいいなと期待しているんですが、この事業の財源は何らかの補助金が充当されているのかということと、あと、昨年の予算より精神障害者の生活サポートが増額されているんですが、その理由について、２点お伺いいたします。","respondent":"高橋障害者福祉課長","answer":"精神障害者のところがなぜ多いのかといいますと、憩いの場ということで、集うことができる、交流の広場ということで、３９０万円、そこのところで行っているものです。","voiceIndex":192,"id":"exchange-083"},{"speaker":"井上委員","kind":"質問・要望","question":"品川区は、放課後の障害児の児童対策として、にじのひろばとナイスデイサポートを打って、受け入れていただいているんですが、身体障害児の受け入れ先が非常に少ないということで、今後どのように拡大をしていくのか、お伺いいたします。","respondent":"高橋障害者福祉課長","answer":"ナイスデイサポートにつきましては、昨年、平成２０年４月に開設したもので、今後については、ここの中でも、可能であれば受け入れていくということも検討してまいりたいと思います。","voiceIndex":194,"id":"exchange-084"},{"speaker":"井上委員","kind":"質問・要望","question":"ぜひ身体障害児の方々も、放課後対策として品川区で取り組んでいただきたいと思います。今年度の予算書によりますと、補正でリサイクルショップ、そして、日本語指導教室についても予算書で見直しが確認できました。利用者の要望も把握された上で、検討していただいたんだと私は思っておりますけれども、昨年同様の２５５万円という結果について理由をお伺いいたします。","respondent":"高橋障害者福祉課長","answer":"お金の問題につきましては、その中でも、場所を移ったり何かする中での今後の検討ということで、当面このままにさせていただいたところです。","voiceIndex":196,"id":"exchange-085"},{"speaker":"井上委員","kind":"質問・要望","question":"今の説明を聞く限りでは、同じナイスデイサポートの予算額が７００万円であるということについて、私は整合性がよくわからないなと感じています。説明のつく算出根拠を示していただいて、さらに検討していただくように、また利用者の声を酌み取っていただきたいということをお願いしたいと思います。ちょっと大きな話ですが、お伺いいたします。","respondent":"冨岡高齢福祉課長","answer":"これは高齢者向け優良賃貸住宅ということで申し上げますと、これにつきましては、国の補助が４５％出るですので、単純に言えばその裏側となりますけれども、これについては、今後都との協議の中で、どの程度まで補助をもらえるのかどうか、それも含めて進めてまいりますので。","voiceIndex":198,"id":"exchange-086"},{"speaker":"井上委員","kind":"質問","question":"補助金については伺いました。この施設について一般財源をどの程度かかると積算をされているのかということを先ほど質問しました。","respondent":"冨岡高齢福祉課長","answer":"イメージとしては、プレスに発表したとおりですけれども、では、具体的にどういう建物にするか、それについては今後、基本計画、基本設計という形で詰めてまいらなければなりませんので、それを踏まえませんと、今おっしゃるところの内容については。","voiceIndex":201,"id":"exchange-087"},{"speaker":"井上委員","kind":"質問・要望","question":"時間がありませんので、介護保険特別会計のほうで、今回、介護予防一般高齢者施策事業が昨年度から４つ事業が移行しましたので、そのことについて、合わせて地域貢献ポイント事業も一般財源に移すべきだと私は考えたので、その点、そこが動かなかったことだけ、時間がありませんが、お答えいただきたいと思います。","respondent":"冨岡高齢福祉課長","answer":"これは介護保険事業の中の地域支援事業ということで位置づけておりますので、財源がいただけるということで、この部分では介護保険特別会計に入れているところです。","voiceIndex":203,"id":"exchange-088"},{"speaker":"高橋委員","kind":"意見","question":"２２１ページの障害者就労訓練事業、それから、発達障害全般のこと、それからあと、２１１ページ、福栄会に対する助成金について、それから、２１７ページのシルバー人材センターに関してです。そして、このような経済状況の中で、現時点での今年度の就労の状況、例えば例年採用されているのに、今年は求人がないとか、あるいは解雇されてしまっただとか、そのような状況をお願いいたします。","respondent":"高橋障害者福祉課長","answer":"知的障害者就労支援ですが、就労支援センター「げんき品川」というところで行っています。","voiceIndex":206,"id":"exchange-089"},{"speaker":"高橋委員","kind":"質問","question":"今、このような経済状態の中で、いろいろ離職等の話はないというお話ですが、今後、そういうことも可能性が出てくるかと思うのですが、区として、こういった状況の中で、特別に、障害者の方々の就労に関して、緊急対策といいますか、そういうようなことはいかがでしょうか。","respondent":"高橋障害者福祉課長","answer":"今の時点でもやめさせられた方がないということは、まじめに働いているのかなと考えています。ただ、ここのところにつきましても、ジョブコーチ等がありますので、丁寧に企業を回って、相談に応じていきたいと考えております。","voiceIndex":208,"id":"exchange-090"},{"speaker":"高橋委員","kind":"質問","question":"区内の企業の中にはたくさんの障害を持った方を雇用されている企業があるかと思うのですが、そのような企業に対して、このような経済状況の中ですから、賃金の一部を負担するとか、例えば、最低賃金の中の一部を期間限定で区のほうが負担をするという形は、結果的には経済対策ではという言い方はあれかもしれませんが、障害者の方の雇用を守り、そして、企業の障害者雇用の促進等につながると考えるのですが。","respondent":"高橋障害者福祉課長","answer":"各区内の企業に対して、障害者の採用もしくは継続ということで、私どもでは、その企業ごとの経営状況がありますので、もし何かあった場合についてはお願いということもありますが、今の段階では、そのまま継続させていただいているという状況です。","voiceIndex":210,"id":"exchange-091"},{"speaker":"高橋委員","kind":"質問・要望","question":"２１１ページの福栄会に対する助成金のことなんですが、昨年の厚生委員会の資料を読んだんですが、詳しいことはよくわからないので、確認だけさせていただきたいんですが、かもめ第一工房が障害者自立支援法による施設に移行することになり、そこで交通費が、利用者の方の補助がなくなってしまうと伺っているんですが、そちらがどうなったかをお答えください。","respondent":"高橋障害者福祉課長","answer":"精神障害者という特性を考えまして、３施設が同歩調をとったほうがよろしいのかなと私どもも考えたところですので、当面、精神障害者の特性を考えまして、かもめ第一工房につきましても、交通費については継続するということになりました。","voiceIndex":212,"id":"exchange-092"},{"speaker":"高橋委員","kind":"質問","question":"先日、新聞記事もありましたが、文京、板橋、それから大田区の蒲田の医師会による５歳児健診も、医師会独自で始まったということなのですが、ともに医師会、目黒区のほうも医師会のほうとの協議でそういう声が出てきて、随分年数かかって協議の結果、実施することになったと伺っていますが、品川区では、医師会との協議を継続的に行われていると思うんですが、その中で。","respondent":"太田品川区保健センター大井保健相談所長","answer":"５歳児健診につきましては、健診というスクリーニングの方法は人口が多い都市圏では行われておらず、確かに幼少時には気づかれなくて、集団生活に入ってから気づかれることがあるとはされておりますが、その場合は、幼稚園、保育園等で職員による気づきで。","voiceIndex":214,"id":"exchange-093"},{"speaker":"高橋委員","kind":"意見","question":"今、幼稚園、保育園、対象の９８％が通園、通学していると言われていますが、今お話があったんですが、その健診といいますか、気づき、今年度はどれぐらいの事例があったのか。そして、その後、具体的にどこでどのような支援を受けることになったのか、お願いします。","respondent":"太田品川区保健センター大井保健相談所長","answer":"今年度の集計はまだできておりませんが、平成１９年度の保健所での健診、１歳６カ月、３歳児健診で見つかった発達障害の疑いがあるお子さんというのは、約４.４％です。例年四、五％程度見つかっております。","voiceIndex":216,"id":"exchange-094"},{"speaker":"飯沼委員","kind":"質問","question":"２２３ページの障害者施設、２２１ページの通所事業利用促進支援事業など、区の独自の負担軽減策についてお伺いいたします。内容的には、代表質問、宮崎委員の続きと思ってください。１点目は、住まいの整備に関してですが、入所施設について、区内の入所施設、施設数と施設名を教えてください。グループホーム、ケアホーム、これは区内の施設数と、幾つかの施設名を教えてください。","respondent":"高橋障害者福祉課長","answer":"身体障害者の入所施設につきましては、第一さつき園があります。それから、グループホームですが、知的障害者については、１０カ所、精神では１カ所ということになっております。","voiceIndex":219,"id":"exchange-095"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先日の共産党の計算したところでは、５００名を超える入所施設、グループホーム、ケアホーム、利用者のうち、区内に住み続けられている人は３割強でありました。７割弱の方が区外とか他県で生活されている。こういったご答弁がありました。これが１点です。ケアホーム、グループホームだけではなくて、ケアが充実した入所施設もこれから必要であると思いますが、この点はいかがでしょうか。","respondent":"高橋障害者福祉課長","answer":"グループホーム、ケアホームですが、今、長期計画の中で、今後、住まいのところについても十分検討していかなくてはならないということで、私どもでは検討しているところです。","voiceIndex":221,"id":"exchange-096"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区外に７割の方が生活されているわけですけれども、私もいろいろな方、知っていますけれども、山形県にお子さんを預けていて、結局、行ったり来たりで交通費はかかるし、本当に会いたいときに会えないというので、引っ越されたケースもあります。計画をきちんと立てていただきたいというのが２点目。こういったケースが生まれてくると思うので、その辺をもう一度お答えください。","respondent":"高橋障害者福祉課長","answer":"したがいまして、品川区においても、グループホーム、ケアホームについても、今後、十分に状況を把握した上で、建設のことを考えてまいりたいと思います。","voiceIndex":223,"id":"exchange-097"},{"speaker":"飯沼委員","kind":"意見","question":"十分状況を考えてということで、私は、計画がいつ立つのかなと。この間、ずっと数値的に全く示されてないんですね。最初に申し上げたように、部長は、一般的に聞くと、一定、水準がありますという答え方をずっとされていて、ここのところ、ちょっとそこが変化されたのか。グループホーム、ケアホームで対応していく。その辺、どう考えていらっしゃるのか、聞かせてください。","respondent":"高橋障害者福祉課長","answer":"グループホーム、プラス、ケアホームということで、ケアホームで暮らしている方につきましては、区分４、区分５、区分６ということで、かなり重症の方が暮らすということで、その辺については、ケアホームに入られる方については、排泄の介助も含めまして。","voiceIndex":225,"id":"exchange-098"},{"speaker":"飯沼委員","kind":"質問・要望","question":"何名でしたか。私、全く切迫感もないなと、今のご答弁で受けとめているので、もう１回その辺を聞かせていただきたいのと、グループホーム、ケアホームに関しては、すごく報酬単価が非常に低いために、大変な状況の中でやられているなと思っています。そういった面では、ＮＰＯとか民間任せにしてしまうのではなくて、区として財政的な支援がすごく大事であると思うんですが、その辺ももう１回お願いします。","respondent":"木下福祉高齢事業部長","answer":"この部分については、区でつくるものももちろん今後考えていく必要があるかと思いますけれども、民間の方でなさっている部分も区内にたくさんありますので、そういうところについては、区としては支援をするようなやり方で進めていきたいと思っています。","voiceIndex":227,"id":"exchange-099"},{"speaker":"飯沼委員","kind":"質問・要望","question":"地域での生活を支える。障害者の福祉なので、私はこの点、応益負担ではなく、応能負担に戻すべきであると思っています。そして、ほとんどの方が、今まで無料で受けられていたのですから、あくまでも無料に近づけていく努力を品川区としてはしていただきたい。求めていきたいと思っていますが、利用される方々への区の独自の軽減策、どういう努力をされているか、聞かせてください。","respondent":"高橋障害者福祉課長","answer":"今回、新規事業で、通所事業の利用促進支援事業ということで、通所の利用の方につきましては、１カ月３,０００円の手当を出し、また自力で通所している方については、３,０００円プラスしまして、６,０００円ということで、月６,０００円の手当というか。","voiceIndex":229,"id":"exchange-100"},{"speaker":"飯沼委員","kind":"質問","question":"今のところなんですが、通所事業利用促進支援事業、３,０００円、６,０００円、利用者にというところで、通所日数が９割を超えないと支援されないという厳しい要件があって、９割通えない人、特に精神障害者の方で、通院のために９割を超えられないという方が受けられない。これは代表質問で答弁漏れだったので、再び聞きます。だれもが補助が受けられるようにすべきと思いますが、いかがでしょうか。","respondent":"高橋障害者福祉課長","answer":"精神障害者につきましては、これから対象を外しまして、交通費の全額負担をそのまま継続するというような方向で考えております。","voiceIndex":231,"id":"exchange-101"},{"speaker":"本間委員","kind":"意見","question":"２１７ページ、シルバー人材センター支援事業とあわせてサポしながわ支援事業、それから、２４７ページ、生活保護費関連について、それから、飛んで５３７ページ、介護保険絡みの地域活動連携型介護予防事業について、大きく分けて３つの点についてお尋ねします。","respondent":"永尾高齢事業課長","answer":"現在、どのようなニーズがあって、どういうふうにやったらいいのか、また料金設定をどうしたらいいのか、その辺について検討しています。","voiceIndex":235,"id":"exchange-102"},{"speaker":"本間委員","kind":"質問・要望","question":"特にコンビニサービスということですから、私も、近くにコンビニエンスストアがありまして、よく利用するんですけれども、３６５日２４時間営業ですよね。そういう非常に強い味方がおりまして、助けられていることがあるんですけれども、どうかそのような部分で、これから具体的にいろんなものをやっていくと思います。","respondent":"永尾高齢事業課長","answer":"昨年は、同じ時期で６２８名でしたので、１６０名弱増えている状況になっています。それに伴って、あと、就職の決定者につきましても、２月現在、２４４名決定している状況になっております。昨年の同じ時期の２月の累計と、こちらはほぼ同数になっている状況です。","voiceIndex":237,"id":"exchange-103"},{"speaker":"本間委員","kind":"質問・要望","question":"さまざまな働き方といいますか、部分があろうかと思います。フルタイムでというようなことはないと思いますけれども、労働条件、あるいは勤務の形態等も含めまして、働いている人から苦情の出ないような形をひとつよろしくお願いします。これからどんどん増えていく時代に合わせて対応していただきたいと思います。担い手等についてお知らせください。","respondent":"冨岡高齢福祉課長","answer":"わくわくクッキング事業のねらいですが、認知症予防、あるいは閉じこもり予防ということで、６５歳以上の自立支援の高齢者の方に対しまして、会場にお集まりいただいて、それから一緒に食材の買い物、買い出しをしていただくことにより、簡単な調理。","voiceIndex":239,"id":"exchange-104"},{"speaker":"本間委員","kind":"質問・要望","question":"６５歳以上の認知症予防ということでありますので、わかりました。昨今の食育との関係をお尋ねしようと思いましたけれども、ちょっと仕事の中身が違う形のように思いましたので、ここでやめておきます。微増だということですけれども、生活保護費の支払われ方というんですか、いつどのような形で支払われているのかというのを、渡し方についてお尋ねします。","respondent":"志村生活福祉課長","answer":"ほとんどが銀行口座をつくっていただいてございまして、大体８０％程度の方が振込です。","voiceIndex":241,"id":"exchange-105"},{"speaker":"本間委員","kind":"意見","question":"そうすると、既にそういうルートにのっとってということになろうかと思いますけれども、振込、あるいは現金支給の場合に、新たなメッセージ、ご本人に対して伝える伝達事項等々は行うことがありますか。","respondent":"志村生活福祉課長","answer":"保護費の変更がありますと、その時点で保護の決定通知というのを送付しています。振込はまた別です。","voiceIndex":243,"id":"exchange-106"},{"speaker":"本間委員","kind":"質問・要望","question":"実は、非常に言いにくいことなんですけれども、受給されている方の生活行動様式について疑問を持って苦情を訴える方がおりますので、そのような人の場合には、何らかの手だてで、振込の際、どういうふうにやるのか、あるいは前払いの手渡しのときどのようにやるのか、一言でもメッセージが伝わるとよろしいかと思いますので、ご検討いただきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":245,"id":"exchange-107"},{"speaker":"大沢委員","kind":"質問・要望","question":"私は２１７ページ、定住外国人福祉給付金支給事業、それと２３３ページ、子どもすこやか医療費助成、それと、今ありました２４６ページの生活保護という３点をお伺いいたします。ただ、いろいろなもろもろについては整理をしなければいけないものもあるのではないかと私は思っておりますが、この点について２つお伺いしたいと思います。品川区は、この事業、２３区のうち、何番目にこの事業を行ったのか。","respondent":"高橋障害者福祉課長","answer":"定住外国人福祉給付金関係の事業ですが、高齢と障害の方を対象にするということで、定住外国人の規定の中で、重度の障害のある方ということで、重度の身体障害者、知的障害者の方に対して行われるということで、私どもで事業を計画しております。","voiceIndex":247,"id":"exchange-108"},{"speaker":"大沢委員","kind":"質問・要望","question":"続きまして、２３３ページ、子どもすこやか医療費助成ということ、これについて２点お伺いします。これは、減ったことだから、いいことだと思うんですけれども、この助成について２点質問します。医師にこんなことはないと思うんですけれども、医師による保険点数の不正請求や、また過剰投薬を防止する観点から、区ではどんなチェックを行っているのか、お答えいただきたいと思います。","respondent":"諸岡児童課長","answer":"医療機関のほうから直接区のほうに請求があるということではありませんで、通常の診療費の支払いと同様に、審査支払機関、現在は国保連合会という支払機関のほうにレセプトがいって、そちらのほうに保険適用外の本人負担分を払ってもらう。","voiceIndex":251,"id":"exchange-109"},{"speaker":"大沢委員","kind":"意見","question":"国保連合会のほうで点検を行って、品川区にということです。そうすると、品川区はあくまでも受け身であって、国保連合会に対していろいろな話し合う場というのは、ここにおいてはできないのか、ないのか、そこのところをお聞かせ願いたいと思います。","respondent":"諸岡児童課長","answer":"これは、東京都内、すべて東京都が調整を図りまして、都内の医師会等との連携のもと、支払方法について定めたものです。なお、国保連合会との委託契約につきましては、各それぞれの区で実施しておりますので、その際に、要望等については申し述べる機会はあると理解しております。","voiceIndex":253,"id":"exchange-110"},{"speaker":"大沢委員","kind":"質問・要望","question":"無料という観点から、無料であるがゆえに重複診療が多く発生する危険性もあると思いますけれども、重複診療についてのチェックはどのようにするのか、教えていただきたいと思います。","respondent":"諸岡児童課長","answer":"診療内容のチェックにつきましては、先ほども説明させていただきましたけれども、審査支払機関、国保連合会のほうに、区が委託しているという形で、内容の審査等を行ってもらっているという状況です。","voiceIndex":255,"id":"exchange-111"},{"speaker":"大沢委員","kind":"意見","question":"国保連合会でという、あくまでも主たるものが国保連合会ということになっているんですが、あくまでも区の事業である以上は、区も国保連合会との何かのかかわりというか、意思というか、話し合う場が必要だと思うんですけれども、そこのところをどういうふうにお考えになりますか。","respondent":"諸岡児童課長","answer":"したがいまして、要望事項等があれば、区が直接ということも可能ですが、基本的にはそれぞれの区が連携して、東京都に働きかけて、東京都のほうから調整を図ってもらう、このような流れです。","voiceIndex":257,"id":"exchange-112"},{"speaker":"大沢委員","kind":"提案","question":"不正受給を見抜くにはということで、警察権の行使というほどまでは言ってはいけないものがあると思うんですけれども、やはりそこらの調べることにおいては、そちらの方たちのほうがプロだと思いますので、その辺りのお知恵というか、ノウハウをいただく手だてというのもよろしいかと思うんですが、そこのところ、どのように受けとめられるでしょうか、お願いいたします。","respondent":"志村生活福祉課長","answer":"これが一番多いんですけれども、そのほかに、今、お尋ねの、例えばそういう意味での悪意を持った不正受給といいますか、この辺のことに関しては、例えば生活安全のほうの関係ということでは、直接的には今やってございませんけれども、ただ、ホームレスの問題等については。","voiceIndex":259,"id":"exchange-113"},{"speaker":"大沢委員","kind":"質問","question":"私、調べたところによりますと、生活保護費をもらうがために、わざと、そういう状況をつくってしまうような方たちも増えているということを聞きました。やはり税金、私たちがみんなで築いたお金ですので、そこのところがきちんと執行されますようにお願いを申し上げて、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":261,"id":"exchange-114"},{"speaker":"武内委員","kind":"確認","question":"児童手当の課税の関係です。これについては、午前中の答弁ですと、すべての児童手当を受け取っている方が、税金がかかっちゃうようなニュアンスで受け取ったんですが、そうじゃないと思うんですが、２４万円以上ですか、そういう部分だと思っているんですけれども、そこをもう１回確認したいと思います。そこを教えてください。","respondent":"諸岡児童課長","answer":"あるいは、職につけない方、例えば病気であれば、診断書とか、あるいは、お子さんに障害があって、お子さんの介助のために働けないということであれば、その証明等も添付されれば、２分の１の減額をしなくて済みますのでというようなことを説明して、また。","voiceIndex":263,"id":"exchange-115"},{"speaker":"武内委員","kind":"質問・要望","question":"きめ細かくお願いしたいと要望します。それから、２１５ページの高齢者の住宅用火災警報器、これについては一般質問をやらせていただいて、対象者を拡大して、また低所得者は１,４４０円、１人１台負担しているところを５００円にされるよということで答弁いただいて、非常に感謝しているんですが、そうすると、この当初予算のほうでは、前の数字が載っているわけですよね。","respondent":"冨岡高齢福祉課長","answer":"当初予算につきましては、今おっしゃったことを含めまして、予算化している金額です。","voiceIndex":265,"id":"exchange-116"},{"speaker":"武内委員","kind":"質問","question":"そうですか。別にいいんですけれども、もともとそういう説明もいただいていませんでしたし、あと、説明資料の中で、例えば拡充する事業は下線を引く、また丸、二重丸と教えていただいている中で、高齢者の火災警報器、これはなっていませんよね。これは予算を見ても、もともと１,４４０円で設定して予算立てしたわけでしょう。そこだけ教えてください。","respondent":"日下部企画財政課長","answer":"議会に対する説明資料の関係ですので、私からお答えします。下線の問題につきましては、基本的には前年と同額ということで、そういう関係で下線を引いていない、そういうものです。","voiceIndex":267,"id":"exchange-117"},{"speaker":"武内委員","kind":"提案","question":"そこで、私が無料と言ったのは、例えばこれが５００円になれば、２基で１,０００円ですから、１,０００円と無料とどう違うんだというと、大して金額的には変わらないと思うんですけれども、ただ、お金がかかることを民生委員が、あまり積極的につけましょう、つけましょうとできないんじゃないかなと。そういう意味で、私は無料でと提案したんですけれども、そこのところをもう１回見解を教えてください。","respondent":"冨岡高齢福祉課長","answer":"できるだけ多くの方にご理解をいただいて、つけていただくという形は進めてまいりたいと考えています。","voiceIndex":269,"id":"exchange-118"},{"speaker":"武内委員","kind":"質問・要望","question":"わかりました。無料、無料じゃないということはこだわっておりませんけれども、なるべくとにかく普及を、あと１年でありますので、区としてできる限り普及させていただきたいということで、それで、また民生委員の方も、さっきあったとおり、説明をよくしていただいて、お願いするしかないと思いますので、またそれ以外の方法もぜひ探っていただいて、お願いしたい。これは要望を最後にします。","respondent":"冨岡高齢福祉課長","answer":"平成２１年度の地域見守りネットワーク事業ですが、今年度、見守り体制を、モデル事業を実施するということで、今年度、大森団地で１つのモデル的に実施をしたのと、あとは、荏原の管内で、住宅街のところで、配食ボランティア等、会合を持って。","voiceIndex":271,"id":"exchange-119"},{"speaker":"武内委員","kind":"質問・要望","question":"高校生が下校時に黄色のマークをかけていく。これが意味するところは「お元気ですか」ということなんですね。下校時にかけていって、翌日の登校時に、これが裏返っていれば「元気です」というマークだという。これは要望します。一部自治体でも補助しているところもあるんですが、こうしたものもぜひ日常生活用具の中に加えてもらえないか、こういう声があったんですけれども、見解について教えてください。","respondent":"高橋障害者福祉課長","answer":"しかし、ソフトを支給したからということで、パソコンと相性がいいかどうかということと、使いこなせるのかというところで、検討会の中でも、大分論議がありまして、そこのところでは、専門家集団と連携が必要ではないかというところで、品川区心身障害者福祉会館にある。","voiceIndex":273,"id":"exchange-120"},{"speaker":"武内委員","kind":"質問・要望","question":"ぜひ検討していただいて、なるべくこういう形で来年度ぐらいからできるように要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":275,"id":"exchange-121"},{"speaker":"藤原委員","kind":"質問・要望","question":"２３５ページ、次世代育成支援対策費、２３９ページ、保育園運営費、それと２４５ページの家庭あんしんセンター、ファミリーサポートセンターについてお伺いしますが、まず保育園からお伺いします。ただ、１カ所ということがやっぱりネックになると思っています。将来でいいですから、品川区でこの制度をどういうふうに展望として考えていくのか、教えてください。","respondent":"小林保育課長、福島長期計画担当課長、諸岡児童課長","answer":"そういった方々に対して、とにかく今、できる努力をしようということで、まだ園で持っております一時保育の枠等を活用して。こちらは、確かに全庁的に行うということで、企画部が行ってございましたが、これは平成１７年に推進計画ができまして、推進してきたものです。現在２カ所体制で実施しておりまして、昨年、大井の開設の前は、提供会員、サービスを提供してくださる会員の方が１７７名でありましたけれども。","voiceIndex":278,"id":"exchange-122"},{"speaker":"藤原委員","kind":"質問","question":"ファミリーサポートセンターの件ですけれども、私の質問は、将来的に増設はするんですかと伺ったので、そこを答えてください。ということは、結婚サポートで、またお子さんの数が増えるじゃないですか。そういう施策ですから、増えていきますよね。保育園の場合は、増設だけじゃないですよ。毎回質問して、さまざまな努力とおっしゃってくれるんですけれども、やっぱり入れない方が増えてくる。","respondent":"諸岡児童課長、小林保育課長、福島長期計画担当課長","answer":"ただ、品川区は児童センターが大変充実しておりますので、一部、子育て支援センターの役割も担っている部分もありますので、そういった意味で。施設、入れなければ意味がないということでは、施設のサービスを充実、維持していくということと同時に、今後の課題として。企画部のほうの支援といいますか、応援も行っていく予定です。","voiceIndex":282,"id":"exchange-123"},{"speaker":"藤原委員","kind":"質問","question":"５つの都市像、新構想の中で、「未来を創る子育て・教育都市」と、５つの中に１つに入っていますよね。今、ワークライフバランス、それがバランスじゃなくて、アンバランスになっちゃうじゃないですか。入れる人と入れない人。だから、課長、熱意あると思いますが、もう１回待機児の熱意の答弁をしていただけますか。","respondent":"小林保育課長","answer":"待機児の解消に向けて、いろいろな方策を講じながら、一生懸命進めてまいります。","voiceIndex":286,"id":"exchange-124"},{"speaker":"南委員","kind":"質問","question":"介護保険特別会計の問題と２２１ページの緊急通報システム、この問題を質問したいと思います。１つのほう、私、請願紹介議員になったので、不採択になったことは非常に残念であります。請願者の方々からいろんな状況もお話を聞きましたので、そういうところで受けとめた思いも含めて、この質問をしたいと思います。そうしたら、倒れていた。その辺の認識はどういうふうに持っているのか、まず伺います。","respondent":"冨岡高齢福祉課長","answer":"緊急通報システムですけれども、これはひとり暮らしの高齢者の方、また、高齢者世帯のご夫婦などの緊急事態における不安の解消と生活の安全を図るという目的で実施をしているものでございまして、不安解消ということで役に立つ事業であると理解しております。","voiceIndex":289,"id":"exchange-125"},{"speaker":"南委員","kind":"質問","question":"そのほかに、よくよく資料を読んでみると、プラス３００円かかるんです。ですから、２,１００円、毎月毎月かかるんですね。ですから、８０万円以下の低所得者の負担額が、毎月、都合１,３００円なんですよ。この金額、どう思いますか。そして、２,１００円もかかるような毎月の負担をもっと低減する、こういう方向に踏み出すべきだと思うんですけれども、その点についてはいかがでしょうか。","respondent":"冨岡高齢福祉課長","answer":"費用のご負担ですけれども、一律１,８００円ということでお話がありましたが、所得の第１段階、第２段階の非課税の方については、１,０００円という形で、それ以外の方というふうに２段の費用のいただき方をしているということでございまして。","voiceIndex":291,"id":"exchange-126"},{"speaker":"南委員","kind":"確認","question":"私は、先ほども申し上げましたけれども、少なくとも命の問題ですから、だれからも倒れたことを気づかれないで一晩中過ごす、そういう方々に、これだけの負担してもらわなきゃつけられないよ、こういう区政を続けるのかどうか、こういう問題です。ぜひこれは検討するべきだと思います。そういう仕組みですね。その辺の確認をしたいと思います。保険料が上がっても仕方がない、こういう認識なんですか。","respondent":"冨岡高齢福祉課長","answer":"市町村特別給付といいますのは、法律で定められた全国共通の介護給付とか予防給付以外の給付でございまして、制度的に確立されてない部分について、独自の給付をし、被保険者の方にサービスを提供するですので、これについては、横出しサービスということでございまして。","voiceIndex":293,"id":"exchange-127"},{"speaker":"南委員","kind":"質問","question":"そういうふうに考えての措置なのかどうか、そこの答弁がありませんので、ぜひお願いしたいと思います。これに比べて品川区は幾らですか。２億円、３年間でね。そういうことで今回、保険料を、取り崩して、低減させるよう努力されたわけですから、もっとそこをしっかりと太いパイプにして、区の基本姿勢に置くべきだと思うんです。３年間で２億円余も使うというのは、どういう検討の中で出てきたんですか。","respondent":"冨岡高齢福祉課長","answer":"しかも、それは介護認定を受けている方の部分ですので、これは保険料で特別給付で扱わせていただくというような考えで、今回の特別給付というところでなったわけです。","voiceIndex":295,"id":"exchange-128"},{"speaker":"南委員","kind":"確認","question":"確認をしたいと思います。それから、２つ目の質問は、横出しサービスすることによって、３年間トータルで２億４００万円使われます。これが後に保険料の値上がり、こういうことになる大きな原因になるわけですけれども、２億円余も使うというのはどういう検討の中で出てきたのかということを聞いたんです。これは高齢者１人当たりにすると幾らになるんでしょうか。そのこともつけ加えます。","respondent":"木下福祉高齢事業部長、冨岡高齢福祉課長","answer":"基準額が同じでほとんどの段階が引き下げになっているということは、保険料全体の収入も下がっているということになるわけでありますけれども、今のお尋ねの部分についていえば、私どもとしては。１人当たりです。今までのリハビリの関係を除きますと、５０円ぐらいだと思います。","voiceIndex":297,"id":"exchange-129"},{"speaker":"南委員","kind":"質問","question":"５０円というのは厚生委員会の答弁と全然違う額です。厚生委員会では７８円とおっしゃったんですよ。どちらが正しいんでしょうか。","respondent":"冨岡高齢福祉課長","answer":"厚生委員会での答弁はリハビリを含めておりまして、申しわけございません。除きますと、そういう額になっているです。","voiceIndex":300,"id":"exchange-130"},{"speaker":"南委員","kind":"質問・要望","question":"そういうことになるんじゃないですか。ですから、私はもっともっと堂々と実施するべきだと。同じ１,５４０円程度に設定している葛飾区は、９段階なんですけれども、最高額を８００万円にしているので、これがまた高額所得者の負担がそれなりに月額７,７００円になっているんですけれども、こういう状況になっているということなんですけれども、改めて厚生労働省の保険料設定の考え方を伺いたいと思います。","respondent":"冨岡高齢福祉課長","answer":"保険料の設定の仕方ですが、今回、介護報酬の改定もあります、第４期の給付費を見込みながら、安定的に給付ができるよう、それから、所得の段階についても、６段階ではなく、多段階ということで、細かくできるように設定するという方針で求めておりますので、区といたしましては。","voiceIndex":302,"id":"exchange-131"},{"speaker":"南委員","kind":"質問","question":"私が、先ほど申しましたように、３００万円にとどめているのは品川区だけなんです。１,０００万円に最高額を設定したのは１５区です。これは２３区のうちの３分の２なんですね。こういうふうに介護保険料の問題でも、そして、先ほど一番最初の質問の緊急システムの問題でも、本当に区民の方たちが安心してここで暮らせるという姿勢に本当に薄い、そういう品川区を、私は、改めるべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":304,"id":"exchange-132"},{"speaker":"須藤委員","kind":"確認","question":"２１５ページのひとり暮らし高齢者等福祉費のところで、緊急通報システムの台数が高齢者のほうは入っているんだけど、２２１ページの障害者のほうには、台数が、消防庁型、民間型とかというのが全然入ってないので、その辺の統一はどういうふうにしているのかなというのが１つあるのと、それから、ひとり暮らしの高齢者等福祉費、２１５ページで、高齢者世帯の安否確認事業に。","respondent":"日下部企画財政課長","answer":"２２３ページに出てまいります、今ご質問にございました高齢者施設、障害者施設、これは機能別、性質別にということで、できる限りわかりやすくということでまとめしていますけれども、ただ、これは率直に申し上げまして、例えば２２７ページをごらんいただきますと。","voiceIndex":306,"id":"exchange-133"},{"speaker":"須藤委員","kind":"確認","question":"もう一つ、火災報知機が安否確認に何で入るのか。","respondent":"冨岡高齢福祉課長","answer":"安否確認というのは非常に広い意味でとらえさせていただいておりまして、例えば以前からあります自動消火装置というのも、認知症の方が家庭で火を使われたときに、火が出た場合には、自然に消えるというようなところ、こういうのは安否の確認かどうかというと。","voiceIndex":308,"id":"exchange-134"},{"speaker":"須藤委員","kind":"質問・要望","question":"２０７ページの品川介護福祉専門学校の修学資金で、来年度の入学者の状況が、こういう景気態勢でどういうふうになってきているのかということと、それから、現在、学校ができて１０年ですか、もう大分なりますけれども、卒業生がどのぐらいトータルで品川区に就職されて、いまだに何人ぐらい継続しているのかなというあたりを教えていただきたいのと、それから、先ほど山内委員が質問した外国人の入学。","respondent":"冨岡高齢福祉課長","answer":"今年度の入学予定ですけれども、昨年度と比べて、３月半ばの今日の段階で予定者が３５名ということで、昨年よりは、おかげさまで、定員には達しませんが、３５名になったと最近の情報で聞いております。それからあと、卒業生の区内の就職の状況です。","voiceIndex":310,"id":"exchange-135"},{"speaker":"須藤委員","kind":"質問","question":"入学の規定は、学校のことだから、直接じゃないので、申しわけないです。卒業生４５６名で、２６２名就職されて、その後どのくらい現在も頑張ってくれているのかなというのが、結局品川区で頑張ってくれることが修学資金を出すという大きな目的だったと思うんですが、そのあたりがどの程度の数字になっているのかなと。わかれば教えてください。現在何人ぐらい続いているか。","respondent":"冨岡高齢福祉課長","answer":"引き続き区内で就職されている方については、申しわけありませんが、今のところは把握してございません。","voiceIndex":312,"id":"exchange-136"},{"speaker":"須藤委員","kind":"質問・要望","question":"それはまた次の何かの機会に教えてもらいます。次に２１１ページ、法人に対する助成金、いろいろな法人があるんですが、この辺の数字の差というのは、基準が当然あろうかと思うんだけれども、どういうふうな基準で法人の助成がされているのか、教えていただきたいと思います。","respondent":"冨岡高齢福祉課長","answer":"例えば事業を開始するとき、あるいは設備をつくるときに、借り入れをした部分の返還金の助成の部分とか、あと、大規模な施設を改修するときの助成の部分とか、さまざまなところがございまして、あとは、機械の部分とか、備品関係の部分とかがございまして、そういった形で。","voiceIndex":314,"id":"exchange-137"},{"speaker":"須藤委員","kind":"質問・要望","question":"こうほうえんというのが２５０万円、施設運営費を助成されているんですけれども、西大井いきいきセンター事業、地域交流、それから、コミュニティレストラン事業とか、いろいろ入ってきているんだけれども、このあたりは、区側からこういう仕組みでというようなお願いをしたのか、こうほうえんが運営する上で、こういうものが必要だよという話で、こういう助成の仕組みになったのか。","respondent":"永尾高齢事業課長","answer":"最後のコミュニティレストラン事業助成ですが、こちらは、区のほうで新しく始める事業ですので、区のほうの積算でお願いしたところです。","voiceIndex":316,"id":"exchange-138"},{"speaker":"須藤委員","kind":"質問","question":"２１５ページ、地域見守りネットワーク、区長の施政方針にも載せてあるんですが、先ほど担当課長の答弁では、町会と自治会、地域でモデルをやったので、その後、地域で特色あるようなやり方を組んで、行政は行政でまた考えたいというようなご答弁をいただいたんだけど、区長の施政方針がポンとそこでネットワークをつくりますというような方針を立てているのに、それから。","respondent":"冨岡高齢福祉課長","answer":"申しわけありません。私の表現の仕方がまずかったかと思います。","voiceIndex":318,"id":"exchange-139"},{"speaker":"須藤委員","kind":"質問・要望","question":"品川区の所帯の人数が平均すると１.８人ぐらい。最後になりますが、２２７ページの心身障害者福祉会館の施設運営費で、高次脳機能障害に対しての考え方、ここで対応してほしいというようなことをお願いしたんだけれども、そのあたりはどういうふうになるでしょうか。","respondent":"高橋障害者福祉課長","answer":"したがいまして、具体的に運営をそのまま継続しますので、継続しながらそこの部分の検討を含めて進めするというような内容になります。","voiceIndex":320,"id":"exchange-140"},{"speaker":"阿部委員","kind":"質問","question":"私からは、まず２１５ページ、家具転倒防止対策助成について、２３２ページ、児童福祉費の中で、区の事業とは直接関係ないんですけれども、品川景徳学園の民間移譲に対する区の考え方について、次に、２３８ページ、保育園運営費、特に待機児童について、それから、関連して、空き店舗活用型保育サービス等についてもお伺いします。現在の考え方で構いませんので、お願いします。お考えを伺いたいと思います。","respondent":"永尾高齢事業課長、諸岡児童課長、小林保育課長、冨岡高齢福祉課長","answer":"平成２１年度の目標ですが、平成２１年度は１５０件を目標にやっていきたいと考えております。そういった情報提供等、連絡等あった時点で、今後東京都と連絡して、どのようなことを進めていくかを含めて、検討していきたいと考えております。今後の対応として、フルタイム等について、それぞれ認証保育所、その他の対応ができる家庭はよろしいかと思うんですけれども。","voiceIndex":324,"id":"exchange-141"},{"speaker":"阿部委員","kind":"質問・要望","question":"家具転倒防止なんですけれども、平成１９年度から大きく伸びているということですが、目標のほぼ半分ちょっとぐらいかなと思います。こちらのほうは要望にしておきます。保育園待機児なんですけれども、もちろん認可園を増やしていただきたいというのは常に要望として持っておりますし、それなりの努力もしていらっしゃることと思います。こちらについてもお考えをお伺いできればと思います。","respondent":"永尾高齢事業課長、小林保育課長、冨岡高齢福祉課長","answer":"確かにもう少し若い世代に対してもそういうような配慮があってもいいかなというのはよくわかりますが、とりあえずは、始めてまだ数年ですので。もちろん家庭で親が育てる、この代替として保育園で保育者が育てるに対して、今後は地域で支えられる人たちで育てていくという視点、人づくりのところから。私どものところには在宅の方のさまざまなご要望がありまして、そのピアカウンセリングという形では届いておりませんけれども。","voiceIndex":329,"id":"exchange-142"},{"speaker":"若林委員","kind":"質問・要望","question":"４点。聴覚障害のほうですが、障害者自立支援法によりまして、要約筆記の派遣に関する実施要綱等の課題が品川区のほうにまだ残っているやに伺っておりますけれども、今年度からまた来年度に向けて、現在どのような状況か、お聞かせいただきたいと思います。そのことについてお聞きしたいと思います。","respondent":"高橋障害者福祉課長、冨岡高齢福祉課長","answer":"要約筆記につきましては、国レベルの部分、もしくは要約筆記という内容のところについては、共通な認識のところがまだ整理されてないという段階ですので、その辺については、十分状況を見ながら。協力員の現状ですけれども、協力員につきましては、民生委員が不在のところで、地域につきまして、協力員という方、これは民生委員を退任された方ですけれども、お願いして、現在、２人の方をお願いしていますが。","voiceIndex":334,"id":"exchange-143"},{"speaker":"若林委員","kind":"質問・要望","question":"特に今回、知的のほうの方との協働、共助という言葉でしたけれども、協働のような形の事業が立ち上がってまいりましたので、ぜひここら辺の部分にも協働という視点で、実施要綱をまた早急に進めていただきたいなと要望をします。","respondent":"高橋障害者福祉課長、冨岡高齢福祉課長","answer":"障害者７団体懇談会ということで、具体的に参加している団体がありますので、この事業を説明し、どういうことを各団体と協働でやれるのかというところも含めまして、それぞれの団体に説明させていただきたいと思いますので。民生委員も研修会がございまして、お互いに自分のいろいろな仕事でぶつかっている問題とかを話し合われて、それぞれアドバイスや何かがあり、先輩の方は後輩とお話しするとかということで、かなりそれは。","voiceIndex":337,"id":"exchange-144"},{"speaker":"若林委員","kind":"質問・要望","question":"１つだけ。７団体の中でとありましたけれども、今回、ＮＰＯをこれから立ち上げるという予定ですが、こういう法人にならないと、なかなかこういう形にはならないのかという考え方をひとつお聞かせいただきたいと思います。","respondent":"高橋障害者福祉課長","answer":"障害者自立支援法の指定事業所にならないと……。","voiceIndex":340,"id":"exchange-145"},{"speaker":"須貝委員","kind":"質問","question":"私は、３９８ページ、国民健康保険料と後期高齢者医療、そして、介護保険の全般について、あと、時間があれば保育園運営費についてお聞きしたいと思います。このような人たちを国保難民と言うようですが、厚生労働省の発表では、今の日本では、国保加入世帯のうち、約２１％の約４５０万世帯がきちんと国保料を納められず滞納しているということです。品川区内の滞納世帯数はどのぐらいあるんですか。","respondent":"本城国保年金課長","answer":"平成１９年度末の数ですが、加入世帯８万１,０００世帯のうち約１万８,０００世帯が滞納世帯ということで勘定しておりますが、この場合の滞納というのは、１回でも納め忘れている方はすべて含んだ形の滞納になっておりまして、率といたしましては、１９.２％です。","voiceIndex":343,"id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"そこで、介護、先ほどの生活保護もそうなんですが、昨年と比較して、品川区では一体どれだけの方をお救いしたというか、こうやって守ってきたんですよと、そういう数値は出しているんでしょうか。ただ事業をやっているということだけで、それで予算化して、それを遂行しているということで終わっているんでしょうか。その辺、もし人数等あればお聞かせください。でも、ここだけは言っておきます。","respondent":"木下福祉高齢事業部長","answer":"それは１つには、自助努力といいますか、個人でやる部分、それからもう一つは、制度として対応する部分というのがありまして、そういう点でいうと、本会議のときにもちょっと申し上げましたけれども、多層構造のセーフティネットというのがあるわけですから、つまり。","voiceIndex":345,"id":"exchange-147"},{"speaker":"須貝委員","kind":"質問","question":"確かに保護者の生活環境などを見れば、ある程度そういう方たち、大変だから、優先しようということも理解できるんですが、同じ働かなきゃならない、品川区内に在住して、そこで困ったので保育園に預けたいという方が入園できないという仕組みは、長年住民税を納めてきて暮らしてきた親の心情を思えば、入所ポイントの中に品川区内の在住期間も加算ポイントとして加えるべきじゃないかと思うんですが。","respondent":"小林保育課長","answer":"現時点では、区に在住している年数等を調整指数に盛り込んでいくのは慎重に対応していたきいと考えています。","voiceIndex":347,"id":"exchange-148"},{"speaker":"石田（秀）委員","kind":"提案","question":"そうすると、これは我々が海外調査に行ったときの提言書でも、提案もしてあるんで、だから、もうご存じだと思うけれども、例えばドイツとかノルウェーは、ゼロ歳児保育というのはないわけです。それぐらいのことをそろそろ考え出してやっていくべきで、もし考えても、やっぱり国となってしまうなら、どういう動きをかけるかということも含めて、考え方があったら、教えてください。","respondent":"永尾高齢事業課長、小林保育課長","answer":"その中での機能をまた変更しつつ、そういう方にも楽しんでいただけて、また新しい方にもそういうところに入って、別の楽しみをしていただくということで、融合を図っていきたいと考えております。それは、ある意味では、広域での対応が必要となると思いますので、その点につきましては、引き続き構造を考えていただきながら、ご議論いただいて、社会的な制度を整えていく必要があるかと思いますが、一方、ローカルな品川区として。","voiceIndex":351,"id":"exchange-149"},{"speaker":"石田（秀）委員","kind":"質問","question":"だけれども、シルバー人材センターという場合は、私の感覚でいくと、平成１７年ぐらいから今見させてもらったけれども、売り上げがずっと１２億円強。登録人数は約２,４００人、２,３００人とか、二千何百人という方が登録している。ほかのところは別ですが、そういうことも私は考えるべきだろうと思っているので、そのところの考え方を教えてください。だけど、最初の２つはよろしくお願いします。","respondent":"永尾高齢事業課長","answer":"シルバーセンターのほうの運営についてですが、これからは少し若い人、団塊の世代以上の方が利用できるような施設を考えたいと考えています。例えばパソコンの導入とか、そういうことも検討の中に入れていきたいと思います。","voiceIndex":354,"id":"exchange-150"},{"speaker":"石田（秀）委員","kind":"意見","question":"シルバー人材センターというところがあって、これでお願いしますとか、交渉の中で安くして、だけど、運営費補助は出すと。そうじゃなくて、ある程度、さっきも言ったように、安価という部分もあるなら、それは、独立して、ある程度の部分はそこで運営してくださいと、その金額が余ったらそれで払えばいいんだから、私はそのほうがしっかりこれからできると思うので、それはもう一度考えてほしいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":356,"id":"exchange-151"},{"speaker":"川西委員","kind":"質問・要望","question":"時間がありましたら、生活保護について、簡単な内容について伺います。それから、いきいきラボ関ヶ原の屋上の防水に関してなんですが、これもほかの科目に入ると言われるといけないんですが、防水を機会に、今、遮熱性塗装、周囲の温暖化の関係もありますが、２度外気の温度が下がるという、これが、こういう防水をする機会に、公的施設ですから、取り入れられないのかどうかというのが質問です。","respondent":"冨岡高齢福祉課長、高橋障害者福祉課長、宍戸施設担当課長","answer":"福祉人材確保の中身ですが、これは今年度、平成２０年度も実施しておりますヘルパー２級の資格取得の支援も含めた部分ですが、それ以外のここの部分は。いきいきラボ関ヶ原の場合、ＲＣ造ですので、どういうふうな効果があるのかというのをもう一度検証しながら、実施設計の中で検討してまいりたいと思います。","voiceIndex":358,"id":"exchange-152"},{"speaker":"川西委員","kind":"質問・要望","question":"ですから、私は品川児童学園の事業かというふうに思って伺っているんですが、品川児童学園ではどの程度のことをやっていただけるのか。そこだけ伺って、あとは、自分で勉強することにいたします。いきいきラボ関ヶ原の屋上の遮熱性なんですけれども、款を別にいたしまして、これはご答弁はいいですから、別のところでもう１回やりますけれども、もう少し積極的にお考えをいただきたいと思います。","respondent":"高橋障害者福祉課長、冨岡高齢福祉課長","answer":"１つが知的障害者の児童デイサービスということで、ちびっこたいむ品川で療育事業を行うもの、もう一つが、発達障害者に対する児童デイサービスということで、品川児童学園でコンパスということで。福祉人材再チャレンジ応援講座事業で考えておりますのは、現場に、就業に結びつけるということではありますが、直接的にヘルパー２級の講習会をやるということではございません。","voiceIndex":362,"id":"exchange-153"},{"speaker":"川西委員","kind":"質問・要望","question":"ですから、この関連というのは、どういう内容なのか、もう１回教えていただきたいのと、それから、既にご答弁の中でありましたように、東京都が、今、出しておりますチャイルドステーション、赤ちゃん・ふらっと事業は、まちの中に、子育ての支援をする施設だということでやっておりますが、この予算というのは、いただいた資料でよくわからないんですが、全額、区の単独予算なのかどうか。","respondent":"諸岡児童課長","answer":"ハード整備ということで、補助金対象事業ということで立ち上げてまいりました。品川区としましては、この赤ちゃん・ふらっと事業にも対応して、補助金を利用して施設整備を図っていきたいと考えているものです。","voiceIndex":365,"id":"exchange-154"},{"speaker":"川西委員","kind":"質問","question":"ありがとうございました。子どものことに関連して、予算にないことを１つ伺います。そういう方は育児休業というのは、自分の会社ですから、自分で認めなきゃならないということがあって、これは、保育園の入所の継続が認められないという話がありますけれども、この辺の基準についてちょっと伺いたい。","respondent":"小林保育課長","answer":"それに伴って一時的には保育に欠けない状態になるということもありますが、品川区につきましては、子どもの安定的な措置という観点もありますので、該当年度末までは継続してお預かりするなど、その状況に応じた対応をやっているところです。","voiceIndex":367,"id":"exchange-155"},{"speaker":"川西委員","kind":"質問","question":"育児休業法の対象にならない自営業ですよね。しかし、子育てはできるだけ、今もいろんな話の中で出ておりますように、ゼロ歳、１歳は自分の力で、親のもとで育てたいという方も、今、いっぱい出てきております。そういう点で、今、育児休業、企業では３年くらい、あるいは学齢までという大きな企業もありますけれども、多少考慮していただければよいと思います。私はセットだと思っておりましたから。","respondent":"志村生活福祉課長","answer":"これは、生活保護の基準を当てはめていくときの順番になってあります。ですから、なかなかご説明しづらいんですけれども、生活扶助から充てていきます。それから、住宅に充てていきます。最後に医療費の部分まである方については、そうやってあります。","voiceIndex":369,"id":"exchange-156"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、生活保護は受けなくてもいい。医療扶助だけ受けたいという場合は単独でできるんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":371,"id":"exchange-157"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私は２４６ページの生活保護費について伺いたいと思います。時間がありましたら、生活安定応援事業についても伺いたいと思います。今、格差貧困というか、貧困の広がりというのは本当にひどくなってきているなと私も思います。とりわけ今、私のところでは、お年寄りの暮らしが崩壊する、そういう事態が広がっている、そういうケースが多くなっていると感じております。","respondent":"志村生活福祉課長","answer":"ご本人のまず意思の尊重が２番目になってまいりますので、そこで確認をしながら、例えば今ご質問にありましたとおり、住むところ、それから仕事もない、こういうことになりますと、今、私どもで路上生活の事業につきまして、東京都と共同してやってあります。","voiceIndex":373,"id":"exchange-158"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そういう方が不景気で一気に仕事をなくして、見る見る生活が崩壊していくという状況は何人か見ているんですけれども、そういう実態があるので、私は伺っているんですけれども、先ほど民生委員に生活保護の制度を知ってもらう。そういうことをやっていると答弁があったんですけれども、それについて、どんな目的で、どういうことをやっているのか、説明をいただきたいと思います。","respondent":"志村生活福祉課長","answer":"したがいまして、毎年、生活保護費の基準改定という作業がありますので、それにつきましては、１３地域センター単位ごとにあります民生委員協議会に行って説明をしています。","voiceIndex":375,"id":"exchange-159"},{"speaker":"宮崎委員","kind":"質問","question":"そうじゃなくて、私は、いろんなところでそういう情報を行政の側でもキャッチできるんじゃないかと。先ほど生活保護制度の周知等、質問していますけれども、私はもっとこの制度を知ってもらうというのが必要だと思うんですけれども、その考え方を聞きたい。そういう方が何人もいました。困ったら来いじゃなくて、そういういろんなアンテナを張る必要があるんじゃないかと思うんですけれども、どうでしょうか。","respondent":"志村生活福祉課長","answer":"具体的な例ですと、入院をして、今、ベッドから起き上がれない。こういうときには、ご連絡をいただきまして、私どものほうから出張して、面接して、保護を開始する。こういうふうになってあります。年１回ですけれども、宅建の方とこうした連絡もとってあります。","voiceIndex":377,"id":"exchange-160"},{"speaker":"宮崎委員","kind":"質問","question":"宅建の方と協議されているということは大事なんですけれども、大家がよく知っていないなという実感があります。ですから、ある意味では、大家にとってもしっかりこういう制度を知っておく必要があると思うんですけれども。そういう事態にならないようにするというのが、生活保護の精神じゃないかと思うんですけれども、もう一度聞きたいと思います。","respondent":"志村生活福祉課長","answer":"生活保護の申請に当たりましては、ご本人の意思の確認をしろと、こういうことになってありますので、最低限これが必要だと考えています。","voiceIndex":379,"id":"exchange-161"},{"speaker":"宮崎委員","kind":"質問","question":"それは前提の話で、その前の情報収集というか、アンテナを広げてほしいということを言っているわけで、もう一度しっかりご検討をお願いしたいと思います。","respondent":"志村生活福祉課長","answer":"生活安定応援事業ですけれども、歳入のときにもお答えしましたとおり、今年度の８月から事業を開始したものです。２月末現在ですけれども、私どもの窓口、相談係のところに設けてありますけれども、来られた方につきましては、２５６名。","voiceIndex":381,"id":"exchange-162"},{"speaker":"宮崎委員","kind":"質問・要望","question":"先ほど、例えば家賃だけの方法とかという、そういう制度は考えられないかというのを答弁いただきたいのと、私、今の生活安定化のところでは、生活費の貸し付けとなると、現に困っている人の制度としては、ちょっとここのところは難しいんじゃないかと思うんですけれども、その点についてもお考えをいただければと思います。","respondent":"志村生活福祉課長","answer":"すみません。答弁漏れで申しわけありませんでした。家賃だけの補助というのは、制度的にはございません。ただし、先ほどの川西委員のご質問にちょっと言葉足らずだったんですけれども、生活保護の仕組みとして、例えば収入を充てていきます。","voiceIndex":383,"id":"exchange-163"},{"speaker":"堺委員","kind":"質問・要望","question":"最初に、２１１ページの訪問介護、この関係ですが、これも冒頭の説明によりますと、緊急総合経済対策の継続分であるというふうなご趣旨のご説明だったかと思いますが、これにつきまして、一応確認をする意味で、この事業内容について教えていただきたいのと、あわせまして、こういう事業に携わっておられます区内の事業所数というんでしょうか、また、その中で、特に１０人未満の事業所数というんですか。","respondent":"冨岡高齢福祉課長","answer":"中身につきましては、ヘルパー２級を取得されるために、事業所にお入りいただく方にヘルパーの２級の取得の講座を受けていただく部分、それと、その講座を受けていただく方に対しまして、事業所はその方を雇用するわけですので、お仕事ができるまでの間、その間。","voiceIndex":386,"id":"exchange-164"},{"speaker":"堺委員","kind":"質問","question":"そうすると、平成２０年度の緊急総合経済対策、それから平成２１年度の本予算で同じ金額で５０人。その説明会に声をかけて参加された事業所数というんでしょうか、またその中の事業所の中で、例えば１０人未満の事業所が何名ぐらいその説明会に参加されたのか、その辺の説明会の開催状況、その辺についてもお知らせいただけますか。","respondent":"冨岡高齢福祉課長","answer":"今の説明会につきましては、１月２０日に実施をさせていただきました。参加をいただいた事業所が２５事業者です。１０人未満の企業については、申しわけありません、把握をしてございません。","voiceIndex":388,"id":"exchange-165"},{"speaker":"堺委員","kind":"質問","question":"区としては、やる以上は説明会をやって、そこに事業所が参加をされた。そこで、区としてその事業の説明をされたんだろうと思うんですが、今度はその後の手続きとしては、その事業所のほうから区のほうに申請をするという流れになってくるんだろうと思うんですが、その辺の申請状況はどうなんですか、これからですか。その辺のところも教えていただけますか。","respondent":"冨岡高齢福祉課長","answer":"１月の説明会の後、１週間ぐらいのところである程度のご希望ということで申請をいただきまして、その段階で５０名ということで、申請をいただきました。そして、審査をいたしまして、２月中につきましては、支出をさせていただいた。","voiceIndex":390,"id":"exchange-166"},{"speaker":"堺委員","kind":"質問","question":"そうすると、緊急総合経済対策の中での５０名の枠については、既に申請があったと。これから具体的に、そういう人が合格するというんですか、その選に入るかどうか、そういうことになってくるだろうなと思うんです。こういう記事があるんです。こんな指摘もあるわけです。これはある一定の枠があるんだろうと思うんですが、そういう面で、その辺のところについての考え方を少し教えていただければと思います。","respondent":"冨岡高齢福祉課長","answer":"基本的には経営努力をしていただくということが一番ですけれども、さまざまな会議、あるいは個々の指導の場面というのはあるかと思います。そういうところで状況を把握するとともに、一定の支援を今後ともしてまいりたいと考えているところです。","voiceIndex":392,"id":"exchange-167"},{"speaker":"堺委員","kind":"質問","question":"そうしますと、今回の予算、後期行動計画策定、６４０万円、これは前期がたしか平成１７年度から平成２１年度まで、前期を踏まえて後期の計画が策定されるということになるんだろうと思うんですが、当然後期の分をつくるに当たっては、前期に計画した分についての検証というんでしょうか、評価というんでしょうか、そういったものが会議の中で行われて。","respondent":"福島長期計画担当課長","answer":"前期の検証および評価、さらにはスケジュールの件ですが、まず前期の検証、こちらにつきましては、平成２１年度に後期計画をつくってまいりますので、推進協議会のほうで十分前期計画の評価、検証を行った上で、後期計画をつくっていくという予定です。","voiceIndex":396,"id":"exchange-168"},{"speaker":"堺委員","kind":"質問","question":"基本方針、基本目標、それから推進計画、こういう４段階といいましょうか、そういう形でこの計画が練り上げられているわけですけれども、そうしますと、今回、後期の中では、最後の推進計画という、この部分だけが変更されてくるのか。要するに、ここで言われている基本理念、基本方針、基本目標、こういったものも当然俎上に上がってくるのか、その辺の考え方も教えていただけますか。","respondent":"福島長期計画担当課長","answer":"当然ながら、基本理念、あるいは基本方針、基本目標、それらも含めまして、一度推進協議会のほうにお諮りしまして、このまま進むかどうか、検討していただく予定です。","voiceIndex":398,"id":"exchange-169"},{"speaker":"鈴木（真）委員","kind":"質問","question":"例えば年間に体調を崩される方というのはどのぐらいいるのかなというのも、我々、ちょっとわからないんですが、知っている方でも急に体調を崩されちゃった方というのもいますので、そういう考え方でどうかなというのが１点です。ですから、その辺、どういうふうに考えているのかなということを、今年やるのかどうかというのはちょっとわからないので、そこら辺を教えてください。","respondent":"永尾高齢事業課長、小林保育課長","answer":"その状況ですが、亡くなられた方が７名、あとは長期の入院になった方が４名、施設に入所された方が２名、親族と同居された方が１名ということで、基本的に高齢者住宅は自立してお住まいになれるという方が入居するところですので。来年度におきましては、場所を変えまして、できれば大井地区でやっていきたいと考えていますが、その実施方法につきましては、ご指摘いただいたように、全体の流れ、あるいは地区ごとにやるのがいいのか。","voiceIndex":401,"id":"exchange-170"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"高齢者住宅は、お一人で住んでいるだけに、大変な状況はあると思うんですね。それから、子どもとの触れ合いの場もつくれるようなものを、これからの設計の中で考えて、組み込んでもらいたいなということを、これは要望しておきます。当日、ある区立幼稚園の園長先生とお会いしたときに、先生が驚いたぐらいのお話を伺いました。できれば両方から考え方を教えていただけませんでしょうか。","respondent":"冨岡高齢福祉課長、小林保育課長","answer":"このようなことで、いろいろ可能性、その中には地域の方もお入りいただくケースもあるでしょうし、そういう形で、さまざまな場面が今後もできると思いますし、高齢者施設につきましては、指定管理者に管理を任せておりますけれども。今後、入居される方の状況がわかった段階で、高齢者施設の施設長と幼稚園長がよく協議をした上で、現実、効果的な交流を企画していくように予定しております。","voiceIndex":404,"id":"exchange-171"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ですから、その辺も、せっかく同じ場ですので、若い方にもそういうことを理解してもらって、うまく交流を図っていただけるようにぜひお願いをしたいと思います。これは要望だけにします。もう１点お聞きしたかったのは、高齢福祉の中から、療養病床群、療養型の病床の関係、今、品川区の中で、病床に入院されている方というのは、どのぐらいいらっしゃるのか、つかめているんでしょうか。","respondent":"冨岡高齢福祉課長","answer":"療養病床群には介護型と医療型とあります。介護型の部分の把握しか、１２月末で、してございませんが、２２９名の方が入床されているという状況です。","voiceIndex":407,"id":"exchange-172"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。区の中で、これをどう考えていくのか。その辺で考え方を、まだ決まってないといえばしようがないかもしれませんけれども、早急に詰めていくべきだと私は思うんですが、ある面の考え方、長期基本計画の中には老人保健施設の設置ということも出ていましたけれども、なかなか現実問題、場所の問題ですとか、いろんな絡みがありますので、すぐに要望もしにくい部分もあります。","respondent":"冨岡高齢福祉課長","answer":"いずれにいたしましても、利用者の方が本当にサービスに困らないような対応は保険者としも当然わきまえていることですので、十分医療機関の動向も見据えながら、今後とも対応してまいりたいと考えているところです。","voiceIndex":409,"id":"exchange-173"},{"speaker":"鈴木（真）委員","kind":"質問","question":"平成２４年ですから、もう少しありますけれども、これから先の考え方として、全体、大きな問題になってくると思うので、ある程度、早目早目に、医療型で、相手があるので、区としてどこまでできるかは別にしても、我々にも考え方を教えてほしいなと思いますが、ぜひよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":411,"id":"exchange-174"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=916#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":125999,"voices":412}},{"id":"h21-20090313-3","meetingId":"h21-c-budget","date":"2009年3月13日","dateIso":"2009-03-13","committee":"予算特別委員会","time":"午前１０時０２分～午後６時０８分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を152件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２１年度品川区一般会計予算","agenda":"平成２１年度品川区一般会計予算","exchanges":[{"speaker":"山内委員","kind":"質問","question":"最初に環境対策費２６９ページの温暖化対策事業、それから２７２ページのリサイクル推進費、２７５ページの資源持ち去り防止対策費、それから２６３ページ保健指導費、かかりつけ医療定着推進事業についてお伺いをいたします。温暖化対策事業について伺いたいんですが、２点。","respondent":"工藤環境課長","answer":"いわゆる温暖化対策を進めるに当たっての基礎的自治体としての役割という質問です。やはり今、温暖化問題というのは環境問題の中の最も深刻な問題だというふうに私どもは認識しております。","voiceIndex":4,"id":"exchange-001"},{"speaker":"山内委員","kind":"質問","question":"２点目のほうなんですが、あまり具体的な、まだそういうのはないのかなというところが説明がないですが、いかがなんでしょうか。","respondent":"工藤環境課長","answer":"今一番導入ポテンシャルが高いというか身近な取り組みとしましては、やはりいろいろと太陽光、風力、バイオマス等があるんですけれども、最も身近な取り組みとしては、太陽光エネルギーをどう使うかという部分が課題となっておりまして、私どももそういう認識の中で。","voiceIndex":6,"id":"exchange-002"},{"speaker":"山内委員","kind":"質問・要望","question":"太陽光の普及にまずはしっかりと努めていっていただきたいと思います。続きまして、資源持ち去り対策費なんですけれども、実は今日、資源ごみの日で、私は集合住宅に住んでいるんですが、見たことのないおじさんが自転車でふらふらしていまして、後ろにリヤカーというか、キャリアを積んでふらふらしているものですから、あれっと思いまして、じっと見ていたんですね。注意しました。","respondent":"島袋品川区清掃事務所長","answer":"ご存じのように７月からパトロールを車２台でやっております。それから７月、１１月については、計４台、強化月間としてやっております。","voiceIndex":8,"id":"exchange-003"},{"speaker":"山内委員","kind":"質問・要望","question":"続きまして、保健指導費の２６３ページ、かかりつけ医のことでちょっとお伺いしたいんですが、地域の医療機関と行政がしっかりと地域の医療を守っていくということで、私も一般質問で質問させていただきましたけれども、いろいろな施策をとっておられるんですけれども、その中で、こういう時期だからこそ私は大事なのかなと思うんです。","respondent":"山岡健康課長","answer":"このかかりつけ医の推進事業ですけれども、今委員がおっしゃったように在宅医療をお求めになる方、当然その方も含めて医師会のほうで紹介をしております。ここの診療所がそれに対応できますよというような紹介を含めてやっているところです。","voiceIndex":10,"id":"exchange-004"},{"speaker":"山内委員","kind":"質問","question":"今やはり高齢者おひとりで住まわれている方に対して、このサービスというのは例えば見守りというんですか、お医者さんが来て、こうやって普通に例えば１週間に１度とか行ってくださっていると、それが見守りにもなるのではないかなと考えるんですけれども、そういう観点から大事なのかなと思ってくるんですけれども、最後に答弁をお願いします。","respondent":"山岡健康課長","answer":"ですから、まだかかりつけ医をお持ちになっていない方は、ぜひ紹介窓口で紹介していただいて、在宅医療を含めた診療ができるような状況にしていただければというふうに思います。","voiceIndex":12,"id":"exchange-005"},{"speaker":"山元委員","kind":"質問・要望","question":"私は２５７ページの各種がん検診について、それから２８７ページのプレミアム付区内共通商品券発行経費助成という、この二つのことでお伺いをさせていただきたいと思います。今回、平成２０年度ですが、今現在でどのぐらいの方が受診なさっているか、おわかりになれば教えていただきたいんですけれども。","respondent":"山岡健康課長","answer":"乳がん検診、マンモグラフィー検診です。今年度は２月末現在で４,６４７名の方が受診されています。それから子宮がん検診です。ここまでで８,０００人の方が受診されております。","voiceIndex":15,"id":"exchange-006"},{"speaker":"山元委員","kind":"質問","question":"昨年私が質問させていただいた中で、受診率を回答いただいた中なんですけれども、希望するすべての人の受診ができるよう検診体制をする必要があるとおっしゃっていただいて、その中で、受付の電話の一本化をできるように努力したいというお話がありましたが、今現在、受付というんですか、例えばマンモグラフィーなんですけれども、受付はどのような形でなさっているか、教えていただけますか。","respondent":"山岡健康課長","answer":"一定期間を設けてその間に申し込んでいただく。その中で定員をオーバーした場合には抽せんする、こういうことを新年度からは考えておるところです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"山元委員","kind":"質問","question":"それにしましても、やはりなかなか受診するチャンスがないということで、前にも質問させていただいたんですが、医療機関の拡大といいますか、今の品川・荏原の医師会、また検診車等ではなかなか広がらないのではないかなと思いますが、そういう意味では広がる手だてといいますか、何かお考えはありますでしょうか。","respondent":"山岡健康課長","answer":"今、新年度から新たにマンモグラフィー検診をお願いできるところ、医療機関を当たっているところですが、そのうち二つの医療機関につきましては既に話が成立しておりまして、二つ合わせて年間にしますと１,５００人ぐらい対応できる予定です。","voiceIndex":19,"id":"exchange-008"},{"speaker":"山元委員","kind":"質問","question":"どんどん夢が広がってうれしいです。それで一番聞きたかったのは、実はお仕事をしていたり、またはおうちの事情で平日なかなか行くに行けない方、土曜日だったら行ける、日曜日だったら行けるという方も中にはいらっしゃるかなと思いますが、土日にさせていただけるようなところというのはお考えでしょうか。","respondent":"山岡健康課長","answer":"それから検診車も、土曜の配車が新年度は可能になりそうですので、検診車についても土曜検診ができる状況をつくりたいと思っています。今交渉しておりますが、ほぼ土曜日検診は何回かできそうですので、ご利用いただければというふうに思っております。","voiceIndex":21,"id":"exchange-009"},{"speaker":"山元委員","kind":"質問","question":"ここで乳がんのチェックといいますか、資料を見せながら質問をしたいと思いますが、委員長の許可をお願いしたいと思いますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-010"},{"speaker":"山元委員","kind":"質問・要望","question":"資料を使って話します。実はある区では、お風呂とかシャワーとかにこれをかけて意識を高めるということで、無料で郵送しているところがあるそうなんです。そういう意味ではぜひとも検診を受ける前に、また案内を送るときに、できればぜひ皆さんに配ってこれを使っていただきたいと思いますが、いかがでしょうか。","respondent":"山岡健康課長","answer":"特に今委員がお示しになったようなグッズはまだ用意しておりません。これから何らか工夫ができればというふうに考えておりますけれども、現在のところはそういうふうに、チラシ、パンフレット等の啓発にとどまっているものです。","voiceIndex":25,"id":"exchange-011"},{"speaker":"山元委員","kind":"質問・要望","question":"時間がなくなってしまいましたので、２８７ページのプレミアム付区内共通商品券発行経費助成についてお伺いさせていただきたいと思います。定額給付金が決まりまして、今いろいろ作業をしていただいていると思いますけれども、この２,５４３万５,０００円の助成というのは、内訳はどういうことなのか教えていただけますでしょうか。","respondent":"金子産業振興課長","answer":"プレミアム付区内共通商品券の助成の内容ですけれども、まず１０％のプレミアムがつきますので、その分が、２億円発行いたしますので２,０００万円分になります。","voiceIndex":27,"id":"exchange-012"},{"speaker":"山元委員","kind":"質問","question":"このプレミアム付商品券はどちらで売るようになるんでしょうか。","respondent":"金子産業振興課長","answer":"この共通商品券ですけれども、区内満遍なくということで、区内の郵便局４３箇所、また中小企業センターにあります商店街連合会の事務局で販売する予定としております。","voiceIndex":29,"id":"exchange-013"},{"speaker":"菊地委員","kind":"質問・要望","question":"いろいろな経済誌を見ましても、３月危機だとか２００万人失業時代だとか大変な景況感の中にありますけれども、こうした中で品川区の経済はどうなっていくのかというところをまずお聞きします。今の状況の中で、昨年暮れから大変な状況にありますけれども、１０月ごろからの廃業件数あるいは倒産件数、この辺を教えていただきたいと思います。","respondent":"金子産業振興課長","answer":"特にここのところの経済情勢の急速な悪化に対応しましては、先ごろ議会で議決いただきましたとおり、緊急経済対策、この中で何とか区内の中小企業を支えていこうという考えでさまざま事業を実施しています。","voiceIndex":32,"id":"exchange-014"},{"speaker":"菊地委員","kind":"質問","question":"２３区との比較でいえばこの構成比というのはかなり長期にわたって２０位前後という産業経済費だったんです。実際に２３区で工業関係、商業関係の多い、その経済によって支えられている区というのもありますから、一概に幾らであればいいということは言えませんけれども、少なくとも構成比についてもう一度見直していくべき時期ではないかというふうに思いますけれども、この辺はどうでしょうか。","respondent":"金子産業振興課長","answer":"２３区と比較して産業経済費の構成比というお尋ねですけれども、先ほど企画財政課長からご説明申し上げたとおり、この経済状況に鑑みて産業経済費全体で言いますと平成２０年度に比べて平成２１年度は約８１％の増ということで。","voiceIndex":34,"id":"exchange-015"},{"speaker":"菊地委員","kind":"質問","question":"２.２％、確かに引き上げられましたけれども、緊急経済対策の中で、融資を中心とした引き上げということで、全体の、一つひとつの事業に対するところではないというふうに思います。ですから、この辺の構成比についてはしっかりともう一度見直すべきではないかというふうに思います。","respondent":"金子産業振興課長","answer":"こういった工場協会等々、あるいは東商についても、当然こういう団体に加入して、企業全体が一致して品川区の産業振興に協力していただく、こういったことは必要だと思いますので、私どもも産業団体とともに。","voiceIndex":36,"id":"exchange-016"},{"speaker":"菊地委員","kind":"質問・要望","question":"中小企業に努力を求めるのであれば、区がそれを上回る、そういう努力をして区内の産業や経済を守っていく、こういう立場に立つべきだと思います。ですから、今の課長のお話は、これからそうした要請をしていくものと受けとめます。それからもう一つですけれども、大型店との連携事業でお聞きします。東京都競馬株式会社が建設をする商業施設というのは、来場目標が年間３００万人だそうです。","respondent":"金子産業振興課長","answer":"これにつきましては、まだ計画等も提示されたばかりですので、私どもとしてもいろいろ研究はしていきたいなというふうに考えてあります。","voiceIndex":38,"id":"exchange-017"},{"speaker":"菊地委員","kind":"質問","question":"今出ました東品川四丁目のジャスコですけれども、東品川四丁目の小売店の売り上げというのが、２００８年で１５１億円だそうです。これはもうジャスコができたことによる売り上げだというふうに思います。この新しいセンターが、大株主が東京都と２３区ですから、この経営が失敗すればそのところがしっかりと区民の肩にかかってくることになると思いますけれども、その辺の認識をちょっとお聞かせをください。","respondent":"金子産業振興課長","answer":"今のご指摘ですけれども、私どものほうにまだ計画の具体的な部分というのは詳細が出ておりませんので……。","voiceIndex":40,"id":"exchange-018"},{"speaker":"石田（慎）委員","kind":"質問","question":"私は２５５ページの新型インフルエンザ対策経費についてお伺いします。","respondent":"吉田品川区保健所保健サービス課長","answer":"新型インフルエンザについてのご質問ですが、新型インフルエンザ対策の経費につきましては、講演会の経費が約１５０万円、ほかはほとんどが物品、感染防護服であるとか、あるいはマスク等の物品の整備となっております。","voiceIndex":43,"id":"exchange-019"},{"speaker":"石田（慎）委員","kind":"質問","question":"主に備蓄についてお伺いをしたいのですが、まず初めに先日の他会派の代表質問でも、リレンザの備蓄をしてはどうだというようなご意見もありました。特に防災関係では備蓄がしっかりされているので、例えばその辺の活用をしたりというのも僕は一つの案だと思うのですが、区のお考えをお聞かせください。","respondent":"吉田品川区保健所保健サービス課長","answer":"続いて使用につきましてですが、治療薬としての備蓄を都はしているわけで、予防薬、つまり感染した方と接触があった方への対応としての備蓄はないので、３,０００人分につきましては、そのような活用も同時に検討していくという形になろうかと思います。","voiceIndex":45,"id":"exchange-020"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。次に、都との連携についてお伺いしたいのですが、例えば備蓄を東京都、国がしている中、どのような形で品川区にその備蓄品がおりてくるのかという流通の流れをお聞かせいただきたい。","respondent":"吉田品川区保健所保健サービス課長","answer":"近隣区との連携につきましては、都がやはり医療の核となることは難しいということで、近隣区を含めまして、担当者は会議を既に２回ほど設けております。その場で医療の確保あるいは通信であるとか、そういう連絡体制についても検討をしていくということになっております。","voiceIndex":47,"id":"exchange-021"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"品川区独自で、もちろんさまざまな対策をとっていただいているんですが、やはり近隣区との連携がどうしても必要だと思うので、ぜひさまざまな形で近隣区との連携を進めていただきたいと思います。もう一つ、連携なんですが、例えば区内業者との事業所等の連携がどのようになされているのか。","respondent":"吉田品川区保健所保健サービス課長","answer":"区内業者につきましてですが、まず区内の各事業所自体が事業継続計画をおつくりいただくということで、その支援のために感染症対策のマニュアルを昨年９月に策定しています。","voiceIndex":49,"id":"exchange-022"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"平成２１年度の予算、さまざまな区で目玉の一つとして新型インフルエンザが取り上げられていました。やはり区民の皆さん、区内業者の皆さんの意識が一番のワクチンになるのではないかなと。やはり実際に起こったときにできるだけ自宅などに待機をしていただくというのが一番の効果だというのはさまざまなところで言われていますので、ぜひ今後も啓発ならびにさまざまな整備を行っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-023"},{"speaker":"井桁委員","kind":"質問・要望","question":"私は、２５７ページの３目環境衛生費の狂犬病予防および動物の愛護について、次が２６１ページ、４目保健指導費、食からの子育て支援事業、食育推進事業について、主にこの項目は食育についてお伺いをしたいと考えています。狂犬病予防および動物の愛護について。そのときに、新しいデザインへの切り換えというのはどのようなお考えをお持ちでしょうか。","respondent":"荒井品川区保健所衛生課長","answer":"これを４月１日から交付します。それから、いままでのものをお使いの方につきまして、新しいものをという場合につきましては、今ちょっと具体的には検討している最中ですが、再交付という形で手続きをとらせていただければというふうに考えているところです。","voiceIndex":53,"id":"exchange-024"},{"speaker":"井桁委員","kind":"質問・要望","question":"せっかく新しいデザインにするのですから、いままで登録している方にも今後つけていただきたいという意味でも、広くこのあたりの告知をしていただけたらなと考えています。再交付もこういった形でできますよとかそういったことを、ぜひ獣医師会とかそういった関係団体のほうにもぜひとも働きかけていただきたいと思うんですが、その辺のお考えをお願いいたします。","respondent":"荒井品川区保健所衛生課長","answer":"委員ご指摘のとおり、ＰＲにつきましては獣医師会あるいは動物病院等を通じて徹底させていただきたいと考えています。","voiceIndex":55,"id":"exchange-025"},{"speaker":"井桁委員","kind":"質問・要望","question":"この１０カ年の計画の中で、都のほうから防災時のマニュアルの取り組み、そういったような、動物というのは地域差があるのも事実です。特に都会での災害時のために、動物のための備蓄であったり、そういったことを市町村がルールをつくるようにというようなことが書かれておるんですが、その辺への現状といいますか、そういったものがわかれば教えていただきたいと考えています。","respondent":"平澤品川区保健センター衛生課長","answer":"災害時における動物に関するご質問です。品川区におきましては「災害時における動物救護活動に関する協定」というものを平成１８年４月１日に取り交わしました。","voiceIndex":57,"id":"exchange-026"},{"speaker":"井桁委員","kind":"質問・要望","question":"この平成１８年度に出ているのはわかるのですが、実際に飼い主の方にそこまで伝わっていないのかなと。次に、その計画案の中で出されております動物愛護推進員というのがあると思うんですけれども、この制度は都の制度になりますが、品川区では現在平成２０年度で５名います。","respondent":"平澤品川区保健センター衛生課長","answer":"推進員の方につきましては、例えばですが、各種の講習会のときに出ていただきまして、私どもと一緒に動物の飼い方、ルール、そういうことについて、区民の皆さんにお話しするときのお手伝い、または講師といった面でお願いしています。","voiceIndex":59,"id":"exchange-027"},{"speaker":"井桁委員","kind":"質問・要望","question":"この質問は以上です。品川区は以前から食に関することであったり、健康にかなり力を入れていると思っておるのですが、その中で、この５カ年計画の中で、ちょうど折り返しといいますか、そういった中になってきて、皆さんの中での認知度も高くなってきているとは思うんですけれども、区の取り組み、実感・成果というのがありましたら、お伺いしたいと考えています。","respondent":"矢野品川区保健センター保健サービス課長","answer":"今後の生涯を通じた食育の連携につきましては、平成１７年から庁内で検討を始めまして、今関係各課と連携会議を毎年持っております。今後、それを膨らませて、生涯を通じた食を通じた健康づくりを進めていこうと考えております。","voiceIndex":61,"id":"exchange-028"},{"speaker":"井桁委員","kind":"質問・要望","question":"平成１７年度は当初だと思うんですが２０回で、平成１８年度が２２回、平成１９年度が７回とかなり依頼によることが減っているというのは、内容等々とかにもアレンジの方法であったり、そういったものを加えてやっていらっしゃるのかなと思いましてお伺いしたいと思います。","respondent":"矢野品川区保健センター保健サービス課長","answer":"食からの子育ての、この部分ですが、依頼によるという部分は地域の団体等の依頼により行っておりますので、周知はしておりますが、その年によって変わってきます。児童センター等との連携は毎年定期的に行っているという状況です。","voiceIndex":63,"id":"exchange-029"},{"speaker":"井桁委員","kind":"質問・要望","question":"この質問は以上です。次に移りまして、２７５ページのリサイクル推進費の資源化センター管理運営費についてお伺いいたします。お願いいたします。","respondent":"島袋品川区清掃事務所長","answer":"粗大ごみの持ち込みにつきましては、もう２年目になるんですけれども、かなり浸透しています。それで、一応、受付は委託しているものですから、委託先のほうに職員が指導してやっているということで、マニュアルというか、簡単な手引書はあります。それによって対応するです。","voiceIndex":65,"id":"exchange-030"},{"speaker":"井桁委員","kind":"質問","question":"その手引書というんでしょうか、手引書について、今後増ということで、さらにさらに資源化センターを見てもらうことのきっかけの一つにもなっていると思いますので、その辺の職員の方の対応であったり、普段職員の方も一生懸命働いていらっしゃると思いますので、効率のいいマニュアルというのを今後また考えていく必要があるかと思うんですけれども、今後の対応についてはいかがでしょうか。","respondent":"島袋品川区清掃事務所長","answer":"ところが時々飛び込みというのがありまして、その対応があるんですけれども、その辺につきましても、今委員の指摘のあったところによりますと、例外的なケースの場合にどうするか、その辺のことについても我々清掃事務所の職員が指導してまいりたいと考えています。","voiceIndex":67,"id":"exchange-031"},{"speaker":"井桁委員","kind":"質問・要望","question":"区民委員会のほうでも視察に行った際に、太陽光パネルの展示があったんですけれども、なかなかそれが実際に持ち込む場所とは違うところについていて、これが一体だれの目に見られているのかなという疑問もあったんですけれども、その辺の今後、資源化センターの見せ方も考えていっていただきたいなと思っておるんですが、いかがでしょうか。","respondent":"秋山資源循環推進課長","answer":"今後パネルの設置をしているですとか、そういうような表示等ＰＲができるようにしていきたいし、見学ができるように、見学の受付ができるような体制になってありますので、その辺ちょっとお声をかけていただければというふうに思っております。","voiceIndex":69,"id":"exchange-032"},{"speaker":"井桁委員","kind":"質問","question":"次の質問です。２８５ページの産業経済費の３目中小企業対策費の中小企業ワークライフバランス支援事業、このことについてお伺いいたします。３月２日の区民委員会でも議案に上がりましたが、この中で、実際の申込件数の想定ですか、それと、もしこれについての問い合わせというのがありましたら教えてください。","respondent":"金子産業振興課長","answer":"ワークライフバランスの融資あっ旋のほう、新しい資金のことだと思いますが、これにつきましては、私どもご案内のとおり平成１８年からワークライフバランスの支援事業を実施しておりまして、既にコンサルタントでも４社ほど入っております。","voiceIndex":71,"id":"exchange-033"},{"speaker":"井桁委員","kind":"質問","question":"この申し込みの要件の中に、策定のワークライフバランスの推進に取り組んでいる、また取り組む計画がある中小企業とあるのですが、そういった計画を立てる際に、指針といいましょうか、指導といいましょうか、そういったものもやられているんでしょうか。","respondent":"金子産業振興課長","answer":"次世代育成支援の行動計画の策定とその中身が具体的にワークライフバランスに資するものというふうにしておりますけれども、そういったことに関しましては、今私ども具体的に幾つかの各企業に入って、コンサルタントということで。","voiceIndex":73,"id":"exchange-034"},{"speaker":"浅野委員","kind":"質問","question":"私は、２５７ページ、予防費の健康診査費、各種がん検診、こころの健康づくり事業、それと２６９ページ、環境対策費の低公害車導入促進助成事業、時間があればエコドライブ普及事業までやりたいと思います。その中で、この案内についてでありますけれども、平成２１年度の案内は、平成２０年度と比べてどのような工夫がされるのかなということについて、まずお伺いしたいと思います。","respondent":"山岡健康課長","answer":"がん検診の通知というか、案内です。平成２１年度につきましては、国保に入っていらっしゃる方は国保の特定健診、それから７５歳以上の高齢者の方につきましては、その高齢者の健診、その通知に同封する形でご案内を出す予定です。","voiceIndex":76,"id":"exchange-035"},{"speaker":"浅野委員","kind":"質問","question":"ということは平成２０年度と同じパターンで臨むというようなことだと思うんですけれども、一つ、やはり国保に加入されていない方、こちらの案内というのは非常にある意味では抜けてしまう部分だということで指摘もさせていただきました。平成２０年度ですけれども、実際にこの国保に加入されていない方に送られた数についてお伺いいたします。","respondent":"山岡健康課長","answer":"合計で２,８１１人の方にお送りしております。","voiceIndex":78,"id":"exchange-036"},{"speaker":"浅野委員","kind":"質問・要望","question":"そのように、これは要望しておきます。それと、先ほども女性のがんについて会派としても取り上げしていますけれども、なかなか男性のがんというものは、ある意味では脚光を浴びないなと思うわけですけれども、男性のがんとして話題になっていないということも含めまして、この件についてお伺いします。","respondent":"山岡健康課長","answer":"１月末現在で５１１名の方が受診しているんですが、当初大体５００人程度というふうに考えておりました。それで、１月現在で既にそれを人数的にオーバーしているということもありまして、この辺をちょっと考えていきたいというふうに思っております。","voiceIndex":80,"id":"exchange-037"},{"speaker":"浅野委員","kind":"質問・要望","question":"次にまいります。こころの健康づくり事業ですけれども、今年度、平成２０年度までは精神保健という形で名前があって、それにそっくりそのまま１行、こころの健康づくり事業ということで取りかわっています。これによりまして、また予算も増加しておりますけれども、この組み替えというのはどういう考えに基づいて変更されたのか、平成２１年度の予算についてお伺いします。","respondent":"吉田品川区保健所保健サービス課長","answer":"こころの健康づくりについてのご質問ですけれども、品川区では、自殺、特にうつ病を原因とするような自殺が結構増えているといった現状です。その内訳を見ますと、２０代それから４０代をピークとするような働き盛りの方にかなり多いということがわかっております。","voiceIndex":82,"id":"exchange-038"},{"speaker":"浅野委員","kind":"質問","question":"これはちょっと気になったところなんですけれども、精神保健福祉法に基づきまして、都に３カ所の総合保健福祉センターがあるかと思います。品川区は世田谷にある中部総合精神保健福祉センターとなっておりますけれども、品川区とこちらのかかわりというものは、連携して何かをするような体制なのか、それとも全く関係なくて独立したものなのか、お伺いいたします。","respondent":"吉田品川区保健所保健サービス課長","answer":"品川区では中部精神保健福祉センターと連携をしておりまして、例えばケースカンファレンスであるとか、あるいは各種相談等、専門的な事項に関する相談等は随時させていただいているような状況です。","voiceIndex":84,"id":"exchange-039"},{"speaker":"浅野委員","kind":"提案","question":"このような大きいところともうまく連携をとりながら進めていっていただきたいんですけれども、この自殺に関しましては、さまざまな対策等が都でも検討されているということですけれども、昨年の第３回定例会で会派からも質問させていただきました沖縄県の総合精神福祉健康センター、これを視察してきましたということと、その中で認知行動療法、ＣＢＴという方法ですけれども。","respondent":"吉田品川区保健所保健サービス課長","answer":"実際にうつ病の対策といたしましてＣＢＰが有効だということは十分承知しておりますが、現時点では中部精神保健福祉センターのほうでうつ病対策というのは充実させていただいているといった状況ですので、区の中ではまだ検討を進めていないということです。","voiceIndex":86,"id":"exchange-040"},{"speaker":"浅野委員","kind":"質問・要望","question":"続きまして、低公害車購入等助成についてということで、これも第４回定例会で会派のほうから質問させていただいたことですけれども、本区としてもこの助成制度の継続を要望しまして、国や都との制度との連携を図りながら、引き続き可能な支援策を検討していただけるという回答をいただいておりましたので、この件について質問します。","respondent":"工藤環境課長","answer":"そういった中で新年度の予算の額ですけれども、受付分が装置装着助成が１２台、購入の助成が１４台というふうな予算になっているところです。","voiceIndex":88,"id":"exchange-041"},{"speaker":"浅野委員","kind":"質問","question":"神奈川県などでは、やはり自動車会社があるということで、全販売店につきまして電気自動車向けの充電機を設置、また横浜市では充電機設置に１基当たり２０万円の助成を出すとか、そういうような動きもあります。区のこれからのお考え、エコカーに対する考えについてお伺いいたします。","respondent":"工藤環境課長","answer":"来年度も引き続きそのような施策を実行いたします。加えまして、今後、都や国、いろいろな助成の動きを見まして区の支援も検討していきたいというふうに考えておりますので、よろしくご理解をいただきたいと思っています。","voiceIndex":90,"id":"exchange-042"},{"speaker":"渡部委員","kind":"質問","question":"衛生費の中で環境対策費と清掃事業費になるんでしょうか、ちょっと中長期的なことも踏まえて伺っていきたいと思います。時間があれば産業振興のほうに行きたいんですが、２点先に伺います。特に一つお伺いしようと思いましたのがＬＥＤライト、発光ダイオード等の蛍光灯とかが世の中にだいぶ出るようになりまして、今実際に市販されている蛍光灯におきましても、省エネタイプというやつが主流になっています。","respondent":"工藤環境課長","answer":"そういった意味では、私どものほうも電力量等も従来の蛍光灯に比べてもメリットがあり、ＣＯ２の排出に関しても十分な削減効果が見込まれるということで、私どもも環境にやさしい製品だというふうに十分認識しています。","voiceIndex":93,"id":"exchange-043"},{"speaker":"渡部委員","kind":"質問・要望","question":"考えを伺わせていただきました。ぜひ導入をといいますか、実験をというんですか、最初の段階で進めていっていただきたいなと思って、この件は終わりにします。その推奨品という形が終わった後に、これは民間のあれだからどうなるかと思うんですが、その推奨品というのが消えた状態でのごみ袋を同じような形で売り続けてというか、消費者が手に入れられる状態にあるのかを教えてください。","respondent":"秋山資源循環推進課長","answer":"そこなんですけれども、他都市の例等を見ましても十分現在２３区推奨の制度と同じものが流通しているということを調査しておりますので、区民の皆様はそういう袋をお買い求めいただいて使えることができるというふうに考えてあります。","voiceIndex":95,"id":"exchange-044"},{"speaker":"渡部委員","kind":"質問","question":"品川区としてもそうですが、２３区、ほかの区全般のこと、また清掃一部事務組合とかでも、長期的に見たごみの有料化等についてどのような考えをお持ちなのか、もしお答えできれば教えていただけますでしょうか。","respondent":"秋山資源循環推進課長","answer":"今後中長期的に見て、国のほうは有料化という方針を出しているようですけれども、２３区内で住宅地が隣接しているような状況で有料化をどのように進めていくのかというのは今後の検討課題、研究を進めていくべき問題だというふうには認識しております。","voiceIndex":97,"id":"exchange-045"},{"speaker":"渡部委員","kind":"質問","question":"何か大きな変動がありそうなときには、やはり早めにいろいろ話し合っていって、確かにこの環境問題等、今高まっている時代ですから、地域の方、住民の方々にも理解を得つつ進めていかなければいけないのかなと思いまして、今日質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-046"},{"speaker":"本間委員","kind":"質問・要望","question":"２６９ページの中から３点ほどお願いします。温暖化対策事業の中と、それから里山再生事業、早川町、蝶の道プロジェクト経費等についてお伺いします。この件につきまして、その内容、取り組み方等々について、もう少し詳しく教えていただきたいというふうに思います。","respondent":"工藤環境課長","answer":"今回、新たな削減手法といたしまして、グリーン電力証書システムを活用しまして、イベント時に使用する電力についてグリーン電力を購入するものです。","voiceIndex":101,"id":"exchange-047"},{"speaker":"本間委員","kind":"質問","question":"イベント事業に伴うというようなことですね。もう少し私たち区民として何ができるのか、事業者に対してはどのような啓発を行っていくかという形の中でとらえていたものですから、区民の立場でとらえた場合にはどのような取り組みがあるのかということについてお知らせください。","respondent":"工藤環境課長","answer":"私ども、先ほど言いましたようにイベント時にグリーン電力を購入するですけれども、イベントのときに、このイベントは自然エネルギーを購入したイベントですよという形で、買った価値の部分を証書にして掲げましてイベントを実施したいと考えています。","voiceIndex":103,"id":"exchange-048"},{"speaker":"本間委員","kind":"意見","question":"次に行きたいと思いますけれども、同じページの中の里山再生事業の件につきましては、既に水と緑の市町村交流事業、マウントしながわの活用事業ということで予算計上が５３０万円何がしついております。さらにこの場面で環境対策費として１００万円そこそこの新たな予算がついている。この兼ね合いと、その環境対策費の観点からの部分は何をねらいとしてどのようなことをやるのか、お聞かせください。","respondent":"工藤環境課長","answer":"内容としましては、区民課のマウントしながわ活用事業との共同事業としまして、早川町里山再生活動に習熟したメンバーを基本構成員としまして、また新たに区民の皆さんを募りまして実施するものです。","voiceIndex":105,"id":"exchange-049"},{"speaker":"本間委員","kind":"質問","question":"蝶の道プロジェクト経費というのがあります。これも１５０万円そこそこついておりますけれども、実はこの件につきましては、去年、幼保一体施設の二葉すこやか園での件がテレビで放映されておりました。その部分で、この蝶の道プロジェクト経費は、どなたがどのようなところでどんなようなことを進めていくのかという観点からお聞きしたいと思います。","respondent":"工藤環境課長","answer":"これが３４万円、あとさまざまな蝶の生息エリアを広げるということで、食草園の整備経費等がありますので、そちらのほうが１２５万円、合計１５９万円計上しているものです。","voiceIndex":107,"id":"exchange-050"},{"speaker":"本間委員","kind":"質問・要望","question":"二葉すこやか園内で見たテレビによりますと、食草園の育成をされているというふうな部分で、蝶の名前はわからなかったんですけれども、きれいな蝶が飛び交っておりました。特に勝島運河のほうでも黒いアゲハチョウというんですか、そのような食草園の育成を見たことがあります。","respondent":"工藤環境課長","answer":"蝶を増やすという部分で食草園を増やしていくということが重要かと考えています。","voiceIndex":109,"id":"exchange-051"},{"speaker":"渡辺委員","kind":"質問","question":"私は、２５３ページ、休日診療費、２８１ページ、観光アクションプラン、２８３ページ、中小企業支援費、この３点で伺わせていただきます。大みそか、あるいは元旦、２日と激痛に襲われた中で、そういった意味も持って当事者意識を持ちながらちょっと伺いたいと思いました。そういった中で、数字的な行政全般の中で、いろいろな見方があると思いますが、ちょっと絞って伺います。まとめて伺います。","respondent":"山岡健康課長","answer":"これは今休日診療ということでお答えしました。は夜間あるいは土曜日の小児診療なども対応しています。","voiceIndex":113,"id":"exchange-052"},{"speaker":"渡辺委員","kind":"質問","question":"強いて言えばという課題を伺えればと思いました。よろしくお願いします。","respondent":"山岡健康課長","answer":"例えば夜間診療、これは平成２０年度から昭和医大の病院の中で設けていただいてやっているところです。やはり課題は、本当に休日夜間で診療が必要なのかどうかです。これはよく言われるコンビニ受診ということがもしなければよろしいかと思います。","voiceIndex":115,"id":"exchange-053"},{"speaker":"渡辺委員","kind":"質問","question":"今のご説明は非常にわかりました。次に行きます。中小企業支援ということで伺いたいと思います。もう先般から出ています緊急総合経済対策、反響はとても私たちも肌で感じております。私どもの会派のほうにも問い合わせも多数いただいたり、当然そこで答えられない部分もあるんですが、実際にこの融資に限定して伺いますと、想定に対してここまでの最新の相談等、申し込み状況を伺えればと思います。","respondent":"金子産業振興課長","answer":"それから資金のあっ旋状の交付ですが、１１月４日から１２月２６日まで年末対策特別融資をやっておりまして、これを１月いっぱいまで延ばしましたが、これが５９１件、それから１月２０日から新たに始めました経営支援資金、これが４９８件。","voiceIndex":117,"id":"exchange-054"},{"speaker":"渡辺委員","kind":"提案","question":"それとは別に、あえてちょっと視点を変えた形で提案的な質問をさせていただきたいと思います。この点が一つ。この事例の中から伺いたいことは、中小企業支援という中で、中小企業が一つにくくりをされるんですが、中規模と小規模、あるいは商業、工業でもだいぶ違ってくると思えます。求められるサービスも違ってくると思うんですが、この辺の考え方を大まかで構いませんのでまず１点目に伺いたいと思います。","respondent":"金子産業振興課長","answer":"そういう意味では、返済できない方が不誠実だということではないんですけれども、私どもとしましては、どうしても返済できない方にも何らかの方策を考えていかなければならない。対応していかなければならないというのが、今持っている大きな課題かなというふうに考えてあります。","voiceIndex":119,"id":"exchange-055"},{"speaker":"安藤委員","kind":"質問・要望","question":"２６９ページ、地球温暖化対策地域推進計画策定費について伺いたいと思います。計画の内容についてお伺いしたいんですが、地域推進計画の策定に当たりまして、２０名以内の地域推進協議会を設置して、うち３名を区民公募するということで、現在広報でも、ちょっともう少しスペースを割いていただきたいなと思ったんですが、３月末までそうした委員を募集しているということです。","respondent":"工藤環境課長","answer":"構成比といいますのが、一応２０名予定しておりまして、その中で今、私どもが考えておりますのが、例えば区内団体の代表の方、あと事業所、例えば大規模製造事業者ですとか大店舗の事業者、あとは鉄道運行事業者、その他の事業者を予定しています。","voiceIndex":123,"id":"exchange-056"},{"speaker":"安藤委員","kind":"質問・要望","question":"２０名という中で、区民の公募が３名ということで、それがちょっと少ないのではないかということの指摘でした。自治体、２３区では、１９９０年度比で、基準年ですから、軒並み削減目標数値を掲げているわけですが、これから協議会をつくって検討ということについて、区の考え方として、削減目標の基準年は１９９０年度ということですべきだと私は思うんですが、いかがでしょうか。","respondent":"工藤環境課長","answer":"さまざまな手法を用いて削減に向けてアプローチしていきたいというふうに考えているところです。今後、区の地域事情を十分に考えまして、今後検討していきたいというふうに思ってあります。","voiceIndex":125,"id":"exchange-057"},{"speaker":"安藤委員","kind":"質問・要望","question":"地域事情ということでありましたので、部門別でぜひ現状を把握していただいてということで、ぜひとも目標のほうは立てていただきたいと思いますし、あと基準年比は多分協議会の中でも当然１９９０年度にすべきという意見が出てくると思いますが、全世界が１９９０年度比に照らして、しかも京都議定書をつくった国ですから、そこに照らして削減努力しているわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-058"},{"speaker":"安藤委員","kind":"質問・要望","question":"広げていくべきだと思いますけれども、現行の共生住宅の水準、これはやはり削減していくということを区として計画を立てるわけですから、その上で、この自然エネルギーを抜本普及していくということは直接大きくかかわることだと思います。実績がどうかということと、あと、これを抜本的に引き上げるべきではないかというところに関して、環境課の考えはいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-059"},{"speaker":"安藤委員","kind":"質問","question":"地域推進計画を策定するに当たって、所管課の環境課といたしまして、区内の住宅に自然エネルギーをどれぐらい増やすかという数値目標というのも盛り込むべきだと思うんですけれども、お考えはいかがでしょうか。","respondent":"工藤環境課長","answer":"私どもが地域推進計画を策定するに当たっては、先ほど申し上げましたように地域推進協議会ということを立ち上げて検討するわけですけれども、同時に区役所内、庁内会議の開催ということで、さまざまな環境にかかわる所管課と連携をとりまして、同時並行的に検討していく予定です。","voiceIndex":133,"id":"exchange-060"},{"speaker":"安藤委員","kind":"質問","question":"区内の地域特性としては太陽光をさえぎってしまう再開発の超高層ビルなどもありますが、こうしたところにも設置の義務というのを、区として推進しているわけですから義務づけを行うべきだと思うんですけれども、こちらの考えはいかがでしょうか。","respondent":"工藤環境課長","answer":"その考えには変わりはございません。超高層ビル等の件に関しましてはいろいろと今法制上の規制がかかっていましたり、都条例、環境確保条例のほうでもさまざまな今規制がかかるところですので、その中でなされるものだというふうに考えております。","voiceIndex":135,"id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"区民への啓発にもなると思いますので、現在どれぐらいの区内施設への設置が、現状何パーセントぐらいなのかということと、また、その数値目標をきちっと今度策定する計画の中、あるいは区みずからが事業者として策定している第２次の計画もありますけれども、実行計画の中でも明確に目標として掲げるべきだと思うんですけれども、いかがでしょうか。","respondent":"工藤環境課長","answer":"今後の目標につきましては、当然地域計画策定の際に協議会の中で話し合われることで、その中で決定をしていきたいというふうに考えております。","voiceIndex":137,"id":"exchange-062"},{"speaker":"安藤委員","kind":"質問","question":"それと、区みずからの姿勢の問題にもかかわってくるんですが、サーマルリサイクルを昨年１０月から実施しておりますが、先日の区民委員会の中でも実施後の経過が報告されました。ですから、このサーマルリサイクルでどれだけＣＯ２が排出されるのかということは、今後きちっと部門別に見ていくということもありました、廃棄物部門というのもありますし、区としてきちんと測定していくべきだと思います。","respondent":"秋山資源循環推進課長","answer":"サーマルリサイクルによるＣＯ２の効果ですけれども、委員がおっしゃられたような清掃一部事務組合からのデータによるプラスチックの温室効果ガスの増加というようなことや、メタンガスの削減というようなことで、影響ということは出ております。","voiceIndex":139,"id":"exchange-063"},{"speaker":"安藤委員","kind":"質問・要望","question":"清掃一部事務組合のデータでもって微増ということをおっしゃるわけです。今も繰り返されたわけですけれども、今度は地域推進計画ということで、区が部門別にしっかりと区内の排出の現状を把握した上で対策を立てるという方向性ですから、きちんとこのサーマルリサイクル実施後、燃やすごみが１３.１％増加したと。","respondent":"秋山資源循環推進課長","answer":"清掃一部事務組合は２３区共同設置の組織ですので、当然調査のほうは責任をもってやっているというふうに考えております。","voiceIndex":141,"id":"exchange-064"},{"speaker":"安藤委員","kind":"質問・要望","question":"ここはこういった計画を策定するという時期でもありますので、区自身できちんと区内のプラスチックごみを燃焼したことによるＣＯ２増加量をはかっていただきたい。強く申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-065"},{"speaker":"藤原委員","kind":"質問","question":"それと中小企業の融資なんですけれども、産業経済費が８１％増ということで、やはりここの比率は高いと思うんですけれども、中小企業の方々はすごく喜んでいると思いますが、ここにこういうふうに手厚く融資のお手伝いをするということが、一般の区民の方にとってどういうメリットがあるのか教えてください。それと、プレミアム付商品券ですが、定額給付金とあわせてというお話です。","respondent":"山岡健康課長、金子産業振興課長","answer":"それを区として、よくやっている、もっと続けてくださいと認証することによって、区民の皆さんがそれぞれ今後も引き続いて健康づくりに取り組んでいただける、そういうことを期待して、この事業を実施するものです。私どもの実施しております融資あっ旋制度を拡充しているわけですが、それの一般の区民のメリットについてというお尋ねです。融資あっ旋制度はご案内のとおりですが、直接的には区内の中小企業者の方を支えるためのものです。","voiceIndex":145,"id":"exchange-066"},{"speaker":"藤原委員","kind":"質問","question":"官と民でという意味で、そこまで役所がやる必要はないと思うんですが、その辺についていかがですか。そのときの区の負担というのはどういうふうになっているのでしょうか。プレミアム付商品券ですが、４月２０日ということですけれども、私も一般質問をさせていただいて、この施策を考えていく上で、年度中にもう一回やってほしいというお願いをさせていただきました。","respondent":"山岡健康課長、金子産業振興課長","answer":"それで地域こぞって健康づくりに取り組んでいただくといったようなことを考えているところです。それから、飲食店につきましても、なかなか飲食店の場合は小さい店舗ですと、禁煙というのは難しいということがあります。制度上そうなっております。それから、プレミアム付商品券ですけれども、これにつきましては、やはり今後の経済情勢を鑑みながら、また検討してまいりたいと考えています。","voiceIndex":148,"id":"exchange-067"},{"speaker":"藤原委員","kind":"意見","question":"結局そこから出ている。ここはどうしても制度だからしょうがないと言われてしまうとそれまでですけれども、どう思われるかということ。すごく、２億のというのは。だからもう次々回に向けてのもっと具体的な、もうちょっと何か検討の中でもどういうふうに、という形で出てきてもいいと思うんですけれども、よろしくお願いします。","respondent":"金子産業振興課長","answer":"商品券のほうからお答え申し上げますが、先ほど申し上げたとおり４月２０日の予定で準備を進めております。","voiceIndex":151,"id":"exchange-068"},{"speaker":"武内委員","kind":"提案","question":"その際、平成１９年の当時の健康課長の答弁では、平成１９年４月から母子健康手帳の修正の中に、このマタニティマークについての意味とか、また国を上げてやっている運動についての趣旨を記載する予定ですとありましたので、これが今どうなっているかという確認と、またそのときに、現在品川区では保健所とか保健センターまた地域センターでポスターを掲示しているけれども、なかなか浸透していないので。","respondent":"山岡健康課長、工藤環境課長、金子産業振興課長","answer":"平成１８年度が７９組、平成１９年度が増えまして２９３組、平成２０年度なんですけれども、実は平成２０年度１月末現在では３８組ですが。国および都の太陽エネルギー等の助成の件です。国の制度が２００５年までやっていたものが打ち切られて、また今年度から再開されました。商店街に所属している限りはこの空き店舗対策は品川区の事業で、大田区の住所のほうの商店にも対象になり得るところですが、やはり区としましては。","voiceIndex":154,"id":"exchange-069"},{"speaker":"武内委員","kind":"質問・要望","question":"トータルの人数を教えてもらいたいということと、あと、去年、決算特別委員会だったと思うんですけれども、うちの公明党の会派の委員が、いわゆる妊娠されたうれしいお知らせの実績はどうなのかという中で、平成２０年度からそれをとるようにしますというお話だったので、まだ１年余りなので、そういう報告がないのかもしれませんが、それについての現況をお知らせいただきたい。","respondent":"山岡健康課長、金子産業振興課長、工藤環境課長","answer":"その中で３８組のうち２３組が妊娠に至ったというふうに報告を受けております。大田区との連携については、さまざまほかの面でもやっておりますけれども、ここはあくまでも品川区山王銀座商店街という形で実施する予定ですので。東京都のほうは１kW１０万円ということで１０kWで１００万円が補助の対象となっています。集合住宅も戸数掛ける１０kWが補助対象になっております。","voiceIndex":158,"id":"exchange-070"},{"speaker":"大沢委員","kind":"質問","question":"２６９ページ、温暖化対策事業についてお伺いいたします。二つこれについて伺います。もう１個については、太陽エネルギー見本市等についての「等」についてちょっとお伺いをいたします。午前中にもこの話は委員からありましたけれども、温暖化対策事業についての、この事業の有用性あるいは意義を午前中に伺いました。それも踏まえまして、改めて伺います。","respondent":"工藤環境課長","answer":"温暖化対策の意義ですけれども、午前中の答弁とも重なりますけれども、やはり世界的に今、温室効果ガスの削減というのが大きな課題となっています。そういった中で、区としてもできる最大限のことをやるということで、今回この推進計画を立てたものです。","voiceIndex":163,"id":"exchange-071"},{"speaker":"大沢委員","kind":"提案","question":"その中で区有施設、実際に区有施設の改修なりいろいろとあると思いますけれども、この中で改修する場合に、例えば高断熱材を用いたり、それと高遮熱のガラスですか、それを積極的に取り入れるような提案を環境課としてやっていく必要性があると思うんですけれども、そこのところは今後どのように連携をとりながら進めていかれるのかご答弁ください。","respondent":"工藤環境課長","answer":"その取り組みの中で、やはり委員ご質問のありましたＣＯ２削減に向けた取り組みは必要だというふうに考えておりまして、温室効果ガス排出抑制のための検討としまして、私ども検討課題を挙げております。","voiceIndex":165,"id":"exchange-072"},{"speaker":"大沢委員","kind":"質問・要望","question":"蛍光灯というのは、ご存じのように白熱灯よりも寿命は長いです。ただしコストが高いという部分がありますけれども、この白熱灯から蛍光灯へ低エネルギー化のために移行をさせるために、電機メーカーや業界団体、また消費団体との連携がとれて、そのような取り組みというのは可能であるのか、もし可能であるならどのような流れの中で行われるのか教えていただきたいと思います。","respondent":"工藤環境課長","answer":"東京都の施策なんですけれども、いろいろと白熱灯一掃作戦ということで、いろいろと施策を打っているところでございまして、当然区のほうもそれを受けまして、そのような考えで進めていきたいというふうに考えております。","voiceIndex":167,"id":"exchange-073"},{"speaker":"大沢委員","kind":"質問・要望","question":"進められるということでお話をいただきました。大きな部分で、省エネ家電についてのことで、これは一番私たちが身近に感じる生活には必要で不可欠なものですけれども、この省エネ家電について、都の事業も踏まえて、区では省エネ家電購入についての何か支援促進の策というのはあるのでしょうか。教えていただきたいと思います。","respondent":"工藤環境課長","answer":"そういった中で、区が今後どのような形で支援するかということになろうかと思います。私どももそういった部分を見守りつつ、今後、購入に際して補助、助成等導入を促進できるもの、そういった部分があるのかどうかという部分を考えていきたいというふうに思っております。","voiceIndex":169,"id":"exchange-074"},{"speaker":"大沢委員","kind":"質問・要望","question":"次の太陽エネルギー見本市等という、こちらのほうの質問に移らせていただきます。ここに「等」とありますけれども、「等」というのはこのグリーン電力活用の事業だと思いますが、例えばしながわエコフェスティバル、防災フェア、まちづくり事業展、この三つで「等」を指すと見てよろしいわけですね。確認をさせていただきたいと思います。","respondent":"工藤環境課長","answer":"対象イベントに関しましては、私ども、エコフェスティバル、防災フェア、まちづくり事業展、この三つを来年度は考えているところです。","voiceIndex":171,"id":"exchange-075"},{"speaker":"大沢委員","kind":"質問・要望","question":"この中でグリーン電力という部分で三つ例が挙げてあります。しながわエコフェスティバルにおいては使用電力量１,０００kW、防災フェアにおいては５００kW、まちづくり事業展においては、これも５００kWということですけれども、このグリーン電力証書によるこの三つのイベントによる使用電力をグリーン化することができるのかどうかを教えていただきたいです。","respondent":"工藤環境課長","answer":"そちらのほうから購入するということですので、実際のところは電力を使う。それと同等な部分をいわゆる販売によって購入するということになります。その購入によって、このイベント等が自然エネルギーを使ってされたというふうにみなされるです。","voiceIndex":173,"id":"exchange-076"},{"speaker":"大沢委員","kind":"質問・要望","question":"購入という言葉とみなされるという言葉を今いただきましたので、ではみなされる部分で、この購入した電力量はどのくらいを見積もりを立てていらっしゃるのか、数字が出ていらっしゃるのであれば教えていただきたいと思います。","respondent":"工藤環境課長","answer":"エコフェスティバルに関しましては１,０００kW分、防災フェアに関しましては５００kW分、まちづくり事業展に関しても同様に５００kW分というふうに考えております。全部で２,０００kW分を購入するです。","voiceIndex":175,"id":"exchange-077"},{"speaker":"大沢委員","kind":"質問・要望","question":"プレスの中に出ていましたので、これは余計な質問だったかと思います。すみません。この証書で購入する、これはわかりやすい制度でありますので、基本的なところをお伺いしたいと思います。この証書で購入する自然エネルギーの種類、１０種類ぐらいあると思いますけれども、これは何かちょっと教えていただきたいと思います。","respondent":"工藤環境課長","answer":"証書の自然エネルギーの種類ですけれども、主なものとしては、今、市場に出回っているというものであれば、風力発電が市場に出回っているものが一番多いです。そのほかに水力、バイオマスという部分も市場に出回っているというふうに聞いております。","voiceIndex":177,"id":"exchange-078"},{"speaker":"大沢委員","kind":"質問・要望","question":"太陽光の次に風力ということですけれども、今バイオマスと言いましたけれども、私はバイオマスについていろいろ調べていることで、これは疑問なので伺わせていただきたいんですけれども、バイオマス発電というのは助燃料としての石炭を使用することが多くてグリーンの電力証書には不向きであるというふうに、私は浅いながらも自分自身の考えの中で結論が出たんですけれども。","respondent":"工藤環境課長","answer":"ただ市場に出回っているという部分に関しましては、なかなか精製が難しいということで、市場に出回っている部分としては少ないというふうに聞いているところです。","voiceIndex":179,"id":"exchange-079"},{"speaker":"大沢委員","kind":"質問・要望","question":"わかりました。近隣の自治体との関係について伺わします。越谷市役所、中野区役所など、このグリーン電力証書によって、庁舎で使用する電力のグリーン化を図っておりますけれども、この取り組みについて、品川区としてではなくて課長のご感想でいいのでお答えいただきたいと思います。","respondent":"工藤環境課長","answer":"今、委員のご質問のほうも、どちらかの地方自治体で利用しているということだと思います。私どもとしましても、そういった形で活用しているという例もとらえておるところでございまして、今後、その動きを注目しています。","voiceIndex":181,"id":"exchange-080"},{"speaker":"稲川委員","kind":"質問","question":"２６９ページ、温暖化対策事業、２７１ページ、マイバッグ運動推進事業、２７５ページ、資源持ち去り防止対策費についてお伺いをいたします。温暖化対策の中の、先ほどもさまざまな委員の皆様から質問がございましたが、太陽エネルギー見本市についてお伺いをいたします。この間いただいた品川区のプレス発表資料を見ながら質問をします。一番身近な自然エネルギーが太陽光エネルギーである。","respondent":"工藤環境課長","answer":"実情としまして今、都内の家庭部門の排出部門というのが前年度から大きく上回っている。そういった部分がございまして、私どもとしましても、家庭部門のＣＯ２の削減対策の必要な柱として位置づける必要がある。そういったところからこの事業を計画したところです。","voiceIndex":184,"id":"exchange-081"},{"speaker":"稲川委員","kind":"質問","question":"この中で実施時期は、このプレスには書いてあるんですが、太陽エネルギーの効果が大きい夏季で土日を含めた連続５日間と限定されているんですが、なぜ夏季だけなのか。これがあと防災センター３階ロビーというところが開催場所になっているんですが、例えば５月に行われるエコフェスティバルですか、そういうところでも、やはりこういうものは区民の目に触れさせるべきだと思うんですが、お伺いします。","respondent":"工藤環境課長","answer":"私ども、夏の連続５日間ということで予定しています。なぜ夏なのかという部分はありますけれども、まずやはり太陽光エネルギーの、一番太陽が降り注いでいる中で、一番そういった部分を実感していただきたい、そういったところで夏にしたです。","voiceIndex":186,"id":"exchange-082"},{"speaker":"稲川委員","kind":"質問","question":"もう１点、この対象者なんですが、区民の多くと言っておりますが、実際に既存の住宅に設置する人を対象者として、これは表に出すべきことではないと思うんですが、実際にこの事業をやるに当たって、既存の住宅に設置をする、施工する方を対象にしているのか、それとも新築、これから建てようという人を対象としているのかを１点お伺いいたします。この２点お願いします。","respondent":"工藤環境課長","answer":"アンケートの件ですけれども、当然来ていただいた方は環境意識の高い方だというふうに私どもは思っておりますので、そういった中でアンケートをとりましたり、我々の環境に関してのイベント等もその中で紹介をしていきたいというふうに考えております。","voiceIndex":188,"id":"exchange-083"},{"speaker":"稲川委員","kind":"質問・要望","question":"ぜひ、進めていっていただきたいと思います。次に、マイバッグ運動推進事業の中にある、当初の説明の中にありましたが、マイ箸運動モデル事業というのがあります。私もこれから購入をしようと考えていますが、お店側がもう既に、店箸というんですか、もう割り箸をやめている店に対しての評価とか、ご努力に対してのインセンティブというか、そういうものがあるかどうか教えてください。","respondent":"工藤環境課長","answer":"そういった中で、マイ箸の取り組みというものも今ホームページ上にアップしまして周知していますので、このマイ箸運動と絡めてＰＲをしていきたいというふうに思っております。","voiceIndex":190,"id":"exchange-084"},{"speaker":"稲川委員","kind":"質問・要望","question":"２７５ページの資源持ち去り防止対策についてですが、もう時間がございませんので、先ほどもこの件について、区の回収が増えたです。地域の方々に聞くと、やはり他県ナンバーが非常に少なくなったということも聞いております。とは言いながら、まだゼロではない。遠くにトラックが見えるというケースもありますので、ぜひこの事業に関しては、これからも継続をしていただきたいと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":192,"id":"exchange-085"},{"speaker":"市川委員","kind":"質問","question":"分担金の内訳というものがあるのでしたら、それもお聞きします。それから、廃プラスチックの分別収集経費の使い方というか、どのような使い方をされるのかお聞きします。それからもう１点は、広報用冊子印刷等という項目が、昨年の４７５万２,０００円から増額となっているんですけれども、この増額の理由についてもお聞きします。","respondent":"秋山資源循環推進課長","answer":"プラスチック容器包装の増の内訳ですけれども、プラスチックの中間処理経費、平成２０年１０月から開始をしたものですので、これは通年化によって増になっているです。","voiceIndex":194,"id":"exchange-086"},{"speaker":"市川委員","kind":"確認","question":"それで品川区の分別収集計画を見ますと平成２１年度の計画は２,００７ｔということですので、計画の半分ぐらいの達成なのかなというふうに読み取れるんですけれども、資源として回収したプラスチック容器包装の状態は非常にいいと資料のほうに書かれておりまして、私たちも京浜島のエコセンターのほうに見学に行きまして、その状態のよいのは確認することができてとてもうれしく思っています。","respondent":"秋山資源循環推進課長","answer":"出していただくについてはきれいなものをということで、このＰＲについては引き続き継続的にいろいろな場面でいろいろな冊子等を使いながら実行していきたいというふうに考えております。","voiceIndex":196,"id":"exchange-087"},{"speaker":"市川委員","kind":"質問・要望","question":"先ほどの２,００７ｔが排出量に対して何％かというような質問なんですけれども、私は排出されるプラスチック容器包装に対しての計画が何％かというふうに聞いたので、全体のごみに対してのお答えだったというふうに今は思うんですけれども、そこのところはまた後でお聞きしたいというふうに思います。今後も普及啓発には努めていただきたいと思いますので、よろしくお願いします。","respondent":"工藤環境課長","answer":"もしどうしても欲しい場合にはお箸を１膳１０円で買ってください、そのときのお箸というのは国産の間伐材を利用したお箸でございました。そのような取り組みを今後も、今回のエコフェスティバル等を含めましてやっていきたいというふうに考えております。","voiceIndex":198,"id":"exchange-088"},{"speaker":"市川委員","kind":"質問","question":"ぜひ間伐材の箸というところも利用を進めるようなＰＲをしていただければと思います。街路樹とかサクラ並木のオーナー制とか、そういう大きな視点でのお考えというのはどうでしょうか。お聞きしたいと思います。","respondent":"工藤環境課長","answer":"ポイントがたまった際の交換する啓発用品に関しましては、今ご提案の趣旨を含めて広く考えていきたいと思います。いずれにしましても、この啓発用品が環境意識の向上を図れるような形で検討してまいります。","voiceIndex":200,"id":"exchange-089"},{"speaker":"市川委員","kind":"提案","question":"よろしくお願いします。それから、ごみ減量の啓発というところで提案をさせていただきたいんですけれども、容器を持っていけば中身だけ買える飲み物の自動販売機というのがあります。区の施設において啓発には役に立つと思いますので、品川区でもぜひ設置の検討を進めていただければなと思うんですけれども、いかがでしょうか。","respondent":"工藤環境課長","answer":"考え方としましては、やはりマイボトルというのが先だと思ってあります。今後検討していきたいというふうに思ってあります。","voiceIndex":202,"id":"exchange-090"},{"speaker":"市川委員","kind":"質問・要望","question":"エコへの関心が高まって、環境にやさしいグッズが増えてきていますので、いろいろなところで十分研究をしていただきたいと思います。よろしくお願いします。健康に留意する家族というのは当然だと思って、それなりのやり方で健康のことは考えているんではないかなというふうに思うんですけれども、あえて家族を含めたという理由について、再度になってしまうかもしれませんけれどもお聞きします。","respondent":"山岡健康課長","answer":"それも家族がやはり基本だと思います。事業所、それからもちろんいろいろな団体もあるんですけれども、そのベースは家族。家族が健康づくりに取り組めば、いろいろな事業所、会社、団体、すべてそこにつながっていくんだと思います。","voiceIndex":204,"id":"exchange-091"},{"speaker":"市川委員","kind":"質問","question":"熱い思いを聞かせていただいて、ありがとうあります。それで、健康でなくてはいけないんだという、そういう行き過ぎた印象を与えないような、健康を害している方たちにも配慮した取り組みというところを進めていってほしいと思っていますので、この辺についてのご見解を伺いたいと思います。","respondent":"山岡健康課長","answer":"そういう意味では、これは皆さんの健康につながれば、当然医療費の削減というところにもつながってくるかと思いますので、その意味でも経費的には２００万円程度の予算ですが、大きく医療費の削減につながっていけばと考えてやるものです。","voiceIndex":206,"id":"exchange-092"},{"speaker":"飯沼委員","kind":"質問","question":"プラマークつきの、廃プラのことについて関連でお伺いをしたいと思います。プラマークつきの資源化が進んで大変うれしいことと思いますけれども、４カ月間で総量が１,１４０ｔということなんですけれども、企業がこの責任を持っているプラマークつきの、廃プラの排出量の総数を把握しているのかどうか、その辺と、資源化量と燃やしている部分との割合がわかったら教えてください。","respondent":"秋山資源循環推進課長","answer":"どのぐらいの量が燃やされているのか、燃えるごみのほうに行っているのかということは、１３％が重量として増えているですし、清掃一部事務組合のほうで工場のバンカー内のごみを調査をしておりまして、そこでの数値ですと、品川工場で約１５％という数字が出ております。","voiceIndex":209,"id":"exchange-093"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区民にどのように資源化を進めていく、アピールをしていくおつもりなのか、その辺を教えていただきたいんです。私としては、これだけのプラマークを燃やすと現在品川区はこれだけのＣＯ２を排出しています、これをここまで減らしていきたいんだというような、明確な、区民がやる気になるような働きかけをしてほしいと思うんですが、いかがでしょうか。","respondent":"秋山資源循環推進課長","answer":"ＰＲに関しましては品川区は戸別収集をしております。冊子のごみリサイクルカレンダー等を毎年全戸配布をしておりますので、そういう中でのＰＲですとか、戸別収集の中で、分別の悪いところには直接職員が指導をするという形でＰＲのほうを進めていきたいと考えています。","voiceIndex":211,"id":"exchange-094"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ、ごみ減量というところも大事ですけれども、地球温暖化の環境の取り組みもこれから広げていかなくてはいけないというところにおいては、ぜひ燃やす、今のごみ行政でどれだけ ＣＯ２が排出されているのかというのを区民にわかりやすく表示をするのと、それを減らしていく方向、特に温暖化防止のところではこれから計画も立てるわけですので、京都議定書の６％削減をするに当たっては。","respondent":"秋山資源循環推進課長","answer":"もちろんごみの発生抑制というのがまず第一に来るのが基本ということはもう言うまでもないことですので、それにあわせてプラスチック類の資源化を私どもはしておりますので、その資源化を進めていく取り組みを区民ともども一緒に進めていきたいというふうに考えております。","voiceIndex":213,"id":"exchange-095"},{"speaker":"高橋委員","kind":"質問","question":"時間でちょっとどうなるかわかりませんが。それが来年度、平成２１年度に指定管理者となったのは、どのような理由からでしょうか。それから、２６５ページの保健所のほうなんですが、医師等とありますが、具体的にどのような方々でしょうか。その方々は、３７１ページに給与明細書がありまして、医療職の（一）から（三）とあるんですが、そちらのどこに当たるのでしょうか。この二つをお願いします。","respondent":"山岡健康課長、平澤品川区保健センター衛生課長","answer":"品川健康センターのほうは平成２１年度の予算では指定管理を実施する関係で、指定管理料の中に、事業運営費とそれから施設の維持管理費、光熱水費等も含めて、これが入ってあります。それから荏原健康センターです。保健センター関係の光熱水費と医師等の賃金についてお答えいたします。初めに保健センター関係の光熱水費ですが、年間で４,０００万円ほどの光熱水費がかかってあります。","voiceIndex":216,"id":"exchange-096"},{"speaker":"高橋委員","kind":"質問・要望","question":"衛生費のほうはそれで、２８１ページの産業振興経費のほうで、現在、阪急が改築中なんですが、特に食品売り場の売り上げが大きかったと。その売り上げ分がどちらに流れたか。それで、先ほどもプレミアム付商品券の話がありましたが、平成２２年度以降、これはちょっと款がもし違ったらあれなんですが、平成２２年度以降もこのような形で続けていっていただきたいのですが、どのような状況かということ。","respondent":"金子産業振興課長、日下部企画財政課長","answer":"緊急経済対策のお尋ねですけれども、これはご案内のとおり今の緊急融資については平成２１年度末、つまり来年の３月３１日で一応今のところは終了する予定ですけれども。ですから、これにつきまして今のところ財源として見込んでいるという状況ではございませんけれども、現在東京都のほうと活用できる内容があるかどうか調整中ですので、今後その辺がはっきりすれば、また財源として見込んでいきたい。","voiceIndex":221,"id":"exchange-097"},{"speaker":"本多委員","kind":"提案","question":"私から２点伺います。２５９ページの母子健康診査費と、２８９ページの海外進出推進事業について伺います。初めに母子健康診査のほうなんですけれども、先ほども出ておりましたマタニティマークの件なんですけれども、社会全体で取り組んでいければと考えています。","respondent":"山岡健康課長","answer":"窓口にその関係のチラシあるいはポスターを貼ってということで、それにとどまっております。何かもっと一般の方に訴えるようなことができれば工夫してまいりたいというふうに考えております。","voiceIndex":225,"id":"exchange-098"},{"speaker":"本多委員","kind":"質問","question":"ぜひ工夫をよろしくお願いいたします。次の２８９ページの海外進出推進事業について伺います。それと、その継続性のある平成２０年度までで実績とされたものもあわせて教えてください。","respondent":"金子産業振興課長","answer":"国際化対応相談員ですけれども、これにつきましては、海外進出を希望する区内製造業にさまざまな進出するに当たってのアドバイス等々、国の習慣等々なかなか難しい日本の文化とは違うものがありますので、そういったもの。","voiceIndex":227,"id":"exchange-099"},{"speaker":"本多委員","kind":"質問","question":"これを続けていく中で、参加する企業の、リピーターといいますか、そういったものも可能なのか、それとあと補助額などについて概要を教えてください。","respondent":"金子産業振興課長","answer":"リピーターというお尋ねは出展助成についてのお尋ねかなと思いますが、これについては今のところ制限はしておりませんので可能です。補助額ですけれども、３分の２を限度としまして５０万円を助成しています。５０万円限度ということです。","voiceIndex":229,"id":"exchange-100"},{"speaker":"本多委員","kind":"質問・要望","question":"先日、区民委員会で東大阪の視察をしたときに、大崎のものづくりの産業支援施設をつくる参考になっている場所のクリエイション・コアを見させていただいたときに、担当者がものすごい熱意で、全部のブースの説明をできるような熱意がありまして、できればそういった、せっかく出る企業に対する通訳等、そういった専門職といいますか、堪能な人材ができるような。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":231,"id":"exchange-101"},{"speaker":"若林委員","kind":"質問・要望","question":"太陽エネルギーのほうは、ちょっと角度を変えまして、この５日間の期間中、この環境情報活動センターというのかな、これはどういうふうな形に、ここにはセミナーをやるというふうに書いてありますけれども、そのほか、要するに５日間、丸々１週間、環境という大きなテーマであの３階のフロアが使われるわけですので、環境情報活動センターがこのことについて、区のほうからどういう要請をしているのか。","respondent":"金子産業振興課長、山岡健康課長、工藤環境課長","answer":"それから三つ目は、定額給付金のチラシを同封するという答弁を先日させていただきましたけれども、この中には４月２０日から販売ということと。各種団体、例えば食品衛生協会等の団体との連携ですけれども、この辺につきましては、当然先ほどの認証制度の中で申し上げたように。そういった中で、また５日間の中で何ができるのかというのは十分検討して。","voiceIndex":233,"id":"exchange-102"},{"speaker":"若林委員","kind":"提案","question":"それからもう一つ、私は従前から、今回どこかに載っていたかなと思うんですが、いわゆる健康づくり推進委員との連携で、地域での公園を使ったそういう健康づくり事業みたいなところも提案をしたりしておるわけですけれども、ここら辺の、その後の検討状況について一言お願いしていただければと思います。それから、環境情報活動センター、ぜひしっかりと行っていただきたいというふうに思っております。","respondent":"山岡健康課長","answer":"公園等を利用した、ですけれども、現在、中心がふれあい健康塾ということで、室内を使った健康体操中心で、雨でもできるということでやっているところです。外でやる部分については今後の検討課題とさせていただきたいと思います。","voiceIndex":237,"id":"exchange-103"},{"speaker":"阿部委員","kind":"質問・要望","question":"乳がん検診についてです。ですので、これは要望です。これは要望です。こころの健康づくりでは、高齢者のうつについてお伺いしたいと思います。そういった子どもたちがどの程度いるのか、その子どもたちに対するアプローチというのはどうなっているのかということを教えていただければと思います。一応確認しておきたいんですけれども、夏季の労務環境に対して何らかの対策はとっているのかということ。","respondent":"吉田品川区保健所保健サービス課長、太田品川区保健センター大井保健相談所長、島袋品川区清掃事務所長","answer":"Ｈｉｂワクチンにつきましてですが、現時点では４月１日からの接種開始というふうに考えております。それで、そのほかにそういうお子さんがいらした場合には、チャイルドステーション事業等もありますので。いずれにしましても、健康状態というのは重要なものですから、清掃作業は労働集約的事業なものですから、そういう意味では体が資本でありますので。その中で昨年は９４件ご相談がございまして、うつあるいは躁病という形につきましては１１件、１２％のご相談がございました。","voiceIndex":240,"id":"exchange-104"},{"speaker":"阿部委員","kind":"質問・要望","question":"高齢期のうつのほうなんですけれども、これは特に予防が大切だと考えています。これは要望です。この把握がなければ、なかなか５歳児全体の発達の状況というのをはかることはできないと思いますので、スクリーニングがないのであれば、ここの部分をぜひ力を入れていただきたいと思いますが、おわかりのことがあればお答えをお願いします。","respondent":"太田品川区保健センター大井保健相談所長","answer":"９８％のお子さんが幼稚園・保育園に通っているということで、それ以外のお子さんについても、もちろんこちらで対応しないということではございませんので、相談があった場合には対応してまいりたいと考えています。","voiceIndex":245,"id":"exchange-105"},{"speaker":"阿部委員","kind":"質問・要望","question":"１３９人、もちろん数は少ないと思いますが、数が少ないからこそ、相談を待つというのではなくて、何かのときにそのお子さんたちの発達の状況がどうであるのか、家庭の状況がどうであるのかというのは、ぜひ積極的なアプローチをかけていただければと思います。これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":247,"id":"exchange-106"},{"speaker":"南委員","kind":"質問・要望","question":"二つ質問したいと思います。これは文科省ですから当然子どもの数字です。そういう状況になっているようなんですけれども、とりわけ大きな原因、深刻な身体的な影響を与えるものの原因の一つに、最近はＰＭ２.５というもの、ごく小さな物質が肺に深く入り込んで健康被害を与えている、こういうことになっているんですけれども、こういう問題についての区の認識をまず伺いたいと思います。","respondent":"工藤環境課長、金子産業振興課長","answer":"こちらのほうは、粒子状物質のうち、さらに小さいものでございまして、呼吸時に気管を通り抜けて気管支や肺まで達するため、健康影響の可能性が懸念されているということは私どもも認識しております。私どもの緊急融資あっ旋の実行件数というお尋ねですけれども、幾つか種類がありますので申し上げますと、先ほど別の委員のところでもご説明しました１１月４日から１月末までに実施しました年末対策特別事業資金。","voiceIndex":252,"id":"exchange-107"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、可能性ということではなく、もっと一歩も二歩も進んだ状況だというふうに思うんですけれども、改めてその点でどうなのかということをちょっと伺っておきたいと思いますし、諮問した結論を早く出すことが今求められていると思うんですね。そういう点で、特にまた中央環状品川線ができ、一般質問でも菊地議員が紹介しましたように交通量の増が２.２倍見込まれる、こういうことになるわけです。","respondent":"金子産業振興課長、工藤環境課長","answer":"こういう国等との、区とのこの制度の乖離といいますか、ご指摘でありますけれども、私どもは区内の中小企業に対して、先ほど申しましたとおり、どういう方法をとればできる限り支援ができるかということで。ＰＭ２.５における品川区の見解ですけれど、私どもも、今、東京都のほうがこの問題について関心を持っておりまして、いろいろと学識経験者により構成される検討会を設置しまして。","voiceIndex":255,"id":"exchange-108"},{"speaker":"南委員","kind":"質問・要望","question":"今やっている大気汚染の対策も長い間かかって、その中には何人もの方々が亡くなられて、そしてようやく費用的な補助は出されたものの、やはり私はこういう経験を見ると早い対策が必要だというふうに思いますので、品川区としてきちんと、ＷＨＯの環境基準に見合う方向で答えを出すように要請をするべきだと思っているんですけれども、その点についてはいかがでしょうか。","respondent":"工藤環境課長","answer":"私どもとしましては、やはり国や都でオーソライズされたものに基づき、区も対応するというのがまず原則だと思います。２３区環境課長会等で、早くこちらの件につきましては解明されるように国等に要請を続けてまいりたいというふうに思っております。","voiceIndex":258,"id":"exchange-109"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それで、あれ、何か知らないうちに聞かなくなったなと思ったんだけれども、高くて使われないというか、使えないという理由等があって、よくよく聞いたら今リボンでも２７０円だ、スーパーでは３００円ぐらいでやっているんだということなんだけれども、区として、ここの部分の黄色い袋はやめようと思っているのか、しょうがないのか、私はこれは、もうだめならだめと言うべきだろうと思うんだけれども。","respondent":"秋山資源循環推進課長、工藤環境課長、藤田道路公園課長","answer":"品川区で戸別回収をしておりますので、カラスに対する被害というのは減っているというふうにこちらとしても認識をしております。マイバッグ推進運動のお尋ねですけれども、現在、参加商店街数が４４、参加店舗数が６００というふうにとらえております。全体計画ですけれども、長期計画上は１５０ｍかける１０年ということで、１,５００ｍほどできればいいかなということで計画をしているものです。平成２０年度が現時点で１１５件ということでございまして、予算が１３５件ですので、現時点で８５％という状況です。","voiceIndex":261,"id":"exchange-110"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"５０商店街が参加をして４４に減ってきて、また４４で落ち着いているということなんだけれども、ではこの部分で、少しでもやはりマイバッグ運動をまた持ち上げていこうとしているのかどうかということは、これから実施計画にうたっていくわけだから、このままずっとこの予算でいくということを、やはり思いがあってやるわけだから、そこはもう一度思いの部分を語ってほしい。","respondent":"福田企画部長","answer":"その前提に立ちまして、３年間のスパンを持つ、この総合実施計画ですが、これは３年間というスパンの中で、全部ではありませんけれども、できるだけ具体的に施策の展開、こういうふうに展開しますと、こういうことをお示ししようと思います。","voiceIndex":266,"id":"exchange-111"},{"speaker":"山路委員","kind":"質問・要望","question":"私のほうからは２５７ページ、環境衛生費の衛生許可および監視指導と食品衛生について、その内容についてお伺いいたします。２点目は２６１ページ、医療等給付費に関連して、区民の方から相談をいただいたんですが、パルスオキシメーターということについてお伺いをいたします。","respondent":"金子産業振興課長、吉田品川区保健所保健サービス課長","answer":"そういう趣旨で、私どもとしましては、金融機関もなかなか貸しにくい状況はあろうかと思いますが、保証協会１００％保証の制度をつくることによって、言ってみれば退路を断つ格好でぜひ区内企業に対して積極的に融資をしていただこう。パルスオキシメーターについてのご説明です。パルスオキシメーター自体は指先に取りつけまして、非常に簡便に血中の酸素の飽和状態をはかることができるものです。","voiceIndex":269,"id":"exchange-112"},{"speaker":"山路委員","kind":"質問・要望","question":"最初の食品衛生の許可と監視についてはご答弁がなかったみたいですが、ここでお伺いしたかったのは、食の安全ということについてお伺いしたい。この返済期間の５年という、これを柔軟的に考えられないかどうか、この辺についてお伺いいたします。","respondent":"平澤品川区保健センター衛生課長、金子産業振興課長、吉田品川区保健所保健サービス課長","answer":"委員お尋ねのＩＳＯにつきましては、おそらく食品衛生法第１３条に指定されております総合衛生管理製造過程認証制度のことではないかと考えております。融資あっ旋の返済期間のことでありますが、私どもいわゆる今回の緊急資金の運転対応のもの、それから従前の運転資金ですね。実際に区内で使用されている方についてですが、人工呼吸器等を使われている方というだけではなくて。","voiceIndex":272,"id":"exchange-113"},{"speaker":"山路委員","kind":"質問・要望","question":"先ほどのＩＳＯ２２０００ですが、自治体として取得するというところまでには行っていないと思うんですけれども、広く考えた場合に、海外進出とかそういうことも考えますと、食品メーカーの啓発、これも今後検討していったらどうかと思いますが、どのようにお考えでしょうか。融資に関しましては、いろいろなケースがありますが、さらに多くの人が活用できるようによろしくお願いいたします。","respondent":"平澤品川区保健センター衛生課長","answer":"先ほどちょっとかなりお高いということを申し上げたんですけれども、こちら新規の登録となりますと１件２３万９,７００円の登録手数料がかります。３年に１回の更新が必要で、９万６,９００円の更新手数料、区内におきましてもかなり大規模なところでしか認証できないです。","voiceIndex":276,"id":"exchange-114"},{"speaker":"西本委員","kind":"質問","question":"２６９ページ、地球温暖化対策地域推進計画策定、それから２８７ページの小規模商店街活力づくり支援事業、それと、しながわの一番店発見プロジェクトについてお聞きいたします。これが２００７年から２０１１年ということで、５カ年でＣＯ２を６％削減という形に目標を掲げられていると思うんですが、その進捗状況をお聞きいたします。","respondent":"工藤環境課長、金子産業振興課長","answer":"そういった中、やはり国や東京都のほうでもいろいろと環境確保条例等でさまざまな改正がなされております。そういった部分と連携しながら、そういった部分を入れながら推進計画をつくっていきたいというふうに思っているところです。商店街の中でこういった事業を実施するには、一番問題になるのはキーパーソンだろうというふうな指摘をアドバイザーのほうから受けてあります。","voiceIndex":279,"id":"exchange-115"},{"speaker":"西本委員","kind":"質問","question":"ですからエネルギーの売買。ですからそこは、行政というのはきっかけづくりはある程度してあげなければいけないと思いますけれども、その後、どう生かしていくかというのはそれぞれの商店でやっていかなきゃいけないことだと思います。その役割分担の中で成果が上がったりというような事例があるのかどうか、それからお考えをお聞きしたいと思います。","respondent":"工藤環境課長、金子産業振興課長","answer":"今ご提案の風車を活用したという部分もありますので、その辺も技術状況によるかと思うんですけれども、風車の中でどれぐらいのエネルギーが生み出せるかという部分もあろうかと思いますけれども。先ほど答弁が漏れまして失礼しました。小規模再生モデル事業の内容ですけれども、一応今のところ１,１００万円を想定していまして、空き店舗対策中心に考えているところです。","voiceIndex":282,"id":"exchange-116"},{"speaker":"川西委員","kind":"提案","question":"二つについては、任意ですから、この年齢層の受診のパーセンテージですね、わかったら教えていただきたい。ですから、この参加された人たちの意見が今度の予算にどう反映されているか、聞かせてください。太陽光見本市なんですけれども、これはこれでもう何回もご答弁聞いておりますから内容を伺っているわけではなく、清掃と関連して提案的な発言になりますけれども、ぜひ聞いておいていただきたい。","respondent":"山岡健康課長、吉田品川区保健所保健サービス課長、矢野品川区保健センター保健サービス課長、工藤環境課長","answer":"予算額は確かに毎年少しずつ増えておりまして、前年度につきましては平日のほうが７３２万円、土曜日のほうが３５２万円ですので。続いて職員教育についてですが、一つは既に実施していますけれども、職員へ知識を啓発するといったこと。保健所は１回に２名の医師ということで、保健相談所のほうは３名体制なんですが。従来やっている部分を１回分私どものほうで環境の視点で対応するです。","voiceIndex":286,"id":"exchange-117"},{"speaker":"林委員","kind":"質問","question":"ダーッとはやっていっちゃうと、もう新型でなくなっちゃう、はやり出して、危ないぞといったときが新型と、僕はそういうふうに受け取ったんですけれども、品川区として、この先生は非常に、職員にも、ほい、これやれ、あれやれという命令を出すような先生らしいので、非常におもしろいお話を聞いたんですけど、これからこの２,７００万円強のお金をどうするかというのを教えてください。","respondent":"吉田品川区保健所保健サービス課長、伊勢危機管理室長、金子産業振興課長","answer":"経費をどういうふうに使うか、それから区としてどういうふうに対応していくかですが、区としては、対象者としては３本。新型インフルエンザを想定した実践的な訓練を、現在取りまとめ中の事業継続計画をもとにいたしまして、これの検証とか実践的な訓練を全庁的にやる予定です。観光協会との関係なんですけども、ご指摘の観光課を設置することで観光協会を取り込んでということがありますけれども、これは私どもの認識とは違いまして。","voiceIndex":292,"id":"exchange-118"},{"speaker":"堺委員","kind":"提案","question":"それからお時間がございましたらＡＥＤの設置ということについてお伺いをさせていただきたいと考えています。重ねて昨年第１回定例会でも、この件についても触れたわけですけども、そういう流れの中で、現在、この太陽光発電システムの設置状況というんですか、取り組み状況といいましょうか、現況についてわかる範囲の中で、お答え可能な範囲の中でお知らせいただければと思います。","respondent":"工藤環境課長","answer":"今の状況で記憶しますところ、日本全国で２０万、３０万というふうに聞いております。普及率に関しましては、多い県で、いわゆる九州地方で２％ぐらい普及されている県があるというふうに聞いておりますけれど、都心部に関しては１％を切っているような状況です。","voiceIndex":297,"id":"exchange-119"},{"speaker":"堺委員","kind":"質問","question":"この場ではなかなか、環境課長のほうからは難しいのかもしれません。私は区全体の区有施設といいましょうかね、それがどういうふうな形で活用、利用されているのかということをお尋ねしたわけですが、それは大丈夫ですか。","respondent":"工藤環境課長","answer":"区有施設での設置状況ですけれど、私ども把握しておりますのがいろいろとございまして、例えば防災センターの３階のロビーに照明をやっていましたり、戸越台の複合施設、品川区保健センター、しながわ中央公園の管理棟、あと学校等、このような形で私ども把握しています。","voiceIndex":299,"id":"exchange-120"},{"speaker":"堺委員","kind":"提案","question":"かなり区としても積極的に推進していただいているというふうに理解をするわけですが、この件に関連しまして、今年の１月３０日の衆議院の本会議で、我が党の代表が、世界は低炭素化競争の時代に突入したという、化石燃料社会から太陽光などクリーンエネルギー社会へ大転換が図られようとする今、太陽光発電の全小中学校への設置などを目指すとともに、住宅の断熱化・省エネ家電の普及、電気自動車。","respondent":"工藤環境課長","answer":"可能な限りやっているところです。今、学校のほうに関しましても、小中一貫校、第一日野小学校、第三日野小学校ということで取りつけを行っている、設備の設置に当たりまして計画に入っているところです。","voiceIndex":301,"id":"exchange-121"},{"speaker":"堺委員","kind":"提案","question":"２点目につきましては公共施設の緑化ですが、これにつきましても、先般みどりの条例ができました。そういうこの緑化については、我が党は昭和６０年の予算特別委員会のときに、学校のフェンス化に伴って、フェンスにつる性の植物をはわせる、垂直緑化とか壁面緑化、こういったものを実現して、夏も冬も緑の創造に寄与するように努めていただきたいと、このような提案をさせていただきました。","respondent":"藤田道路公園課長","answer":"今回こちらのほうに計上させていただきました公共施設屋上等緑化調査委託ですが、これまでも緑化に対することは積極的に区として取り組んできてまいったわけですが、建物等に関しての緑化は、強度的な問題ですとかいろいろありますので、建て替え。","voiceIndex":303,"id":"exchange-122"},{"speaker":"堺委員","kind":"質問・要望","question":"ぜひ区全体の緑化ということで、積極的に取り組んでいっていただきたいと思います。それから、３点目のＡＥＤの件です。今回、できれば公衆浴場、区ではしながわ出会いの湯とかやっております。多くの方々が集まるそういう場にも、ぜひ浴場組合等とも協議しながら、そういうところにもＡＥＤを設置していただきたいと思いますが、区のご見解をお聞かせいただければと思います。","respondent":"山岡健康課長","answer":"組合とお話し合いをできればというふうに考えております。","voiceIndex":305,"id":"exchange-123"},{"speaker":"須貝委員","kind":"質問","question":"２８２ページの中小企業対策費について、まずお聞きしたいと思います。商店数も減少傾向にあるというお話でしたが、この数は、廃業や倒産してから廃業届等を提出した企業だけの数ですか。後でこれをちょっと教えてください。ではその運転資金はどうしているんですかとお聞きしますと、皆さんご自分の預金を取り崩したり、年金を使ったりして企業を存続させているという実態を聞いております。","respondent":"金子産業振興課長","answer":"折に触れ、こういったところとの意見交換を進んでするようにしておりまして、こういったところで現況というのは把握するように努めてあります。","voiceIndex":308,"id":"exchange-124"},{"speaker":"須貝委員","kind":"質問","question":"それで、ちょっとお聞きしたいのですが、産業振興を進める事業部、産業振興課なんですが、中小企業対策についてですけれども、今回の事業内容で、区内の大半の企業を守れるんですか、存続させられるんですか、それをお聞きしたい。ですが、公共の建設事業に対しては、主な予算は区外に本店のあるゼネコンにほとんど流れていくというのはしょうがない、建てられないのですから実態はそうなっております。","respondent":"金子産業振興課長","answer":"もちろん今後どういうふうに続くか見えない部分が多いですけれども、今後とも区内中小企業に対して取り得る施策というのは、研究しながら状況を見て検討していきたいというふうに考えてあります。","voiceIndex":310,"id":"exchange-125"},{"speaker":"須貝委員","kind":"意見","question":"今回、経済対策、もちろんわかるんです。ですが、何が一番効果があるんだ。じゃあ何ができるんだ。前にも言いましたが、５２億円の定額給付金を出して、実際２億円しか販売しない。そうすると４％の人しか買えない。そういうのではなくて、今せっかく国がやってくれているなら区もやはり同調して、私は何とか手に入るように工夫すべきじゃないかな。最後に一言ありましたらよろしくお願いいたします。","respondent":"宮地区民生活事業部長","answer":"もう当然承知しておりますが、何にしても早く動くことと考えております。先ほどの緊急経済対策にしても臨時議会を開いていただきました。そういう中で一歩でも素早く動くというようなことを今後とも進めていきたいと考えております。","voiceIndex":312,"id":"exchange-126"},{"speaker":"須藤委員","kind":"質問","question":"産経費で、４、５日前にテレビ朝日で戸越銀座商店街が映っていて、今、商店の経済動向どうだというのでアナウンスをしていましたけども、見た人いますか。誰も見てくれなかったけれども、３月ぐらい、この１２月まで落ちたんだけれども、１月、２月で少しずつ上がってきました。２９１ページ、勤労者共済会運営補助、これはどのくらいの数の人たちが入って、どんなことをやっているか教えてください。","respondent":"金子産業振興課長","answer":"勤労者共済会のお尋ねです。共済会、現在会員につきましては、事業所数で申し上げますと２,２７９、会員数で申し上げますと６,６２７の会員で運営されているものです。","voiceIndex":315,"id":"exchange-127"},{"speaker":"須藤委員","kind":"質問","question":"会費がどの程度で、どんなことをされているのか、どういう恩恵があるのか、そのあたりがわかったら教えてください。","respondent":"金子産業振興課長","answer":"それからもう一つは、さまざまな福利厚生に関する事業を行うということで、例えば年間６回ほどだったと思いますがバス旅行、あるいはさまざまなエンターテインメントの施設への割引券等々の事業を行って、区内の中小企業の勤労者の方の福利厚生を実施している。","voiceIndex":317,"id":"exchange-128"},{"speaker":"須藤委員","kind":"質問","question":"続いて２８９ページの海外進出推進事業。これは内容的には先ほど本多委員のほうで質問しましたので、この事業と、品川区にあります国際友好協会等々の関連はなされているのかどうか。４月から組織改正で協働・国際担当というのができてくるんだけれども、そういったところとの連携はどんなふうに考えていらっしゃるのか、教えてください。","respondent":"宮地区民生活事業部長","answer":"これからの連携ですけれども、まさにこれから４月ということですので、従来ありましたそれぞれの課題等を含めまして、今後のあり方を至急検討していきたいというふうに考えております。","voiceIndex":319,"id":"exchange-129"},{"speaker":"須藤委員","kind":"質問","question":"せっかく協働・国際担当というのをつくっているので、そのあたりの情報もやはりしっかり同じ部内ですから取り合って、いい形をつくっていただければと思います。午前中からずっと、午後の答弁を聞いていて、うーんと思っちゃうのが幾つかあるんだけれども、まず担当課長、健康というのはどういうふうに考えていらっしゃるんでしょうか。健康とは何ですか。","respondent":"山岡健康課長","answer":"これはまさに、体も心も十分に生き生きと生かせるような状況、これを健康というふうに考えているものです。","voiceIndex":321,"id":"exchange-130"},{"speaker":"須藤委員","kind":"質問","question":"その健康というものを、ここで宣言、認証制度をしますよというのは、そのトップ、区長なら区長が顕彰する、何かやるんだろうと思うんだけれども、品川区の職員の健康状態はどうですか。前の総務費のほうで聞いたら、多くの病気でこういう方が今休んでいますというような報告もいただいていますよね。そのあたりというのは、どういうふうに考えているんですか。それはどうやって取り入れようとしていますか。","respondent":"山岡健康課長","answer":"要するに区役所も対象にしてまいりたい。そういうふうに考えているところです。","voiceIndex":323,"id":"exchange-131"},{"speaker":"須藤委員","kind":"質問","question":"それから幼稚園に入ります、保育園に入ります、学校に行きます、そういった成長過程のところと、うちの健康課のほうと、どういう連携をとっているんですか。それが本当に連携した仕組みでなければならないと思うんだけども、区民の健康ということをお考えになるなら、その教育委員会との連携はどういうふうになさっていますか。ただお話し合いをしてますよというだけなのか、そのあたりをお聞かせください。","respondent":"山岡健康課長","answer":"そういうところとは、当然情報交換をしながら、さらによりよいものをつくっていけるような形を考えているところです。それから、先ほどの認証制度のところで申し上げますと、それぞれのところで学校も含めて取り組んでいるところもあれば、当然認証の対象にしてまいりたい。","voiceIndex":325,"id":"exchange-132"},{"speaker":"須藤委員","kind":"質問・要望","question":"健康は非常に我々が気にするところでもあるし、また重いテーマだと思うので、本当にしっかり足をつけていかないと、ともすれば、これがこうだよ、例えばよくテレビでココアがいいよと言うとバーッとココアが売れちゃうとか、ネギがいいよと言うとネギが売れちゃうとか、そんな流れで、こっち右だ左だみたいな軽々なあれではなくて、考えていただいて、健康問題に取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":327,"id":"exchange-133"},{"speaker":"土井委員","kind":"質問・要望","question":"それから２３区の清掃一部事務組合の分担金のところで、公債費が増えたというようなお話があったわけですけれども、たしかいままでのあれの中では、ダイオキシン対策のところなどは都が出すよというスタイルでやっていましたし、これは通常の意味でのいままでの建て替え等の公債費が残ってきたのか。","respondent":"工藤環境課長、秋山資源循環推進課長、金子産業振興課長","answer":"バーチャルエコ住宅に関しましては、今年度ぎりぎりになりますけれども、３月末までにホームページ上にオープンする予定になっております。清掃一部事務組合の分担金ですけれども、公債費につきましては過去の建て替え、それからダイオキシン対策も含めてですけれども。ご指摘のように新製品、新技術、今年も約２,０００万円の予算をもって実施いたす予定ですけれども、このほかにも国内展示会の出展助成。","voiceIndex":329,"id":"exchange-134"},{"speaker":"土井委員","kind":"質問・要望","question":"２３区の清掃一部事務組合の後ですが、たしかダイオキシン対策のときは、ダイオキシン対策のようなものは２３区に渡しちゃったらできないだろうというような意味だったのかどうかわからないけれども、東京都がそこまではやりますよというような話だったと思うので、それが公債費を請け負っちゃいけないのではないかなという気がしないでもないんだけれども、そこら辺はどうなんでしょうかという意味です。","respondent":"秋山資源循環推進課長","answer":"平成１２年度以降に発行したものもありますので、それも含めてということになるのではなかろうかと考えております。","voiceIndex":333,"id":"exchange-135"},{"speaker":"宮崎委員","kind":"確認","question":"保健所と保健センターのこの手引きについて伺いたいと思います。初めに、この手引きについて伺いたいんですけれども、今回の議会に、墓地に関する陳情が出てきて、私もこういう事態になっているのかなというのは知ったんですけれども、改めて区は行政としてどういうふうに対応していくのかということをちょっと確認しておきたいと思います。","respondent":"荒井品川区保健所衛生課長","answer":"平成１２年度に都が条例を改正いたしまして、墓地建設に当たりましては、隣接住民と、それから申請者との間でトラブルを防止するために、許可申請に先立って事前に十分な周知をするようにということで、事前周知制度を導入したというふうに認識しています。","voiceIndex":336,"id":"exchange-136"},{"speaker":"宮崎委員","kind":"質問","question":"それと、通常マンション紛争なんかですと、住民側との間で協定書というのを結んで、それで話が一件落着ということになるんですけれども、この手引きのところでは、協定を結んだ場合は添付義務というのがあるんですけれども、この協定書、協定を結ぶということそのものについては、保健所というか、行政のほうはどういうふうな指導をするんでしょうか。","respondent":"荒井品川区保健所衛生課長","answer":"協議につきましては、事前周知制度の中に、標識の設置および隣接住民への説明会、その説明会に基づいて隣接住民の方たちが意見申し出というのを保健所長に行うことができます。","voiceIndex":338,"id":"exchange-137"},{"speaker":"宮崎委員","kind":"質問","question":"今の最後のご答弁のところだと、なかなか基準がよくわからなくなってくるんですよね。協定書を結べば、それははっきりするんですけれども、そのとり方といいますか、それで変わってくるということが一つ心配なんですけれども、そういう点ではどうなのかということをお聞きしたいと思います。今回の陳情のケースですと何項目ぐらい出てきているのか。","respondent":"荒井品川区保健所衛生課長","answer":"新たに出てきたものということですが、やはり住宅街の中に墓地をつくるということであれば、近隣住民の方たちとのできるだけいい関係をつくっていただきたいということで、申請予定者のほうには、できるだけ協議に乗るようにという指導をしてまいるところです。","voiceIndex":340,"id":"exchange-138"},{"speaker":"宮崎委員","kind":"質問・要望","question":"狭い土地に３０２基なのでかなりの人が出入りするようになるのかなというふうに思うんですけれども、当然住民が、いろいろとそういういっぱい人が集まるということを心配しているんですけれども、そういう点で区はどういうふうに考えているのか。設置予定者、申請予定者には、そういうようなところで地理的な条件等も何か考えているところはあるのか、そこのところはどうか、お聞かせいただきたいと思います。","respondent":"荒井品川区保健所衛生課長","answer":"墓地ができると人が集まる、あるいは交通量が多くなるのではないかというご心配ではないかと思いますが、その件につきましては、申請予定者のほうに十分にそういった配慮をするように指導していく予定です。","voiceIndex":342,"id":"exchange-139"},{"speaker":"宮崎委員","kind":"意見","question":"先ほど協議の内容としては、いろいろ基準がありましたけれども、その中で都会にふさわしい墓地、都会の墓地にふさわしい、そういうことで協議をしてほしい、そういうことだと思うんです。大体４５cmかける４５cmがかなりいっぱいあるとか。墓石の業者に聞いてもそれは最近なんだということなんですけれども、このお墓が小さくなってきたというのは、行政側はどういうふうに受けとめておられますか。","respondent":"荒井品川区保健所衛生課長","answer":"お墓の大きさにつきましては、保健所が判断するところではございませんので、ご了解いただければと思います。","voiceIndex":344,"id":"exchange-140"},{"speaker":"宮崎委員","kind":"質問","question":"そこで、いわゆるお墓事情ということをどういうふうに受けとめているかということを聞いているんですね。いままで要するに東京都の条例をつくったときには、こういうふうな小さいお墓が出てくるということは私は想定していないんじゃないかという気がするんですけれども、そういう角度から聞いているんですけれども、どうでしょうか。","respondent":"荒井品川区保健所衛生課長","answer":"保健所といたしましては、あくまでも公衆衛生上の観点からお墓の構造について設備基準に基づいて判断していくということになってありますので、ご了解いただきたいと思います。","voiceIndex":346,"id":"exchange-141"},{"speaker":"宮崎委員","kind":"質問・要望","question":"先ほど答弁がありました。そういうことじゃないんですか。ですから、これはちょっと、そのお墓の大きさというのは、そこの限られた土地の中に幾つつくれるか、そういう問題ですから、これは今の答弁というのは私はちょっと納得できない。考えがあったらお聞かせいただきたいと思います。今回の事態も私は新たな事態だと思うんですけれども、改めて伺いたいと思います。","respondent":"古川児童保健事業部長","answer":"あくまでも都条例に従った今後の指導の範囲の中で、最終的には墓地の設置基準等を勘案しながら最終的な判断をしていく、こういう段階ですので、現時点においては指導をしているということでご了解いただければと思います。","voiceIndex":349,"id":"exchange-142"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、これは一番先にご答弁がありましたけれども、人の出入りあるいは車の数とかこういうところは、それはそれで指導していくということでありますので、このお墓の数の問題というのは、それとまさに連動している問題だというふうに思います。新しい事態なんだということ、そういう事態だということを踏まえた対応をぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":351,"id":"exchange-143"},{"speaker":"三上委員","kind":"質問・要望","question":"ただ、日程的に考えますと、夏の暑い盛りというと、これはどこでも企画する話であって、今申し上げたような話にしても、遅くなればなるほど、どこに声をかけても何も手に入らない、こういうことにもなりかねないということですから、ぜひともそういうふうなことを考えながら、ソーラービークルという、要するに太陽電池を利用した子どものおもちゃのようなもの、それをつくらせるようなことを含めたり。","respondent":"工藤環境課長","answer":"ちょっと先ほども申し上げたんですけれども、ソーラークッカーですね、太陽光の集熱炉を用いたものとか、子ども対象に、先ほど言いましたミニチュアソーラーカー等の工作という部分もあるというふうに聞いておりますので、そういった部分で。","voiceIndex":353,"id":"exchange-144"},{"speaker":"三上委員","kind":"質問","question":"よろしくお願いしたいと思います。次に、まず一つは環境衛生費の中で、最近私のところの周辺では夜中にカラスがさえずるのか鳴いているのか、過去はずいぶんあったんです。こういう状況を考えたときに、かなり公園にしても歩道上にあっても、そういうようなハトのふん害、そういうことで、ハトのふん害での影響というものは人体的にあるのかないのか、どういうふうに今言われているでしょうか。","respondent":"工藤環境課長","answer":"その中でハトのふん害等の相談というのも年に数件寄せられておりまして、その場合には、東京都環境局のほうがいろいろとポスター等をつくっておりまして、そういった部分を貼っていただくとか、そういった形で対応しています。","voiceIndex":355,"id":"exchange-145"},{"speaker":"三上委員","kind":"質問","question":"ハトのふん害について、ポスターを貼ってもふん害はなくならないですよね。ちょっとホームページをいろいろ引っ張り出したら、ハトのふんで洗濯物が干せなかったり、においや汚れの被害などで悩んだり、毎日が憂鬱になっている人も多い。ですから、そういった対策をやはり真剣に取り組んでいっていただくという、そういう窓口も必要ではないかと思いますが、いかがでしょうか。","respondent":"荒井品川区保健所衛生課長","answer":"ハトの被害については個々に保健所でもお受けすることがあります。その場合につきましては、におい消しみたいな、そういったものをお渡ししたりして、当面は様子を見ていただくというような形で対応しています。","voiceIndex":357,"id":"exchange-146"},{"speaker":"三上委員","kind":"質問","question":"よろしくお願いします。続いてリサイクルのほうのレアメタルについてちょっとお伺いします。ある人に言わせると、日本の都市にある金は約６,８００ｔ、世界の埋藏量の約１６％に達するという、そういうデータも出ておりますけれども、そういった点での今後の取り組みとして方向性をどういうふうにお考えなのか、ちょっとお伺いします。","respondent":"秋山資源循環推進課長","answer":"回収ボックスを大学それから自治体、駅等において回収をしています。東京都が中心となった活動ですけれども、小型電気製品につきましても、こういう東京都のリサイクルの内容も含めて、参考にしながら研究していきたいというふうに考えております。","voiceIndex":361,"id":"exchange-147"},{"speaker":"三上委員","kind":"意見","question":"今後そういった点で、しっかり取り組んでいただくようご検討をお願いしたいと思います。はだしで、両手をこう載せる場所がある。おでこのところに２カ所電極をつけるというようなことで、それで身体機能についてのいろいろな微少電力を流しながら測る。それから、パンデミックサミットということで、３月４日、東京フォーラムで参加してきて、そこでいろいろなことがありました。","respondent":"吉田品川区保健所保健サービス課長","answer":"それについて、現在ご希望のあるところには啓発を行っていたところですが、今後はさらにネットワーク等を活用できるような環境を整備して、事業所の皆様でご検討いただける場を区としても検討していくというふうに考えてあります。","voiceIndex":363,"id":"exchange-148"},{"speaker":"三上委員","kind":"質問・要望","question":"これが危機管理ということでしょうから、そういうことに対して、やはりこれは指揮をとる人がその決断というものをどう早く下すかということが大事だと言われてまいりました。各家庭にしてもそういうことですから、そういう瞬時にどう判断するかということについてのご検討を、しっかりやはり訴えていくような仕組みというものを考えていっていただきたいとお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":365,"id":"exchange-149"},{"speaker":"鈴木（真）委員","kind":"質問","question":"最後に私からは、環境対策費２６９ページが主に入りますけれども、それから区としての環境対策という意味で、区有施設に関してちょっとお聞きしたい点、全体的にこの辺から質問をさせてもらいたいと思います。ですから、そういうところがどの程度進んでいるのか。この辺でまずどういうふうにやっていらっしゃるか、ちょっと教えてもらえたらと思います。","respondent":"工藤環境課長","answer":"当初１年目は、学校の参加校が２２校、人数で言いますと２７８名でありましたが、年々参加する方が増えておりまして、平成２０年度は３７校全校、２,０８０の家庭で実施されているところです。","voiceIndex":367,"id":"exchange-150"},{"speaker":"鈴木（真）委員","kind":"質問","question":"日本は別ですよね。区の施設の中で、私も本会議の質問の中で、区の一事業者として平成１８年比１.５２％の温室効果ガスの削減をしたというお答えをいただきました。最初の初期投資はちょっとかかるかもしれませんけれども、区の施設の中でもそういうのができる部分があるように何か変わってきたということを聞いたんですけれども、その辺、何か施設の状況がわかることがありますでしょうか。","respondent":"宍戸施設担当課長","answer":"環境にもやさしくランニングコストがゼロである。しかもメンテナンスフリーということで、法の縛りがありますけれども補助的に設けるというふうなことでは可能かなというふうに思っております。都南病院跡地の高齢者施設でも、補助的な部分ですけれども採用したところです。","voiceIndex":369,"id":"exchange-151"},{"speaker":"鈴木（真）委員","kind":"意見","question":"地下へおりていくときに。ＣＯ２の削減ということもできれば、どこまで可能なのかわかりませんけれども、少し検討の材料になるのではないかと思いますので、その辺はそれこそ検討していただければと思います。それと同時に、二つ分かれたことによって、防災まちづくりとこちらの都市環境事業部とのつながりというのをもう一度、環境に対する思いという意味でお答えをいただければと思うんですけれども。","respondent":"久保田環境清掃事業部長","answer":"まちづくりというのはやはり実践の部隊というか、いわゆる具体的にいろいろな実践をしていたところもあるだろうということで、これも二つが融合すること、あるいは一緒になることによって。","voiceIndex":371,"id":"exchange-152"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=918#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":119690,"voices":373}}]);
